# Ported from the upstream mirror's Server Script "wm_payment" (API) — logic unchanged.
# Farms / projects / company / approver roles now come from Work Management Settings
# and the Work Management Farm doctype — see work_management/api/config.py.
# REGENERATED by the mirror's port_app.py — edit the mirror script, not this file.

import json

import frappe

from work_management.api.config import get_config


@frappe.whitelist()
def wm_payment(**kwargs):
    _cfg = get_config()
    FARM_PROJECT = _cfg["farm_project"]
    DEFAULT_COMPANY = _cfg["default_company"]
    FARMS = _cfg["farms"]
    BLOCK_EXCLUDE = _cfg["block_exclude"]
    FARM_APPROVER_ROLE = _cfg["farm_approver_role"]
    HR_HEAD_ROLES = _cfg["hr_head_roles"]
    STAGE_ROWS = _cfg["stage_rows"]
    STAGE_STATES = _cfg["stage_states"]
    CAPABILITIES = _cfg["capabilities"]
    ALLOW_CONCURRENT_PLANS = _cfg["allow_concurrent_master_plans"]
    ALLOW_SPLIT_DAY = _cfg["allow_split_day"]
    STANDARD_DAY = _cfg["standard_day"]

    # ==================================================================
    # Master plan attribution: none. Every period_from/period_to in this script is
    # the PAYMENT's own pay period -- the week a run covers -- not a master plan's.
    # Nothing here attributes work to a budget, so nothing changed when a farm became
    # able to hold two plans over the same days. Checked line by line rather than
    # assumed.
    # SERVER SCRIPT — "WM Payment" (API, api_method=wm_payment)
    # Powers: Planner + Assigner (a_) + Actuals (act_) + Payment (pay_) + dash
    # Multi-block planner (Option A) + fast grouped-query dashboard.
    # ==================================================================

    # How long a full day is, and the denominator every man-day figure divides by.
    # Sunday is worked on these farms, so it is a full day and not zero -- a zero
    # would divide by nothing on every Sunday row.
    #
    # This was three loose constants, declared in five scripts and read in one. It is
    # one value now because port_app.py strips it and rebuilds it from get_config(),
    # so a site that works a six-hour Friday can say so in Work Management Settings
    # instead of it being compiled in. Mirrors work_management/split_day.py, which is
    # unit-tested; keep the two in step.

    # WHO THIS SYSTEM PAYS
    # Task work only. Permanent, Contract and Temporary staff are salaried and paid
    # through payroll, so their recorded work must never turn into a payment here.
    # The row's own employment_type column cannot be trusted for this -- every row
    # carries "Task Worker" regardless of the Employee master -- so the test always
    # reads tabEmployee.
    # An employee qualifies if ANY of the three configured lists matches. A blank
    # employment type on a new hire therefore does not quietly make them unpayable.
    # Each list is a picked child table now -- the free-text boxes they used to be
    # are gone, so there is no character check to make: a Link target or a Select
    # option is a docname, not typing, and an apostrophe in a designation is not a
    # hazard.
    TW_SOURCES = [
        ("employment_type", "Work Management Payable Employment Type", "employment_type"),
        ("designation", "Work Management Payable Designation", "designation"),
        ("custom_category", "Work Management Payable Category", "category"),
    ]
    # Only the Employee columns THIS site actually has. employment_type and
    # designation are standard; custom_category is a custom field one site created,
    # and naming a column the site has not got does not narrow the query, it kills
    # it -- (1054, "Unknown column 'twe.custom_category' in 'WHERE'") took a whole
    # screen down on a site that never had the field. frappe.db.has_column is not in
    # the sandbox's globals, but the meta is, and it knows custom fields too.
    TW_META = frappe.get_meta("Employee")
    TW_COLUMNS = []
    for tw_mc in ("employment_type", "designation", "custom_category"):
        if TW_META.get_field(tw_mc):
            TW_COLUMNS.append(tw_mc)

    TW_CLAUSES = []
    for tw_col, tw_child, tw_cfield in TW_SOURCES:
        # the three lists are ORed, so dropping the column this site lacks costs
        # nothing -- there is no Settings list it could have matched anyway
        if tw_col not in TW_COLUMNS:
            continue
        tw_vals = []
        # frappe.get_all() on a doctype this site does not have raises rather than
        # returning nothing, so ask before looking.
        if frappe.db.exists("DocType", tw_child):
            for tw_r in frappe.get_all(tw_child,
                    filters={"parenttype": "Work Management Settings"}, fields=[tw_cfield]):
                tw_p = str(tw_r.get(tw_cfield) or "").strip()
                if tw_p:
                    tw_vals.append("'" + tw_p.replace("'", "''") + "'")
        if tw_vals:
            TW_CLAUSES.append("twe." + tw_col + " IN (" + ", ".join(tw_vals) + ")")
    if not TW_CLAUSES:
        # never leave the gate wide open if Settings is blank or unusable
        TW_CLAUSES = ["twe.employment_type = 'Task Worker'"]
    TW_ONLY = (" AND EXISTS (SELECT 1 FROM `tabEmployee` twe WHERE twe.name = we.employee"
               "             AND (" + " OR ".join(TW_CLAUSES) + "))")

    # PAYROLL CHECK (2026-11-12). HR picks the dates to pay; each farm manager
    # fixes and approves their farm, then HR, then the GM. A worker-day joins a
    # check (Work Actuals Employee.payroll_check) when its farm is approved, and
    # belongs to that check for good. With the Settings switch on, only rows in
    # an Approved or Sent check are payable -- appended to every selection of
    # payable work, the way TW_ONLY is. Off (or no doctype): empty, and payment
    # behaves exactly as before.
    PC_DT = 1 if frappe.db.exists("DocType", "Work Management Payroll Check") else 0
    PC_GATE = 0
    if PC_DT:
        pc_sw = frappe.db.sql("""SELECT value FROM `tabSingles`
            WHERE doctype = 'Work Management Settings' AND field = 'payroll_check_required'""")
        PC_GATE = frappe.utils.cint(pc_sw[0][0]) if pc_sw else 0
    CHECKED_ONLY = (" AND EXISTS (SELECT 1 FROM `tabWork Management Payroll Check` pchk"
                    " WHERE pchk.name = we.payroll_check AND pchk.status IN ('Approved', 'Sent'))") if PC_GATE else ""

    # WHO MAY SEND WORK TO ACCOUNTS
    # Sending creates the payment record and commits the money, so it is limited to
    # the HR head, accounting and the general manager. Everyone else can review and
    # audit; the buttons are hidden for them and the actions refuse server-side, so
    # hiding the UI is not the only thing standing between a farm clerk and payroll.
    send_role_list = frappe.db.get_all("Has Role", filters={"parent": frappe.session.user}, pluck="role")
    CAN_SEND = 1 if "System Manager" in send_role_list else 0
    # Who may do what, beyond approving. In the app, port_app.py strips this and
    # rebuilds CAPABILITIES from get_config(), so it is whatever Settings holds. Here
    # it is what this site has always allowed -- these were four lists compiled into
    # the code, naming this company's job titles, so a farm could say who approves a
    # plan and not who may change a rate.

    for sr in CAPABILITIES.get("send_payment") or []:
        if sr in send_role_list:
            CAN_SEND = 1

    # WHAT ONE SEND COVERS
    # Pay weeks always. A range of days as well, when Settings offers it -- one day,
    # five, a fortnight, up to a month. Whether a range may be sent at all is a
    # Settings decision; what this particular send covers is the operator's, so it
    # arrives as the `days` parameter and Settings only says whether it is allowed.
    # Ticking the box changes nothing on its own: a send that asks for no range
    # still groups into pay weeks, exactly as payroll has always received them.
    # A bad ask is refused rather than rounded into something sendable -- paying a
    # range nobody chose hands payroll documents covering the wrong dates, and a
    # payment already sent is the expensive thing to undo.
    MAX_SPAN_DAYS = 31


    def wmpay_span(wsp_anchor):
        """{"days": 0 for the pay week or 1..31, "error": message or ""}."""
        wsp_raw = str(frappe.form_dict.get("days") or "").strip()
        if wsp_raw in ("", "0"):
            return {"days": 0, "error": ""}
        if not frappe.utils.cint(frappe.db.get_single_value(
                "Work Management Settings", "allow_day_range")):
            return {"days": 0, "error": ("Sending a chosen range of days is switched off. Tick "
                                         "\u201cAlso allow sending a chosen range of days\u201d in "
                                         "Work Management Settings to use it.")}
        wsp_n = frappe.utils.cint(wsp_raw)
        if wsp_n < 1:
            return {"days": 0, "error": str(wsp_raw) + " is not a number of days to cover."}
        if wsp_n > MAX_SPAN_DAYS:
            return {"days": 0, "error": ("One payment can cover at most " + str(MAX_SPAN_DAYS)
                                         + " days; " + str(wsp_n) + " were asked for.")}
        # A range longer than a day has to be tiled from somewhere. Choosing the
        # anchor here -- today, or each worker's earliest work date -- would put one
        # day on different payments for different people, and re-running the same
        # send later would draw the boundaries somewhere else.
        if wsp_n > 1 and not wsp_anchor:
            return {"days": 0, "error": ("Choose the date range first -- a span of " + str(wsp_n)
                                         + " days has to start somewhere.")}
        return {"days": wsp_n, "error": ""}



    # STAND-INS AND TWO PAIRS OF EYES (2026-11-12). Nobody approves their own entry,
    # and nobody takes two steps on one record. When the usual approver is the one
    # who already acted, a stand-in listed in Settings takes the step -- they may
    # take it without holding the step's role. A System Manager may override with a
    # reason, which is logged on the record and raised in the payroll check.
    WMG_SI = []
    if frappe.db.exists("DocType", "Work Management Approval Stand In"):
        for wmg_r in frappe.db.get_all("Work Management Approval Stand In",
                filters={"parenttype": "Work Management Settings", "user": frappe.session.user},
                fields=["stage", "farm"]):
            WMG_SI.append((wmg_r.stage, str(wmg_r.farm or "").strip()))


    def wmg_si(stage, farm):
        """1 when this person is a listed stand-in for `stage` on `farm`."""
        for wmg_s in WMG_SI:
            if wmg_s[0] == stage and (not wmg_s[1] or wmg_s[1] == str(farm or "").strip()):
                return 1
        return 0


    def wmg_step_err(stage, farm, others, doctype, name):
        """The refusal when this person already acted on the record (entered it, or
        took the step before), else "". A System Manager's logged override passes."""
        me = frappe.session.user
        if me not in [o for o in others if o]:
            return ""
        reason = (frappe.form_dict.get("override_reason") or "").strip()
        if "System Manager" in frappe.get_roles() and reason:
            frappe.get_doc(doctype, name).add_comment("Comment",
                "Two-pairs-of-eyes override at " + stage + " by " + me + ": " + reason)
            return ""
        sis = []
        if frappe.db.exists("DocType", "Work Management Approval Stand In"):
            for r in frappe.db.get_all("Work Management Approval Stand In",
                    filters={"parenttype": "Work Management Settings", "stage": stage}, fields=["user", "farm"]):
                if r.user != me and (not r.farm or str(r.farm).strip() == str(farm or "").strip()):
                    sis.append(r.user)
        return ("You already acted on this record (you entered it or took the step before), so somebody else "
                "must take this step" + (": " + ", ".join(sis) + "." if sis else
                ". Add a stand-in under Work Management Settings > Approval stand-ins."))


    action = frappe.form_dict.get("action") or "meta"
    out = {}

    # ===== PLANNER =====
    # A farm this caller is not offered is not a farm they may ask about. FARMS is
    # the project's farm list, narrowed to the farms this person is permitted where
    # the site has asked for that -- so the picker has already stopped offering the
    # rest. What the picker cannot close is the request itself, and every action
    # below reads its farm from the request: `?farm=Endebess` from somebody
    # restricted to Saboti was answered in full, picker or no picker.
    #
    # So the guard sits ahead of the dispatch rather than inside the actions. There
    # are thirty-odd places that read a farm and one that could be forgotten is one
    # that leaks, and an action added next year gets this for free.
    #
    # Two things it deliberately does not refuse. A request naming no farm is a
    # request across everything the caller may see, and FARMS already bounds that --
    # refusing it would break the default view of every screen for everybody. And an
    # empty FARMS means the site is unconfigured, not that this person is permitted
    # nothing: the pickers are empty there anyway, so there is nothing to defend and
    # a guard that fired would only break a fresh install.
    # WRITES ARE POST-ONLY, AND EACH NEEDS ITS CAPABILITY (2026-11-12). A link opened
    # from an email or chat is a GET, and a GET skips Frappe's CSRF check -- so it
    # cannot be allowed to approve, purge or re-price anything. Reads stay GET. The
    # capability named against an action is the Settings grant it needs; "" means
    # the action makes its own role and farm checks further down.
    WMG_WRITES = {
        "pay_bulk_review": "", "pay_bulk_submit": "send_payment",
        "pay_bulk_withdraw": "send_payment", "pay_fix_duplicates": "repair_payments",
        "pay_fix_orphan_refs": "repair_payments", "pay_fix_unvalued": "repair_payments",
        "pay_purge_queue": "repair_payments", "pay_recalc_wages": "repair_payments",
        "pay_release_inactive": "repair_payments", "pay_round_amounts": "repair_payments",
        "pay_run_withdraw": "send_payment", "pay_submit": "send_payment",
        "pay_worker_edit_day": "send_payment", "pay_worker_edit_days": "send_payment",
        "pay_worker_review": "", "pay_worker_submit": "send_payment"
    }
    WMG_DENY = ""
    if action in WMG_WRITES or action.startswith("chk_") and action not in ("chk_list", "chk_detail", "chk_issues", "chk_dup_groups", "chk_dup_detail"):
        if frappe.request and frappe.request.method != "POST":
            WMG_DENY = ("This changes data, so it has to be sent from the screen (as a POST), "
                        "not opened as a link.")
        elif WMG_WRITES.get(action):
            wmg_need = WMG_WRITES.get(action)
            wmg_held = frappe.get_roles()
            if "System Manager" not in wmg_held and not [r for r in (CAPABILITIES.get(wmg_need) or []) if r in wmg_held]:
                WMG_DENY = ("You are not allowed to do this. It needs the '" + wmg_need +
                            "' permission in Work Management Settings.")


    FARM_ASKED = (frappe.form_dict.get("farm") or "").strip()
    FARM_DENIED = ""
    if FARM_ASKED and FARMS and FARM_ASKED not in FARMS:
        # The farm they asked for, and no others: listing the ones they may not see
        # would hand back exactly what the guard withholds.
        FARM_DENIED = (FARM_ASKED + " is not a farm you are working. If it should be,"
            " it needs adding to the farms this project works, or to the farms you"
            " are permitted.")

    if FARM_DENIED:
        out["error"] = FARM_DENIED
    elif WMG_DENY:
        out["error"] = WMG_DENY
    elif action == "pay_confirmed":
        rows = frappe.db.get_all("Work Management Actuals",
            filters={"workflow_state":"CONFIRMED","paid":0},
            fields=["name","farm","task","block_section","payroll_people","total_payment","entry_date"],
            order_by="farm", limit=500)
        out["actuals"] = rows

    elif action == "pay_submit":
        # Retired 2026-11-12: it stamped no payment_ref and raised no Additional
        # Salary, so its rows stayed payable and its runs were never stamped paid.
        out["error"] = "Send from the Pay workers tab, one worker or many at a time."

    elif action == "pay_submit" and not CAN_SEND:
        out["error"] = ("Only the HR head, accounting or the general manager can send work to "
                        "accounts. You can review and audit, but not create the payment.")

    elif action == "pay_submit":
        # Worker-centric: pay a list of employees. Each becomes ONE payment line summarising
        # their unpaid confirmed earnings; on mark-paid we stamp their individual rows.
        title = frappe.form_dict.get("title")
        workers_raw = frappe.form_dict.get("workers")
        submit_now = frappe.form_dict.get("submit_now")
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        err = None
        emp_list = []
        if workers_raw:
            for e in workers_raw.split(","):
                ev = e.strip()
                if ev and ev not in emp_list:
                    emp_list.append(ev)
        if not emp_list: err = "Select at least one worker to pay"
        if err:
            out["error"] = err
        else:
            d = frappe.new_doc("Work Management Payment")
            d.run_title = title or ("Payment run " + frappe.utils.today())
            d.company = DEFAULT_COMPANY
            d.payroll_date = frappe.utils.today()
            d.prepared_by = frappe.session.user
            # store the window if the fields exist (safe: set_value later per-row anyway)
            try:
                if dfrom:
                    d.period_from = dfrom
                if dto:
                    d.period_to = dto
            except Exception:
                pass
            gt = 0
            cnt = 0
            for emp in emp_list:
                aconds = "we.employee=%s AND ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0" + CHECKED_ONLY
                aparams = [emp]
                if dfrom:
                    aconds = aconds + " AND we.work_date >= %s"
                    aparams.append(dfrom)
                if dto:
                    aconds = aconds + " AND we.work_date <= %s"
                    aparams.append(dto)
                agg = frappe.db.sql("""
                    SELECT we.employee_name nm, ac.farm farm,
                           COUNT(DISTINCT we.work_date) days,
                           COALESCE(SUM(we.actual_quantity),0) qty,
                           COALESCE(SUM(we.amount),0) owed
                    FROM `tabWork Actuals Employee` we
                    INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                    WHERE """ + aconds + """
                """, tuple(aparams), as_dict=True)
                if not agg or frappe.utils.flt(agg[0].owed) <= 0:
                    continue
                g = agg[0]
                row = d.append("lines", {})
                row.employee = emp
                row.employee_name = g.nm
                row.farm = g.farm
                row.days = g.days
                row.qty = g.qty
                row.paid_workers = 1
                row.amount = frappe.utils.flt(g.owed)
                gt = gt + frappe.utils.flt(g.owed)
                cnt = cnt + 1
            d.amount = gt
            d.total_workers = cnt
            d.total_actuals = cnt
            d.flags.ignore_permissions = True
            d.insert(ignore_permissions=True)
            if submit_now:
                frappe.db.set_value("Work Management Payment", d.name, "workflow_state", "Unpaid", update_modified=False)
                d.workflow_state = "Unpaid"
            out["name"] = d.name
            out["workflow_state"] = d.workflow_state
            out["amount"] = d.amount
            out["total_workers"] = cnt

    elif action == "pay_workers":
        # Worker-centric. Optional: farms (CSV) + date range (filters payable work_days).
        # include_all=1 -> return EVERY confirmed worker in range with a status (Unpaid/Submitted/Paid)
        #                  and the run ref; paid/submitted rows are shown but not payable.
        farms_raw = frappe.form_dict.get("farms")
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        include_all = frappe.form_dict.get("include_all")
        conds = "ac.workflow_state='CONFIRMED' AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0" + TW_ONLY
        if not include_all:
            conds = conds + " AND IFNULL(we.paid,0)=0" + CHECKED_ONLY
        params = []
        farm_list = []
        if farms_raw:
            for f in farms_raw.split(","):
                fv = f.strip()
                if fv:
                    farm_list.append(fv)
        if farm_list:
            ph = ",".join(["%s"] * len(farm_list))
            conds = conds + " AND ac.farm IN (" + ph + ")"
            for fv in farm_list:
                params.append(fv)
        if dfrom:
            conds = conds + " AND we.work_date >= %s"
            params.append(dfrom)
        if dto:
            conds = conds + " AND we.work_date <= %s"
            params.append(dto)
        rows = frappe.db.sql("""
            SELECT we.employee emp, we.employee_name emp_name, ac.farm farm,
                   COUNT(DISTINCT we.work_date) days,
                   COUNT(DISTINCT ac.task) tasks,
                   MIN(we.work_date) wfrom, MAX(we.work_date) wto,
                   COALESCE(SUM(we.actual_quantity),0) qty,
                   COALESCE(SUM(we.amount),0) owed,
                   COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=1 THEN we.amount ELSE 0 END),0) paid_amt,
                   COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 THEN we.amount ELSE 0 END),0) unpaid_amt,
                   COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 AND IFNULL(we.payment_ref,'')=''""" + CHECKED_ONLY + """ THEN we.amount ELSE 0 END),0) payable_amt,
                   COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 AND IFNULL(we.payment_ref,'')!='' THEN we.amount ELSE 0 END),0) sent_amt,
                   COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 AND IFNULL(we.custom_reviewed,0)=0 THEN we.amount ELSE 0 END),0) unreviewed_amt,
                   COUNT(DISTINCT ac.name) docs,
                   MIN(IFNULL(we.paid,0)) min_paid,
                   MAX(IFNULL(we.paid,0)) max_paid,
                   MAX(we.payment_ref) run_ref
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + conds + """
            GROUP BY we.employee, we.employee_name, ac.farm
            ORDER BY ac.farm, owed DESC
        """, tuple(params), as_dict=True)
        # attendance-conflict flag per worker: day-rows in this window that fall on
        # a marked-Absent day (the headline discrepancy — full detail lives in the
        # review sheet's Discrepancies tab)
        disc_map = {}
        drows = frappe.db.sql("""
            SELECT we.employee emp, COUNT(*) n
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            INNER JOIN `tabAttendance` att ON att.employee = we.employee
                  AND att.attendance_date = we.work_date
                  AND att.docstatus = 1 AND att.status = 'Absent'
            WHERE """ + conds + " AND NOT EXISTS (\n                SELECT 1 FROM `tabAttendance` pp\n                WHERE pp.employee = att.employee AND pp.attendance_date = att.attendance_date\n                  AND pp.docstatus = 1 AND pp.status IN ('Present','Half Day','Work From Home')\n              )" + """
            GROUP BY we.employee
        """, tuple(params), as_dict=True)
        for r in drows:
            disc_map[r.emp] = frappe.utils.cint(r.n)
        # derive status per worker. Mid-week (or any partial) sending means a
        # window can legitimately be a MIX: some days already sent (or paid),
        # others confirmed since and never sent at all -- payable_amt is what
        # actually still needs sending, independent of whatever else in this
        # same window was sent earlier. A row is never hidden from sending
        # just because part of it already went: "Partially sent" says so
        # explicitly rather than collapsing into "Sent to payroll", which
        # used to make the still-payable remainder unreachable from here.
        for r in rows:
            r["disc_days"] = disc_map.get(r.emp, 0)
            rref = r.get("run_ref")
            runstate = None
            if rref:
                runstate = frappe.db.get_value("Work Management Payment", rref, "workflow_state")
            payable_amt = frappe.utils.flt(r.get("payable_amt"))
            sent_amt = frappe.utils.flt(r.get("sent_amt"))
            if r.get("max_paid") == 1 and r.get("min_paid") == 1:
                r["pay_status"] = "Paid"
            elif rref and runstate == "Paid" and frappe.utils.flt(r.get("unpaid_amt")) <= 0.001:
                r["pay_status"] = "Paid"
            elif r.get("max_paid") == 1 and frappe.utils.flt(r.get("unpaid_amt")) <= 0.001:
                r["pay_status"] = "Paid"
            elif payable_amt > 0.001 and sent_amt > 0.001:
                r["pay_status"] = "Partially sent"
            elif payable_amt <= 0.001 and sent_amt > 0.001:
                r["pay_status"] = "Sent to payroll"
            else:
                r["pay_status"] = "Unpaid"
            r["run_ref"] = rref or None
            r["wfrom"] = str(r.get("wfrom")) if r.get("wfrom") else None
            r["wto"] = str(r.get("wto")) if r.get("wto") else None
            r["payable"] = 1 if payable_amt > 0.001 else 0
        out["workers"] = rows
        # work held back because it is not yet in an approved payroll check
        out["awaiting_check"] = []
        if PC_GATE:
            aw_conds = ("ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0 AND IFNULL(we.payment_ref,'')=''"
                        " AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0" + TW_ONLY +
                        " AND NOT EXISTS (SELECT 1 FROM `tabWork Management Payroll Check` pchk"
                        " WHERE pchk.name = we.payroll_check AND pchk.status IN ('Approved', 'Sent'))")
            aw_params = []
            if farm_list:
                aw_conds = aw_conds + " AND ac.farm IN (" + ",".join(["%s"] * len(farm_list)) + ")"
                for fv in farm_list:
                    aw_params.append(fv)
            if dfrom:
                aw_conds = aw_conds + " AND we.work_date >= %s"
                aw_params.append(dfrom)
            if dto:
                aw_conds = aw_conds + " AND we.work_date <= %s"
                aw_params.append(dto)
            out["awaiting_check"] = frappe.db.sql("""
                SELECT ac.farm farm, COUNT(*) worker_days, COALESCE(SUM(we.amount),0) amount,
                       MIN(we.work_date) date_from, MAX(we.work_date) date_to
                FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON ac.name = we.parent
                WHERE """ + aw_conds + """
                GROUP BY ac.farm ORDER BY ac.farm
            """, tuple(aw_params), as_dict=True)
        tot = 0
        for r in rows:
            tot = tot + frappe.utils.flt(r.get("payable_amt"))
        out["amount"] = tot
        # ALL farms that have earnings in the same window (payable-only for the multi-select summary --
        # an amount already sent, awaiting payroll, is not something this chip's count should offer again)
        fconds = ("ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0 AND IFNULL(we.payment_ref,'')='' "
                  "AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0") + CHECKED_ONLY
        fparams = []
        if dfrom:
            fconds = fconds + " AND we.work_date >= %s"
            fparams.append(dfrom)
        if dto:
            fconds = fconds + " AND we.work_date <= %s"
            fparams.append(dto)
        allfarms = frappe.db.sql("""
            SELECT ac.farm farm, COUNT(DISTINCT we.employee) workers, COALESCE(SUM(we.amount),0) owed
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + fconds + """
            GROUP BY ac.farm ORDER BY ac.farm
        """, tuple(fparams), as_dict=True)
        out["farms"] = allfarms

    elif action == "pay_worker_detail":
        # One worker's completed jobs (per task/plan/day) that are confirmed + unpaid
        emp = frappe.form_dict.get("employee")
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        jconds = "we.employee=%s AND ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1" + CHECKED_ONLY
        jparams = [emp]
        if dfrom:
            jconds = jconds + " AND we.work_date >= %s"
            jparams.append(dfrom)
        if dto:
            jconds = jconds + " AND we.work_date <= %s"
            jparams.append(dto)
        jobs = frappe.db.sql("""
            SELECT ac.name actuals, ac.farm farm, ac.task task, ac.block_section block,
                   we.work_date wdate, we.actual_quantity qty, we.amount amount,
                   CASE WHEN IFNULL(we.actual_quantity,0) > 0
                        THEN we.amount / we.actual_quantity ELSE ac.rate END rate
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + jconds + """
            ORDER BY we.work_date
        """, tuple(jparams), as_dict=True)
        empinfo = frappe.db.get_value("Employee", emp, ["employee_name","custom_farm"], as_dict=True)
        out["employee"] = emp
        out["employee_name"] = empinfo.employee_name if empinfo else emp
        out["jobs"] = jobs
        tot = 0
        days = {}
        for j in jobs:
            tot = tot + frappe.utils.flt(j.amount)
            days[str(j.wdate)] = 1
        out["total_owed"] = tot
        out["total_days"] = len(days)

    elif action == "pay_pending":
        # The queue can run to thousands. It is paged rather than silently cut off
        # at 200: the true total always comes back, so the tab can never imply the
        # queue is smaller than it is.
        pp_limit = frappe.utils.cint(frappe.form_dict.get("limit") or 200)
        if pp_limit < 1:
            pp_limit = 200
        if pp_limit > 1000:
            pp_limit = 1000
        pp_start = frappe.utils.cint(frappe.form_dict.get("start") or 0)
        pp_week = frappe.form_dict.get("payroll_date")
        # Same filters the Pay workers tab offers, so accounts can narrow the queue
        # the way the person who built it did: farm, worked-date range, and a search
        # over the worker or the reference. Applied server-side, so the totals and
        # the paging stay honest rather than filtering only the page on screen.
        pp_farms = (frappe.form_dict.get("farms") or "").strip()
        pp_from = frappe.form_dict.get("from_date")
        pp_to = frappe.form_dict.get("to_date")
        pp_q = (frappe.form_dict.get("q") or "").strip()
        pp_filters = {"workflow_state": "Unpaid"}
        if pp_week:
            pp_filters["payroll_date"] = pp_week
        pp_cond = "p.workflow_state = 'Unpaid'"
        pp_args = {}
        if pp_week:
            pp_cond = pp_cond + " AND p.payroll_date = %(wk)s"
            pp_args["wk"] = pp_week
        if pp_farms:
            pp_flist = [f.strip() for f in pp_farms.split(",") if f.strip()]
            if pp_flist:
                pp_cond = pp_cond + " AND p.farm IN %(fl)s"
                pp_args["fl"] = tuple(pp_flist)
        if pp_from:
            pp_cond = pp_cond + " AND p.period_to >= %(pf)s"
            pp_args["pf"] = pp_from
        if pp_to:
            pp_cond = pp_cond + " AND p.period_from <= %(pt)s"
            pp_args["pt"] = pp_to
        if pp_q:
            pp_cond = pp_cond + (" AND (p.name LIKE %(q)s OR p.run_title LIKE %(q)s"
                                 " OR EXISTS (SELECT 1 FROM `tabWork Payment Line` wl"
                                 " WHERE wl.parent = p.name AND (wl.employee LIKE %(q)s"
                                 " OR wl.employee_name LIKE %(q)s)))")
            pp_args["q"] = "%" + pp_q + "%"
        pp_agg = frappe.db.sql("""
            SELECT COUNT(*) n, COALESCE(SUM(p.amount),0) a
            FROM `tabWork Management Payment` p WHERE """ + pp_cond, pp_args, as_dict=True)[0]
        out["total"] = frappe.utils.cint(pp_agg.n)
        out["total_amount"] = frappe.utils.flt(pp_agg.a)
        out["filtered"] = 1 if (pp_farms or pp_from or pp_to or pp_q) else 0
        out["queue_total"] = frappe.db.count("Work Management Payment", {"workflow_state": "Unpaid"})
        out["farms"] = frappe.db.sql("""
            SELECT p.farm, COUNT(*) n FROM `tabWork Management Payment` p
            WHERE p.workflow_state = 'Unpaid' AND IFNULL(p.farm,'') != ''
            GROUP BY p.farm ORDER BY p.farm
        """, as_dict=True)
        # every pay week in the queue, so accounts can work a week at a time
        pp_wcond = pp_cond
        if pp_week:
            pp_wcond = pp_wcond.replace(" AND p.payroll_date = %(wk)s", "")
        out["weeks"] = frappe.db.sql("""
            SELECT p.payroll_date, p.period_from, p.period_to, COUNT(*) n,
                   COALESCE(SUM(p.amount),0) amount
            FROM `tabWork Management Payment` p
            WHERE """ + pp_wcond + """
            GROUP BY p.payroll_date, p.period_from, p.period_to
            ORDER BY p.payroll_date DESC
        """, pp_args, as_dict=True)
        pp_args["lim"] = pp_limit
        pp_args["off"] = pp_start
        pend = frappe.db.sql("""
            SELECT p.name, p.run_title, p.total_actuals, p.total_workers, p.amount,
                   p.prepared_by, p.payroll_date, p.period_from, p.period_to, p.farm
            FROM `tabWork Management Payment` p
            WHERE """ + pp_cond + """
            ORDER BY p.payroll_date DESC, p.name ASC
            LIMIT %(lim)s OFFSET %(off)s
        """, pp_args, as_dict=True)
        # one query for the worker names rather than one per payment
        pp_names = [pr.name for pr in pend]
        pp_emp = {}
        if pp_names:
            for ln in frappe.db.sql("""
                SELECT parent, employee, employee_name FROM `tabWork Payment Line`
                WHERE parent IN %(p)s GROUP BY parent, employee, employee_name
            """, {"p": tuple(pp_names)}, as_dict=True):
                if ln.parent not in pp_emp:
                    pp_emp[ln.parent] = ln
        for pr in pend:
            ln = pp_emp.get(pr.name)
            pr["employee"] = ln.employee if ln else None
            pr["employee_name"] = ln.employee_name if ln else None
            pr["period_from"] = str(pr.period_from) if pr.period_from else None
            pr["period_to"] = str(pr.period_to) if pr.period_to else None
            pr["payroll_date"] = str(pr.payroll_date) if pr.payroll_date else None
        # Reconciliation note per run: its Additional Salary's pay date already
        # falls inside a submitted Salary Slip's window, but that slip does not
        # actually reference it -- so this run cannot be marked Paid
        # automatically even though a slip technically exists for the period.
        # Not an Issue (nothing failed to send -- the run and its Additional
        # Salary were both raised fine) and never auto-fixed (matching by
        # amount alone is not proof of the same payment): just a note on the
        # run it actually concerns, here in the queue it is sitting in.
        if pend:
            pp_as = frappe.db.get_all("Additional Salary",
                filters={"ref_doctype": "Work Management Payment", "ref_docname": ["in", pp_names], "docstatus": 1},
                fields=["name", "ref_docname", "employee", "payroll_date", "creation"])
            pp_as_by_payment = {a.ref_docname: a for a in pp_as}
            for pr in pend:
                pr["candidate_slip"] = None
                a = pp_as_by_payment.get(pr.name)
                if not a:
                    continue
                cand_slips = frappe.db.get_all("Salary Slip",
                    filters={"employee": a.employee, "docstatus": 1,
                             "start_date": ["<=", a.payroll_date], "end_date": [">=", a.payroll_date]},
                    fields=["name", "creation"])
                # a slip generated BEFORE this Additional Salary even existed could
                # never have picked it up -- that is not a missed reconciliation,
                # it is ordinary sequencing (this run was raised after that
                # month's payroll already went out, and is simply waiting for the
                # next one). Only a slip created after the Additional Salary is a
                # genuine candidate for "should have referenced it but didn't".
                cand_slips = [c for c in cand_slips if c.creation > a.creation]
                if not cand_slips:
                    continue
                linked = frappe.db.get_all("Salary Detail",
                    filters={"parenttype": "Salary Slip", "parent": ["in", [c.name for c in cand_slips]],
                             "additional_salary": a.name},
                    limit_page_length=1)
                if not linked:
                    pr["candidate_slip"] = cand_slips[0].name
        out["pending"] = pend
        out["start"] = pp_start
        out["limit"] = pp_limit
        out["returned"] = len(pend)
        out["has_more"] = 1 if (pp_start + len(pend)) < out["total"] else 0

    # pay_mark_paid removed: a run is no longer finalised by a manual click.
    # Raising the Additional Salary already happens when it is sent for payroll
    # processing (pay_worker_submit / pay_bulk_submit); "Paid" is now set
    # automatically by on_salary_slip_submit() once payroll actually submits the
    # Salary Slip that carries it. See that function and
    # _stamp_actuals_paid_for_payment() below.

    elif action == "pay_my":
        # History holds PROCESSED runs only -- payroll actually paid them, a real
        # Salary Slip exists. Not Unpaid (still in the queue -- "Awaiting
        # payroll") and not Cancelled either: a cancelled run was withdrawn
        # before payroll ever touched it, so it was never processed and has no
        # place in a record of what payroll paid. It still exists and is fully
        # auditable from the Work Management Payment list in the Desk (filter
        # workflow_state = Cancelled) -- just not surfaced in this tab.
        my_runs = frappe.db.get_all("Work Management Payment",
            filters={"prepared_by":frappe.session.user, "workflow_state": "Paid"},
            fields=["name","run_title","total_actuals","total_workers","amount","workflow_state","payroll_date"],
            order_by="creation desc", limit=200)
        # Resolve each run's Salary Slip in one pass: the actual paper trail a
        # Paid entry in history should offer directly, not two clicks away
        # through the Additional Salary's own connections. ref_docname is the
        # Payment; Salary Detail.additional_salary is the Slip's own trace
        # back to the Additional Salary it paid.
        if my_runs:
            my_names = [r["name"] for r in my_runs]
            my_as = frappe.db.get_all("Additional Salary",
                filters={"ref_doctype": "Work Management Payment", "ref_docname": ["in", my_names]},
                fields=["name", "ref_docname"])
            my_as_by_payment = {r.ref_docname: r.name for r in my_as}
            my_as_names = [r.name for r in my_as]
            my_slip_by_as = {}
            if my_as_names:
                my_slip_rows = frappe.db.sql("""
                    SELECT additional_salary, parent FROM `tabSalary Detail`
                    WHERE parenttype = 'Salary Slip' AND additional_salary IN %(names)s
                """, {"names": tuple(my_as_names)}, as_dict=True)
                for sr in my_slip_rows:
                    my_slip_by_as[sr.additional_salary] = sr.parent
            for r in my_runs:
                as_name = my_as_by_payment.get(r["name"])
                r["salary_slip"] = my_slip_by_as.get(as_name)
        out["runs"] = my_runs

    elif action == "pay_roles":
        rl = frappe.db.get_all("Has Role", filters={"parent": frappe.session.user}, pluck="role")
        is_acc = ("System Manager" in rl) or any(
            r in rl for r in (CAPABILITIES.get("handle_payments") or []))
        out["user"] = frappe.session.user
        out["is_accounts"] = 1 if is_acc else 0
        out["can_send"] = CAN_SEND
        # the page picks pay weeks, not free dates, so it needs the configured
        # week boundary
        r_names = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
        r_start = frappe.db.get_single_value("Work Management Settings", "pay_week_starts_on") or "Sunday"
        r_end = frappe.db.get_single_value("Work Management Settings", "pay_week_ends_on") or "Saturday"
        r_pay = frappe.db.get_single_value("Work Management Settings", "pay_day") or r_end
        r_si = r_names.index(r_start) if r_start in r_names else 6
        r_ei = r_names.index(r_end) if r_end in r_names else 5
        out["week_starts_on"] = r_start
        out["week_ends_on"] = r_end
        out["pay_day"] = r_pay
        out["week_days"] = ((r_ei - r_si) % 7) + 1
        # whether the page may offer to send a chosen range as one payment, or only
        # pay weeks. The page needs it to label the range picker honestly: sending a
        # range on a site that does not offer them is refused server-side, and
        # finding that out after ticking two hundred workers is no way to learn it.
        out["allow_day_range"] = frappe.utils.cint(frappe.db.get_single_value(
            "Work Management Settings", "allow_day_range"))
        out["max_span_days"] = MAX_SPAN_DAYS

    elif action == "pay_audit":
        # Reconcile CONFIRMED actuals against assigner + payment, per task/block, for the range.
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        farms_raw = frappe.form_dict.get("farms")
        farm_list = []
        if farms_raw:
            for f in farms_raw.split(","):
                fv = f.strip()
                if fv:
                    farm_list.append(fv)
        conds = "ac.workflow_state='CONFIRMED'"
        params = []
        if dfrom:
            conds = conds + " AND we.work_date >= %s"
            params.append(dfrom)
        if dto:
            conds = conds + " AND we.work_date <= %s"
            params.append(dto)
        if farm_list:
            ph = ",".join(["%s"] * len(farm_list))
            conds = conds + " AND ac.farm IN (" + ph + ")"
            for fv in farm_list:
                params.append(fv)
        # ---- SUMMARY: one row per actuals doc (task/block/assignment) ----
        summ = frappe.db.sql("""
            SELECT ac.name actuals, ac.farm farm, ac.task task, ac.block_section block,
                   ac.assignment assignment, ac.entry_date entry_date, ac.entered_by entered_by,
                   COUNT(DISTINCT we.employee) workers,
                   COUNT(*) worker_days,
                   COALESCE(SUM(we.actual_quantity),0) actual_qty,
                   COALESCE(SUM(we.amount),0) total_pay,
                   COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=1 THEN we.amount ELSE 0 END),0) paid_pay,
                   COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 THEN we.amount ELSE 0 END),0) unpaid_pay,
                   COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 AND IFNULL(we.payment_ref,'')='' THEN we.amount ELSE 0 END),0) payable_pay,
                   COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 AND IFNULL(we.payment_ref,'')!='' THEN we.amount ELSE 0 END),0) sent_pay,
                   MAX(we.payment_ref) run_refs
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + conds + """
            GROUP BY ac.name, ac.farm, ac.task, ac.block_section, ac.assignment, ac.entry_date, ac.entered_by
            ORDER BY ac.farm, total_pay DESC
        """, tuple(params), as_dict=True)
        sumrows = []
        t_tasks = 0
        t_qty = 0
        t_total = 0
        t_paid = 0
        t_unpaid = 0
        t_wdays = 0
        for s in summ:
            # enrich with assigner planned/assigned + plan link
            planned = 0
            assigned = 0
            variance = 0
            planner = None
            pfrom = None
            pto = None
            if s.assignment:
                ai = frappe.db.get_value("Work Management Assigner", s.assignment,
                    ["planned_people","assigned_count","variance","planner_request"], as_dict=True)
                if ai:
                    planned = frappe.utils.cint(ai.planned_people)
                    assigned = frappe.utils.cint(ai.assigned_count)
                    variance = frappe.utils.cint(ai.variance)
                    planner = ai.planner_request
            if planner:
                pd = frappe.db.get_value("Work Management Planner", planner, ["from_date","to_date"], as_dict=True)
                if pd:
                    pfrom = str(pd.from_date) if pd.from_date else None
                    pto = str(pd.to_date) if pd.to_date else None
            # pay status for the doc. payable/sent split the same way pay_workers()
            # does: a row can be sent to payroll (payment_ref set) well before it is
            # confirmed paid, so "not yet paid" alone used to read as "Unpaid" even
            # when it was already mid-week sent and just awaiting the Salary Slip.
            tot = frappe.utils.flt(s.total_pay)
            paid = frappe.utils.flt(s.paid_pay)
            unpaid = frappe.utils.flt(s.unpaid_pay)
            payable = frappe.utils.flt(s.payable_pay)
            sent = frappe.utils.flt(s.sent_pay)
            if tot > 0 and paid >= tot - 0.001:
                pstat = "Paid"
            elif paid > 0:
                pstat = "Part paid"
            elif payable > 0.001 and sent > 0.001:
                pstat = "Partially sent"
            elif payable <= 0.001 and sent > 0.001:
                pstat = "Sent to payroll"
            else:
                pstat = "Unpaid"
            sumrows.append({
                "actuals": s.actuals, "farm": s.farm, "task": s.task, "block": s.block,
                "assignment": s.assignment, "planner_request": planner, "from_date": pfrom, "to_date": pto,
                "planned_people": planned, "assigned_count": assigned, "variance": variance,
                "actual_qty": frappe.utils.flt(s.actual_qty), "workers": frappe.utils.cint(s.workers),
                "worker_days": frappe.utils.cint(s.worker_days),
                "total_pay": tot, "paid_pay": paid, "unpaid_pay": unpaid,
                "payable_pay": payable, "sent_pay": sent,
                "pay_status": pstat, "run_refs": s.run_refs, "entered_by": s.entered_by,
                "entry_date": str(s.entry_date) if s.entry_date else None
            })
            t_tasks = t_tasks + 1
            t_qty = t_qty + frappe.utils.flt(s.actual_qty)
            t_total = t_total + tot
            t_paid = t_paid + paid
            t_unpaid = t_unpaid + unpaid
            t_wdays = t_wdays + frappe.utils.cint(s.worker_days)
        out["summary"] = sumrows
        # ---- DETAIL: one row per worker per day ----
        det = frappe.db.sql("""
            SELECT ac.farm farm, ac.task task, ac.block_section block, ac.assignment assignment,
                   we.employee emp, we.employee_name emp_name, we.employment_type emp_type,
                   we.work_date wdate, we.actual_quantity qty, we.amount amount,
                   IFNULL(we.count_in_payroll,0) in_payroll,
                   IFNULL(we.paid,0) paid, IFNULL(we.custom_reviewed,0) reviewed, we.payment_ref run_ref
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + conds + """
            ORDER BY ac.farm, ac.task, we.employee_name, we.work_date
        """, tuple(params), as_dict=True)
        detrows = []
        for d in det:
            # a day-row's own payment_ref already says whether it was sent, no
            # aggregation needed at this granularity -- see the same payable/sent
            # split in pay_workers().
            if frappe.utils.cint(d.paid) == 1:
                pstat = "Paid"
            elif d.run_ref:
                pstat = "Sent to payroll"
            else:
                pstat = "Unpaid"
            detrows.append({
                "farm": d.farm, "task": d.task, "block": d.block, "assignment": d.assignment,
                "emp": d.emp, "emp_name": d.emp_name, "emp_type": d.emp_type,
                "wdate": str(d.wdate) if d.wdate else None,
                "qty": frappe.utils.flt(d.qty), "amount": frappe.utils.flt(d.amount),
                "in_payroll": frappe.utils.cint(d.in_payroll), "pay_status": pstat, "run_ref": d.run_ref,
                "reviewed": frappe.utils.cint(d.reviewed)
            })
        out["detail"] = detrows
        out["totals"] = {"tasks": t_tasks, "qty": t_qty, "total_pay": t_total,
                         "paid": t_paid, "unpaid": t_unpaid, "worker_days": t_wdays}

    elif action == "pay_insights":
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        farm = frappe.form_dict.get("farm")
        conds = "ac.workflow_state='CONFIRMED'"
        params = []
        if dfrom:
            conds = conds + " AND we.work_date >= %s"
            params.append(dfrom)
        if dto:
            conds = conds + " AND we.work_date <= %s"
            params.append(dto)
        if farm:
            conds = conds + " AND ac.farm = %s"
            params.append(farm)
        # KPIs
        kp = frappe.db.sql("""
            SELECT COUNT(DISTINCT we.employee) active_workers,
                   COUNT(*) mandays,
                   COALESCE(SUM(we.amount),0) earned,
                   COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=1 THEN we.amount ELSE 0 END),0) paid_amt,
                   COUNT(DISTINCT CASE WHEN IFNULL(we.paid,0)=1 THEN we.employee END) paid_workers,
                   COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 THEN we.amount ELSE 0 END),0) unpaid_amt,
                   COUNT(DISTINCT CASE WHEN IFNULL(we.paid,0)=0 THEN we.employee END) unpaid_workers
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + conds + """
        """, tuple(params), as_dict=True)
        k = kp[0] if kp else {}
        out["kpi"] = {
            "active_workers": frappe.utils.cint(k.active_workers) if kp else 0,
            "mandays": frappe.utils.cint(k.mandays) if kp else 0,
            "earned": frappe.utils.flt(k.earned) if kp else 0,
            "paid_amt": frappe.utils.flt(k.paid_amt) if kp else 0,
            "paid_workers": frappe.utils.cint(k.paid_workers) if kp else 0,
            "unpaid_amt": frappe.utils.flt(k.unpaid_amt) if kp else 0,
            "unpaid_workers": frappe.utils.cint(k.unpaid_workers) if kp else 0
        }
        # assigned workers (live assignments in window/farm)
        aconds = "a.workflow_state IN ('Pending Farm Manager','Pending HR Head','Pending GM','Assigned')"
        aparams = []
        if farm:
            aconds = aconds + " AND a.farm = %s"
            aparams.append(farm)
        asg = frappe.db.sql("""
            SELECT COUNT(DISTINCT we.employee) c
            FROM `tabWork Assignment Employee` we
            INNER JOIN `tabWork Management Assigner` a ON we.parent = a.name
            WHERE """ + aconds + """ AND IFNULL(we.status,'Active')='Active'
        """, tuple(aparams), as_dict=True)
        out["assigned_workers"] = frappe.utils.cint(asg[0].c) if asg else 0
        # workforce pool: active Task Workers -> available = pool - assigned
        pconds = "status='Active' AND employment_type='Task Worker'"
        pparams = []
        if farm:
            pconds = pconds + " AND custom_farm = %s"
            pparams.append(farm)
        pool = frappe.db.sql("""
            SELECT name emp, employee_name nm, custom_farm farm, designation
            FROM `tabEmployee` WHERE """ + pconds + """
            ORDER BY employee_name LIMIT 3000
        """, tuple(pparams), as_dict=True)
        out["pool_count"] = len(pool)
        arows = frappe.db.sql("""
            SELECT we.employee emp, we.employee_name nm, a.farm farm, a.task task,
                   a.name assignment, a.from_date fdate, a.to_date tdate, a.workflow_state state
            FROM `tabWork Assignment Employee` we
            INNER JOIN `tabWork Management Assigner` a ON we.parent = a.name
            WHERE """ + aconds + """ AND IFNULL(we.status,'Active')='Active'
            ORDER BY a.from_date DESC LIMIT 5000
        """, tuple(aparams), as_dict=True)
        aset = {}
        amap = {}
        for r in arows:
            aset[r.emp] = 1
            g = amap.get(r.emp)
            if not g:
                g = {"emp": r.emp, "nm": r.nm, "farm": r.farm, "assignments": 0, "tasks": {}, "latest_from": None, "latest_to": None}
                amap[r.emp] = g
            g["assignments"] = g["assignments"] + 1
            if r.task:
                g["tasks"][r.task] = 1
            if not g["latest_from"]:
                g["latest_from"] = str(r.fdate) if r.fdate else None
                g["latest_to"] = str(r.tdate) if r.tdate else None
        alist = []
        for k2 in amap:
            g = amap[k2]
            tl = []
            for tk in g["tasks"]:
                tl.append(tk)
            tl = sorted(tl)
            g["task_list"] = ", ".join(tl)
            g["task_count"] = len(tl)
            del g["tasks"]
            alist.append(g)
        alist = sorted(alist, key=lambda x: x["assignments"], reverse=True)
        out["assigned_list"] = alist
        avail = []
        for p in pool:
            if not aset.get(p.emp):
                avail.append({"emp": p.emp, "nm": p.nm, "farm": p.farm, "designation": p.designation})
        out["available_list"] = avail
        # unpaid list (worker-level, biggest first)
        unp = frappe.db.sql("""
            SELECT we.employee emp, we.employee_name nm, ac.farm farm,
                   COUNT(DISTINCT we.work_date) days, COALESCE(SUM(we.amount),0) owed,
                   MIN(we.work_date) oldest, MAX(we.work_date) newest
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + conds + """ AND IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0
            GROUP BY we.employee, we.employee_name, ac.farm
            ORDER BY owed DESC LIMIT 500
        """, tuple(params), as_dict=True)
        ulist = []
        for u in unp:
            ulist.append({"emp": u.emp, "nm": u.nm, "farm": u.farm,
                "days": frappe.utils.cint(u.days), "owed": frappe.utils.flt(u.owed),
                "oldest": str(u.oldest) if u.oldest else None, "newest": str(u.newest) if u.newest else None})
        out["unpaid_list"] = ulist
        # task costs (per task per farm)
        tc = frappe.db.sql("""
            SELECT ac.task label, ac.farm farm,
                   COALESCE(SUM(we.amount),0) pay, COALESCE(SUM(we.actual_quantity),0) qty,
                   COUNT(DISTINCT we.employee) workers, COUNT(*) mandays
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + conds + """
            GROUP BY ac.task, ac.farm ORDER BY pay DESC LIMIT 500
        """, tuple(params), as_dict=True)
        tclist = []
        for r in tc:
            tclist.append({"label": r.label, "farm": r.farm, "pay": frappe.utils.flt(r.pay),
                "qty": frappe.utils.flt(r.qty), "workers": frappe.utils.cint(r.workers),
                "mandays": frappe.utils.cint(r.mandays)})
        out["task_costs"] = tclist
        # top earners
        top = frappe.db.sql("""
            SELECT we.employee emp, we.employee_name nm, ac.farm farm,
                   COUNT(DISTINCT we.work_date) days, COALESCE(SUM(we.actual_quantity),0) qty,
                   COALESCE(SUM(we.amount),0) pay
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + conds + """
            GROUP BY we.employee, we.employee_name, ac.farm
            ORDER BY pay DESC LIMIT 50
        """, tuple(params), as_dict=True)
        toplist = []
        for r in top:
            toplist.append({"emp": r.emp, "nm": r.nm, "farm": r.farm,
                "days": frappe.utils.cint(r.days), "qty": frappe.utils.flt(r.qty), "pay": frappe.utils.flt(r.pay)})
        out["top_workers"] = toplist
        # idle: assigned but no confirmed work in window
        idle = frappe.db.sql("""
            SELECT we.employee emp, we.employee_name nm, a.farm farm, COUNT(DISTINCT a.name) assignments
            FROM `tabWork Assignment Employee` we
            INNER JOIN `tabWork Management Assigner` a ON we.parent = a.name
            WHERE """ + aconds + """ AND IFNULL(we.status,'Active')='Active'
              AND we.employee NOT IN (
                SELECT DISTINCT we2.employee
                FROM `tabWork Actuals Employee` we2
                INNER JOIN `tabWork Management Actuals` ac2 ON we2.parent = ac2.name
                WHERE ac2.workflow_state='CONFIRMED'""" + (" AND we2.work_date >= %s" if dfrom else "") + (" AND we2.work_date <= %s" if dto else "") + """
              )
            GROUP BY we.employee, we.employee_name, a.farm
            ORDER BY assignments DESC LIMIT 500
        """, tuple(aparams + ([dfrom] if dfrom else []) + ([dto] if dto else [])), as_dict=True)
        ilist = []
        for r in idle:
            ilist.append({"emp": r.emp, "nm": r.nm, "farm": r.farm, "assignments": frappe.utils.cint(r.assignments)})
        out["idle_list"] = ilist
        # farms list for the dropdown
        allf = frappe.db.sql("""SELECT DISTINCT farm FROM `tabWork Management Actuals`
            WHERE farm IS NOT NULL ORDER BY farm""", as_dict=True)
        out["farms"] = [f.farm for f in allf]
        out["window"] = {"farm": farm or None, "from": dfrom or None, "to": dto or None}

    elif action == "pay_worker_history":
        # In-depth overview of ONE worker: every confirmed job (paid or not),
        # grouped per task/actuals doc with plan period, plus the raw daily log,
        # payment runs and headline KPIs. Used by the Audit worker deep-dive.
        emp = frappe.form_dict.get("employee")
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        if not emp:
            out["error"] = "employee is required"
        else:
            hconds = "we.employee=%s AND ac.workflow_state='CONFIRMED'"
            hparams = [emp]
            if dfrom:
                hconds = hconds + " AND we.work_date >= %s"
                hparams.append(dfrom)
            if dto:
                hconds = hconds + " AND we.work_date <= %s"
                hparams.append(dto)
            einfo = frappe.db.get_value("Employee", emp,
                ["employee_name", "custom_farm", "designation", "employment_type", "status", "date_of_joining"],
                as_dict=True)
            out["info"] = {
                "employee": emp,
                "employee_name": (einfo.employee_name if einfo else None) or emp,
                "farm": einfo.custom_farm if einfo else None,
                "designation": einfo.designation if einfo else None,
                "employment_type": einfo.employment_type if einfo else None,
                "status": einfo.status if einfo else None,
                "date_of_joining": str(einfo.date_of_joining) if einfo and einfo.date_of_joining else None,
            }
            # KPIs across the window
            kp = frappe.db.sql("""
                SELECT COUNT(*) mandays,
                       COUNT(DISTINCT we.work_date) days,
                       COUNT(DISTINCT ac.task) tasks,
                       COUNT(DISTINCT ac.name) docs,
                       COALESCE(SUM(we.actual_quantity),0) qty,
                       COALESCE(SUM(we.amount),0) earned,
                       COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=1 THEN we.amount ELSE 0 END),0) paid_amt,
                       COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 THEN we.amount ELSE 0 END),0) unpaid_amt,
                       COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 AND IFNULL(we.payment_ref,'')='' THEN we.amount ELSE 0 END),0) payable_amt,
                       COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 AND IFNULL(we.payment_ref,'')!='' THEN we.amount ELSE 0 END),0) sent_amt,
                       COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 AND IFNULL(we.custom_reviewed,0)=0 THEN we.amount ELSE 0 END),0) unreviewed_amt,
                       MIN(we.work_date) first_day, MAX(we.work_date) last_day
                FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                WHERE """ + hconds + """
            """, tuple(hparams), as_dict=True)
            k = kp[0] if kp else None
            days = frappe.utils.cint(k.days) if k else 0
            earned = frappe.utils.flt(k.earned) if k else 0
            out["kpi"] = {
                "mandays": frappe.utils.cint(k.mandays) if k else 0,
                "days": days,
                "tasks": frappe.utils.cint(k.tasks) if k else 0,
                "docs": frappe.utils.cint(k.docs) if k else 0,
                "qty": frappe.utils.flt(k.qty) if k else 0,
                "earned": earned,
                "paid_amt": frappe.utils.flt(k.paid_amt) if k else 0,
                # unpaid_amt: total not yet confirmed paid, sent or not -- kept for
                # anything reporting the true outstanding balance. payable_amt is
                # what a mid-week (or any partial) send left genuinely unsent, and
                # is what "Ready to pay" / "Approve & send to payroll" must use, or
                # a worker with part of a window already sent looks fully done when
                # new confirmed work is still sitting there unsent.
                "unpaid_amt": frappe.utils.flt(k.unpaid_amt) if k else 0,
                "payable_amt": frappe.utils.flt(k.payable_amt) if k else 0,
                "sent_amt": frappe.utils.flt(k.sent_amt) if k else 0,
                "unreviewed_amt": frappe.utils.flt(k.unreviewed_amt) if k else 0,
                "avg_per_day": (earned / days) if days else 0,
                "first_day": str(k.first_day) if k and k.first_day else None,
                "last_day": str(k.last_day) if k and k.last_day else None,
            }
            # per actuals doc first, then merged per TASK (many docs are single-day,
            # so grouping by task is what reads naturally: one card per task with
            # its full worked period and every approver involved)
            grp = frappe.db.sql("""
                SELECT ac.name actuals, ac.farm farm, ac.task task, ac.block_section block,
                       ac.assignment assignment, ac.rate doc_rate,
                       ac.entered_by entered_by, ac.hr_approved_by hr_approved_by, ac.gm_approved_by gm_approved_by,
                       MIN(we.work_date) wfrom, MAX(we.work_date) wto,
                       COUNT(DISTINCT we.work_date) days,
                       COALESCE(SUM(we.actual_quantity),0) qty,
                       COALESCE(SUM(we.amount),0) amount,
                       COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=1 THEN we.amount ELSE 0 END),0) paid_amt,
                       COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 THEN we.amount ELSE 0 END),0) unpaid_amt,
                       COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 AND IFNULL(we.payment_ref,'')='' THEN we.amount ELSE 0 END),0) payable_amt,
                       COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 AND IFNULL(we.payment_ref,'')!='' THEN we.amount ELSE 0 END),0) sent_amt,
                       MAX(we.payment_ref) run_ref
                FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                WHERE """ + hconds + """
                GROUP BY ac.name, ac.farm, ac.task, ac.block_section, ac.assignment, ac.rate,
                         ac.entered_by, ac.hr_approved_by, ac.gm_approved_by
                ORDER BY MIN(we.work_date) DESC
            """, tuple(hparams), as_dict=True)
            asg_cache = {}
            std_cache = {}
            tmap = {}
            torder = []
            for g in grp:
                ai = None
                if g.assignment:
                    ai = asg_cache.get(g.assignment)
                    if ai is None:
                        ai = frappe.db.get_value("Work Management Assigner", g.assignment,
                            ["planner_request", "from_date", "to_date", "assigned_by", "approved_by"], as_dict=True)
                        asg_cache[g.assignment] = ai
                key = (g.task or "") + "|" + (g.block or "") + "|" + (g.farm or "")
                t = tmap.get(key)
                if not t:
                    t = {"task": g.task, "block": g.block, "farm": g.farm,
                         "plan_from": None, "plan_to": None, "work_from": None, "work_to": None,
                         "days": 0, "qty": 0, "amount": 0, "paid_amt": 0, "unpaid_amt": 0,
                         "payable_amt": 0, "sent_amt": 0,
                         "docs": [], "assignments": {}, "runs": {}, "planners": {},
                         "assigned_by": {}, "fm_approved_by": {}, "entered_by": {},
                         "hr_approved_by": {}, "gm_approved_by": {}, "rate_num": 0,
                         "standard": None}
                    tmap[key] = t
                    torder.append(key)
                # the plan's work standard, e.g. "5 Ha/day" (task_kpi verbatim, else
                # daily_target + uom). Shown as the Standard column in review sheets.
                if ai and ai.planner_request and not t["standard"]:
                    std = std_cache.get(ai.planner_request)
                    if std is None:
                        pstd = frappe.db.get_value("Work Management Planner", ai.planner_request,
                            ["task_kpi", "daily_target", "uom"], as_dict=True)
                        std = ""
                        if pstd:
                            if pstd.task_kpi:
                                std = str(pstd.task_kpi)
                            elif frappe.utils.flt(pstd.daily_target) > 0:
                                std = str(frappe.utils.flt(pstd.daily_target)).rstrip("0").rstrip(".") + " " + (pstd.uom or "") + "/day"
                        std_cache[ai.planner_request] = std
                    if std:
                        t["standard"] = std
                t["docs"].append(g.actuals)
                if g.assignment:
                    t["assignments"][g.assignment] = 1
                if g.run_ref:
                    t["runs"][g.run_ref] = 1
                if ai:
                    if ai.planner_request:
                        t["planners"][ai.planner_request] = 1
                    pf = str(ai.from_date) if ai.from_date else None
                    pt = str(ai.to_date) if ai.to_date else None
                    if pf and (not t["plan_from"] or pf < t["plan_from"]):
                        t["plan_from"] = pf
                    if pt and (not t["plan_to"] or pt > t["plan_to"]):
                        t["plan_to"] = pt
                    if ai.assigned_by:
                        t["assigned_by"][ai.assigned_by] = 1
                    if ai.approved_by:
                        t["fm_approved_by"][ai.approved_by] = 1
                for fld in ("entered_by", "hr_approved_by", "gm_approved_by"):
                    v = g.get(fld)
                    if v:
                        t[fld][v] = 1
                wf = str(g.wfrom) if g.wfrom else None
                wt = str(g.wto) if g.wto else None
                if wf and (not t["work_from"] or wf < t["work_from"]):
                    t["work_from"] = wf
                if wt and (not t["work_to"] or wt > t["work_to"]):
                    t["work_to"] = wt
                t["days"] = t["days"] + frappe.utils.cint(g.days)
                t["qty"] = t["qty"] + frappe.utils.flt(g.qty)
                t["amount"] = t["amount"] + frappe.utils.flt(g.amount)
                t["paid_amt"] = t["paid_amt"] + frappe.utils.flt(g.paid_amt)
                t["unpaid_amt"] = t["unpaid_amt"] + frappe.utils.flt(g.unpaid_amt)
                t["payable_amt"] = t["payable_amt"] + frappe.utils.flt(g.payable_amt)
                t["sent_amt"] = t["sent_amt"] + frappe.utils.flt(g.sent_amt)
            tasks = []
            for key in torder:
                t = tmap[key]
                amt = t["amount"]
                if amt > 0 and t["paid_amt"] >= amt - 0.001:
                    pstat = "Paid"
                elif t["paid_amt"] > 0:
                    pstat = "Part paid"
                elif t["payable_amt"] > 0.001 and t["sent_amt"] > 0.001:
                    pstat = "Partially sent"
                elif t["payable_amt"] <= 0.001 and t["sent_amt"] > 0.001:
                    pstat = "Sent to payroll"
                else:
                    pstat = "Unpaid"
                tasks.append({
                    "task": t["task"], "block": t["block"], "farm": t["farm"],
                    "plan_from": t["plan_from"], "plan_to": t["plan_to"],
                    "work_from": t["work_from"], "work_to": t["work_to"],
                    "days": t["days"], "qty": t["qty"],
                    "rate": (amt / t["qty"]) if t["qty"] else 0,
                    "amount": amt, "paid_amt": t["paid_amt"], "unpaid_amt": t["unpaid_amt"],
                    "payable_amt": t["payable_amt"], "sent_amt": t["sent_amt"],
                    "pay_status": pstat,
                    "standard": t["standard"],
                    "doc_count": len(t["docs"]),
                    "assignments": sorted(t["assignments"].keys()),
                    "planners": sorted(t["planners"].keys()),
                    "runs": sorted(t["runs"].keys()),
                    "assigned_by": sorted(t["assigned_by"].keys()),
                    "fm_approved_by": sorted(t["fm_approved_by"].keys()),
                    "entered_by": sorted(t["entered_by"].keys()),
                    "hr_approved_by": sorted(t["hr_approved_by"].keys()),
                    "gm_approved_by": sorted(t["gm_approved_by"].keys()),
                })
            tasks = sorted(tasks, key=lambda x: x["work_to"] or "", reverse=True)
            out["tasks"] = tasks
            # raw daily log
            dl = frappe.db.sql("""
                SELECT ac.name actuals, we.name rowname, we.work_date wdate, ac.task task, ac.block_section block, ac.farm farm,
                       we.actual_quantity qty, we.amount amount, ac.rate doc_rate,
                       IFNULL(we.paid,0) paid, IFNULL(we.count_in_payroll,0) in_payroll,
                       IFNULL(we.custom_reviewed,0) reviewed, we.payment_ref run_ref
                FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                WHERE """ + hconds + """
                ORDER BY we.work_date ASC
            """, tuple(hparams), as_dict=True)
            # presence evidence per worked day: first scan time + attendance status
            # (P = scan/Present, A = marked Absent yet work recorded, ? = no record)
            ev_scan = {}
            ev_att = {}
            ddates = tuple(set([str(r.wdate) for r in dl if r.wdate]))
            if ddates:
                for r2 in frappe.db.sql("""
                    SELECT DATE(`time`) d, MIN(`time`) t FROM `tabEmployee Checkin`
                    WHERE employee = %s AND DATE(`time`) IN %s GROUP BY DATE(`time`)
                """, (emp, ddates), as_dict=True):
                    ev_scan[str(r2.d)] = str(r2.t)[11:16]
                for r2 in frappe.db.sql("""
                    SELECT attendance_date d, status FROM `tabAttendance`
                    WHERE docstatus = 1 AND employee = %s AND attendance_date IN %s
                """, (emp, ddates), as_dict=True):
                    dk2 = str(r2.d)
                    if r2.status in ('Present', 'Half Day', 'Work From Home'):
                        ev_att[dk2] = r2.status
                    elif ev_att.get(dk2) not in ('Present', 'Half Day', 'Work From Home'):
                        ev_att[dk2] = r2.status
            ev_leave = {}
            ev_off = {}
            if ddates:
                dmin2 = min(ddates)
                dmax2 = max(ddates)
                for r2 in frappe.db.sql("""
                    SELECT leave_type, from_date, to_date FROM `tabLeave Application`
                    WHERE docstatus < 2 AND (status='Approved' OR docstatus=1)
                      AND employee = %s AND from_date <= %s AND to_date >= %s
                """, (emp, dmax2, dmin2), as_dict=True):
                    for dd in ddates:
                        if str(r2.from_date) <= dd <= str(r2.to_date):
                            ev_leave[dd] = r2.leave_type or "leave"
                hl2 = frappe.db.get_value("Employee", emp, "holiday_list")
                if hl2:
                    for r2 in frappe.db.sql("""
                        SELECT holiday_date FROM `tabHoliday`
                        WHERE parent = %s AND holiday_date IN %s
                    """, (hl2, ddates), as_dict=True):
                        ev_off[str(r2.holiday_date)] = 1
            daily = []
            for r in dl:
                qty = frappe.utils.flt(r.qty)
                amt = frappe.utils.flt(r.amount)
                wd = str(r.wdate) if r.wdate else None
                daily.append({
                    "actuals": r.actuals,
                    "rowname": r.rowname,
                    "doc_rate": frappe.utils.flt(r.doc_rate),
                    "editable": 1 if (not frappe.utils.cint(r.paid)) and frappe.utils.cint(r.in_payroll) else 0,
                    "wdate": wd,
                    "task": r.task, "block": r.block, "farm": r.farm,
                    "qty": qty, "amount": amt, "rate": (amt / qty) if qty else 0,
                    "paid": frappe.utils.cint(r.paid), "in_payroll": frappe.utils.cint(r.in_payroll),
                    "reviewed": frappe.utils.cint(r.reviewed), "run_ref": r.run_ref,
                    "scan_in": ev_scan.get(wd) if wd else None,
                    "att_status": ev_att.get(wd) if wd else None,
                    "day_leave": ev_leave.get(wd) if wd else None,
                    "day_off": ev_off.get(wd, 0) if wd else 0,
                })
            out["daily"] = daily
            # payment runs that include this worker -- one row per RUN, which is what
            # the heading above the table promises and what the run-count tile beside
            # it reports. Ungrouped, a run covering five days returned five rows whose
            # every visible column was run-level -- the name, the title, the payroll
            # date, the state -- so they printed identically and read as duplicates.
            # The value that told them apart was the line's own work date, which this
            # table does not show and should not: a day-row belongs on Work & days.
            #
            # Summed rather than picked, because one line's amount under a GROUP BY is
            # an arbitrary day's pay presented as the run's.
            runs = frappe.db.sql("""
                SELECT p.name run, p.run_title title, p.payroll_date rdate, p.workflow_state state,
                       SUM(l.amount) amount, SUM(l.days) days, SUM(l.qty) qty
                FROM `tabWork Payment Line` l
                INNER JOIN `tabWork Management Payment` p ON l.parent = p.name
                WHERE l.employee = %s
                GROUP BY p.name, p.run_title, p.payroll_date, p.workflow_state
                ORDER BY p.payroll_date DESC LIMIT 100
            """, (emp,), as_dict=True)
            runlist = []
            for r in runs:
                runlist.append({
                    "run": r.run, "title": r.title, "date": str(r.rdate) if r.rdate else None,
                    "state": r.state, "amount": frappe.utils.flt(r.amount),
                    "days": frappe.utils.cint(r.days), "qty": frappe.utils.flt(r.qty),
                })
            out["runs"] = runlist

    elif action == "pay_run_withdraw":
        # Return a pending payment to Unpaid: clear the reference and review stamps
        # on its rows and delete the draft payment doc — the worker redoes
        # review → send from the start.
        nm = frappe.form_dict.get("name")
        cur = frappe.db.get_value("Work Management Payment", nm, "workflow_state")
        if not cur:
            out["error"] = "Payment reference not found"
        elif cur != "Unpaid":
            out["error"] = "Only payments awaiting accounts can be returned (state: " + str(cur) + ")"
        elif frappe.db.sql("""
            SELECT sd.parent FROM `tabSalary Detail` sd
            INNER JOIN `tabAdditional Salary` a ON a.name = sd.additional_salary
            WHERE a.ref_doctype = 'Work Management Payment' AND a.ref_docname = %(n)s LIMIT 1
        """, {"n": nm}, as_dict=True):
            # payroll has already consumed this payment; withdrawing would delete
            # the document a Salary Slip is pointing at
            out["error"] = ("Cannot withdraw: a Salary Slip has already paid this through payroll. "
                            "Reverse it in payroll first.")
        else:
            # cancel the payment's Additional Salary before the document goes --
            # nothing has consumed it, so the payroll record must not outlive it
            for asr in frappe.db.sql("""
                SELECT name FROM `tabAdditional Salary`
                WHERE ref_doctype = 'Work Management Payment' AND ref_docname = %(n)s
                  AND docstatus = 1
            """, {"n": nm}, as_dict=True):
                adoc = frappe.get_doc("Additional Salary", asr.name)
                adoc.flags.ignore_permissions = True
                adoc.cancel()
            rows = frappe.db.get_all("Work Actuals Employee",
                filters={"payment_ref": nm, "paid": 0}, pluck="name")
            for rn in rows:
                frappe.db.set_value("Work Actuals Employee", rn, "payment_ref", None, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", rn, "custom_reviewed", 0, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", rn, "custom_reviewed_by", None, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", rn, "custom_reviewed_at", None, update_modified=False)
            wname = frappe.db.get_value("Work Management Payment", nm, "run_title")
            frappe.delete_doc("Work Management Payment", nm, ignore_permissions=True, force=True)
            frappe.db.commit()
            out["name"] = nm
            out["rows_reset"] = len(rows)
            out["run_title"] = wname

    elif action == "pay_worker_edit_day":
        # Audit-stage correction: change the quantity recorded for one worker-day.
        # Pay recomputes at that row's rate, parent totals are re-summed, and the
        # row's review stamp resets so it must be re-reviewed before payment.
        emp = frappe.form_dict.get("employee")
        rowname = frappe.form_dict.get("rowname")
        new_qty = frappe.utils.flt(frappe.form_dict.get("qty"))
        if not emp or not rowname:
            out["error"] = "employee and rowname are required"
        elif new_qty < 0:
            out["error"] = "Quantity cannot be negative"
        else:
            row = frappe.db.get_value("Work Actuals Employee", rowname,
                ["name", "parent", "employee", "employee_name", "work_date",
                 "actual_quantity", "amount", "paid", "count_in_payroll"], as_dict=True)
            if not row:
                out["error"] = "Record not found"
            elif row.employee != emp:
                out["error"] = "Record does not belong to this worker"
            elif frappe.utils.cint(row.paid):
                out["error"] = "This day is already paid and cannot be edited"
            elif PC_DT and frappe.db.get_value("Work Actuals Employee", rowname, "payroll_check"):
                out["error"] = ("This day is in payroll check " +
                    str(frappe.db.get_value("Work Actuals Employee", rowname, "payroll_check")) +
                    ", which its farm has approved. Send the check back to change it.")
            elif frappe.db.get_value("Work Actuals Employee", rowname, "payment_ref") and \
                 frappe.db.get_value("Work Management Payment",
                    frappe.db.get_value("Work Actuals Employee", rowname, "payment_ref"),
                    "workflow_state") == "Unpaid":
                out["error"] = ("This day is inside a payment awaiting accounts (" +
                    str(frappe.db.get_value("Work Actuals Employee", rowname, "payment_ref")) +
                    "). Return it to Unpaid first, then edit.")
            elif not frappe.utils.cint(row.count_in_payroll):
                out["error"] = "This row is not payroll-counted (salaried) — nothing to edit"
            else:
                pstate = frappe.db.get_value("Work Management Actuals", row.parent, "workflow_state")
                if pstate != "CONFIRMED":
                    out["error"] = "Actuals doc is not CONFIRMED (state: " + str(pstate) + ")"
                else:
                    old_qty = frappe.utils.flt(row.actual_quantity)
                    old_amt = frappe.utils.flt(row.amount)
                    rate = (old_amt / old_qty) if old_qty else frappe.utils.flt(
                        frappe.db.get_value("Work Management Actuals", row.parent, "rate"))
                    new_amt = round(new_qty * rate, 2)
                    frappe.db.set_value("Work Actuals Employee", rowname, "actual_quantity", new_qty, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", rowname, "amount", new_amt, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", rowname, "custom_reviewed", 0, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", rowname, "custom_reviewed_by", None, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", rowname, "custom_reviewed_at", None, update_modified=False)
                    tots = frappe.db.sql("""
                        SELECT COALESCE(SUM(actual_quantity),0) q, COALESCE(SUM(amount),0) p
                        FROM `tabWork Actuals Employee` WHERE parent=%s
                    """, (row.parent,), as_dict=True)
                    if tots:
                        frappe.db.set_value("Work Management Actuals", row.parent, "total_actual_qty", frappe.utils.flt(tots[0].q), update_modified=False)
                        frappe.db.set_value("Work Management Actuals", row.parent, "total_payment", frappe.utils.flt(tots[0].p), update_modified=False)
                    frappe.db.commit()
                    try:
                        frappe.get_doc("Work Management Actuals", row.parent).add_comment("Edited",
                            "Audit correction: " + (row.employee_name or emp) + " on " + str(row.work_date) +
                            " — qty " + str(old_qty) + " → " + str(new_qty) +
                            ", pay " + str(round(old_amt, 2)) + " → " + str(round(new_amt, 2)) +
                            " (by " + frappe.session.user + ")")
                    except Exception:
                        pass
                    out["rowname"] = rowname
                    out["qty"] = new_qty
                    out["amount"] = new_amt
                    out["rate"] = rate
                    out["parent"] = row.parent

    elif action == "pay_worker_review":
        # Stamp ONE worker's unpaid confirmed rows in the window as reviewed —
        # the audit trail between "Unpaid" and "sent to accounts".
        emp = frappe.form_dict.get("employee")
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        if not emp:
            out["error"] = "employee is required"
        else:
            rconds = "we.employee=%s AND ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0" + CHECKED_ONLY
            rparams = [emp]
            if dfrom:
                rconds = rconds + " AND we.work_date >= %s"
                rparams.append(dfrom)
            if dto:
                rconds = rconds + " AND we.work_date <= %s"
                rparams.append(dto)
            rows = frappe.db.sql("""
                SELECT we.name rowname FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                WHERE """ + rconds + """
            """, tuple(rparams), as_dict=True)
            if not rows:
                out["error"] = "No unpaid confirmed rows to review in this window"
            else:
                now = frappe.utils.now()
                for r in rows:
                    frappe.db.set_value("Work Actuals Employee", r.rowname, "custom_reviewed", 1, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", r.rowname, "custom_reviewed_by", frappe.session.user, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", r.rowname, "custom_reviewed_at", now, update_modified=False)
                frappe.db.commit()
                out["employee"] = emp
                out["rows_reviewed"] = len(rows)
                out["reviewed_by"] = frappe.session.user

    elif action == "pay_worker_submit" and not CAN_SEND:
        out["error"] = ("Only the HR head, accounting or the general manager can send work to "
                        "accounts. You can review and audit, but not create the payment.")

    elif action == "pay_worker_submit":
        # ONE SEND AT A TIME (2026-11-12): two people sending at once, or a retried
        # request, both saw the same unsent rows and both paid them. A site-wide lock
        # held for the whole send makes the second wait, then find nothing left.
        if not frappe.db.sql("SELECT GET_LOCK('wmpay-send', 60)")[0][0]:
            frappe.throw("Another payment send is running. Try again in a minute.")
        # Approve ONE worker's unpaid confirmed earnings and send them to accounts
        # as a single-worker payment run (workers are paid one at a time).
        emp = frappe.form_dict.get("employee")
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        wk_ask = wmpay_span(dfrom)
        if not emp:
            out["error"] = "employee is required"
        elif wk_ask["error"]:
            out["error"] = wk_ask["error"]
        else:
            # Workers are paid by the WEEK. One payment per worker per COMPLETED
            # pay week, so payroll receives one Additional Salary line per week
            # instead of a single lump covering several. The week still in progress
            # is held back until it closes -- otherwise that week would need a
            # second document later and payroll would see it twice.
            # Start day, end day and pay day are three independent settings. The
            # week length follows from start and end, so a week need not be seven
            # days; the pay day may be the closing day or any day after it.
            wk_names = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
            wk_start_day = frappe.db.get_single_value("Work Management Settings", "pay_week_starts_on") or "Sunday"
            wk_end_day = frappe.db.get_single_value("Work Management Settings", "pay_week_ends_on") or "Saturday"
            wk_pay_day = frappe.db.get_single_value("Work Management Settings", "pay_day") or wk_end_day
            wk_start_wd = wk_names.index(wk_start_day) if wk_start_day in wk_names else 6
            wk_end_idx = wk_names.index(wk_end_day) if wk_end_day in wk_names else 5
            wk_pay_idx = wk_names.index(wk_pay_day) if wk_pay_day in wk_names else wk_end_idx
            wk_len = ((wk_end_idx - wk_start_wd) % 7) + 1
            wconds = ("we.employee=%s AND ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0"
                      " AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0"
                      " AND IFNULL(we.payment_ref,'')=''") + TW_ONLY + CHECKED_ONLY
            wparams = [emp]
            if dfrom:
                wconds = wconds + " AND we.work_date >= %s"
                wparams.append(dfrom)
            if dto:
                wconds = wconds + " AND we.work_date <= %s"
                wparams.append(dto)
            wk_rows = frappe.db.sql("""
                SELECT we.work_date d, COALESCE(SUM(we.amount),0) a
                FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                WHERE """ + wconds + """
                GROUP BY we.work_date ORDER BY we.work_date
            """, tuple(wparams), as_dict=True)
            wk_today = frappe.utils.getdate(frappe.utils.today())
            wk_part_ok = frappe.utils.cint(frappe.db.get_single_value(
                "Work Management Settings", "allow_part_week_send"))
            wk_map = {}
            # 0 = the configured pay week; 1..31 = the range this send asked for
            wk_days = wk_ask["days"]
            wk_outside = []
            for wr in wk_rows:
                wdd = frappe.utils.getdate(wr.d)
                wk_back = (wdd.weekday() - wk_start_wd) % 7
                wk_span = wk_len
                if wk_days:
                    # a chosen range: the configured week is not consulted at all,
                    # and the range tiles forward from the first date selected.
                    # Anchoring each date's window on itself would overlap them --
                    # with a range of five the 28th would open 28th-1st and the 29th
                    # 29th-2nd, and both would claim the 30th.
                    wk_span = wk_days
                    wk_back = 0
                    if wk_days > 1:
                        wk_back = frappe.utils.date_diff(wdd, frappe.utils.getdate(dfrom)) % wk_days
                elif wk_back >= wk_len:
                    # the pay week is shorter than seven days and this weekday sits
                    # in the gap, so it belongs to no week -- reported, never dropped,
                    # and sendable only as a chosen range
                    wk_outside.append({"date": str(wr.d), "amount": frappe.utils.flt(wr.a)})
                    continue
                wk_s = frappe.utils.add_days(wdd, -wk_back)
                wk_e = frappe.utils.add_days(wk_s, wk_span - 1)
                wk_key = str(wk_s)
                if wk_key not in wk_map:
                    wk_map[wk_key] = {"week_from": str(wk_s), "week_to": str(wk_e),
                                      "amount": 0, "days": 0,
                                      "complete": 1 if (frappe.utils.getdate(wk_e) < wk_today or wk_part_ok) else 0}
                wk_map[wk_key]["amount"] = wk_map[wk_key]["amount"] + frappe.utils.flt(wr.a)
                wk_map[wk_key]["days"] = wk_map[wk_key]["days"] + 1
            wk_list = sorted(wk_map.values(), key=lambda x: x["week_from"])
            wk_ready = [w for w in wk_list if w["complete"]]
            wk_held = [w for w in wk_list if not w["complete"]]
            out["weeks"] = wk_list
            out["weeks_ready"] = wk_ready
            out["weeks_held"] = wk_held
            out["week_starts_on"] = wk_start_day
            out["week_ends_on"] = wk_end_day
            out["pay_day"] = wk_pay_day
            out["week_days"] = wk_len
            out["span_days"] = wk_days
            out["outside_any_week"] = wk_outside
            if frappe.utils.cint(frappe.form_dict.get("preview")):
                out["preview"] = 1
                out["would_create"] = len(wk_ready)
            elif not wk_ready:
                if wk_held:
                    out["error"] = ("Nothing to send yet - the only unpaid work is in the week still in "
                                    "progress (" + wk_held[0]["week_from"] + " to " + wk_held[0]["week_to"] +
                                    "). It can be sent once that week closes.")
                else:
                    out["error"] = "No unpaid confirmed earnings for this worker in the window"
            else:
                out["created"] = []
                out["skipped"] = []
                wq_from = frappe.form_dict.get("from_date")
                wq_to = frappe.form_dict.get("to_date")
                for wk in wk_ready:
                    # clamp to the caller's window: a pay week can start before or
                    # end after the range on screen, and sweeping in work outside it
                    # would pay days the sender never saw
                    dfrom = wk["week_from"]
                    dto = wk["week_to"]
                    if wq_from and str(dfrom) < str(wq_from):
                        dfrom = wq_from
                    if wq_to and str(dto) > str(wq_to):
                        dto = wq_to
                    # IFNULL(payment_ref,'')='' matters: without it a second send re-claims rows
                    # that already sit on a payment, silently orphaning the first document
                    sconds = ("we.employee=%s AND ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0"
                               " AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0"
                               " AND IFNULL(we.payment_ref,'')=''") + TW_ONLY + CHECKED_ONLY
                    sparams = [emp]
                    if dfrom:
                        sconds = sconds + " AND we.work_date >= %s"
                        sparams.append(dfrom)
                    if dto:
                        sconds = sconds + " AND we.work_date <= %s"
                        sparams.append(dto)
                    wm_agg_sql = """
                        SELECT ac.name actuals, ac.farm farm, ac.task task, ac.block_section block,
                               ac.rate doc_rate, ac.assignment assignment,
                               ac.entered_by entered_by, ac.hr_approved_by hr_approved_by,
                               ac.gm_approved_by gm_approved_by, we.employee_name nm,
                               MIN(we.work_date) wfrom, MAX(we.work_date) wto,
                               COUNT(DISTINCT we.work_date) days,
                               COALESCE(SUM(we.actual_quantity),0) qty,
                               COALESCE(SUM(we.amount),0) owed,
                               MAX(we.custom_reviewed_at) reviewed_at,
                               MAX(we.custom_reviewed_by) reviewed_by
                        FROM `tabWork Actuals Employee` we
                        INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                        WHERE """ + sconds + """
                        GROUP BY ac.name, ac.farm, ac.task, ac.block_section, ac.rate, ac.assignment,
                                 ac.entered_by, ac.hr_approved_by, ac.gm_approved_by, we.employee_name
                        ORDER BY MIN(we.work_date)
                    """
                    agg = frappe.db.sql(wm_agg_sql, tuple(sparams), as_dict=True)
                    total_owed = 0
                    for g in agg:
                        total_owed = total_owed + frappe.utils.flt(g.owed)
                    if not agg or total_owed <= 0:
                        continue
                    else:
                        # Payroll preconditions, checked BEFORE the payment is written.
                        # Mirrors hrms Additional Salary.validate(). If ERPNext could not
                        # raise the Additional Salary for this worker, no payment is created
                        # either: the work stays unpaid and unreferenced, so it is picked up
                        # on the next send once the underlying data is fixed. This keeps the
                        # payment count and the Additional Salary count identical.
                        wm_pay_on = dto
                        if not wk_days:
                            # only the recurring weekly cycle searches forward for the
                            # configured pay day - a chosen range was given an end date
                            # on purpose, and that IS the pay date
                            wm_guard = 0
                            while frappe.utils.getdate(wm_pay_on).weekday() != wk_pay_idx and wm_guard < 7:
                                wm_pay_on = frappe.utils.add_days(wm_pay_on, 1)
                                wm_guard = wm_guard + 1
                        wm_emp = frappe.db.get_value("Employee", emp,
                            ["status", "date_of_joining", "relieving_date", "employee_name", "company"], as_dict=True)
                        wm_block = None
                        if wm_emp and wm_emp.status == "Suspended":
                            wm_block = "employee is Suspended"
                        elif wm_emp and wm_emp.company and wm_emp.company != DEFAULT_COMPANY:
                            wm_block = "employee belongs to " + str(wm_emp.company) + ", not " + str(DEFAULT_COMPANY)
                        elif wm_emp and wm_emp.status == "Inactive":
                            wm_block = "employee is Inactive"
                        elif wm_emp and wm_emp.relieving_date and str(wm_pay_on) > str(wm_emp.relieving_date):
                            wm_block = ("pay date " + str(wm_pay_on) + " is after the relieving date "
                                        + str(wm_emp.relieving_date))
                        elif wm_emp and wm_emp.date_of_joining and str(wm_pay_on) < str(wm_emp.date_of_joining):
                            wm_block = ("pay date " + str(wm_pay_on) + " is before the joining date "
                                        + str(wm_emp.date_of_joining))
                        else:
                            wm_ssa = frappe.db.sql("""
                                SELECT name FROM `tabSalary Structure Assignment`
                                WHERE employee = %(e)s AND docstatus = 1 AND from_date <= %(d)s LIMIT 1
                            """, {"e": emp, "d": wm_pay_on}, as_dict=True)
                            if not wm_ssa:
                                wm_later = frappe.db.sql("""
                                    SELECT MIN(from_date) d FROM `tabSalary Structure Assignment`
                                    WHERE employee = %(e)s AND docstatus = 1
                                """, {"e": emp}, as_dict=True)
                                if wm_later and wm_later[0].d:
                                    wm_block = ("salary structure starts " + str(wm_later[0].d)
                                                + ", after the pay date " + str(wm_pay_on))
                                else:
                                    wm_block = "no submitted Salary Structure Assignment"
                        if wm_block:
                            out["skipped"].append({
                                "employee": emp,
                                "employee_name": (wm_emp.employee_name if wm_emp else None) or agg[0].nm or emp,
                                "week_from": str(dfrom),
                                "week_to": str(dto),
                                "pay_date": str(wm_pay_on),
                                "amount": frappe.utils.flt(total_owed),
                                "reason": wm_block,
                            })
                            continue
                        ename = agg[0].nm or frappe.db.get_value("Employee", emp, "employee_name") or emp
                        wm_savepoint = "wmsingle" + frappe.generate_hash(length=10)
                        frappe.db.savepoint(wm_savepoint)
                        try:
                            # Late work for a week already sent: hrms allows one Additional Salary per
                            # worker, component and pay date, so instead of a second one the week is
                            # re-sent whole -- see release_sent_week_for_topup(). Inside the savepoint,
                            # so a failed re-send restores the earlier run and its Additional Salary.
                            wm_topup = release_sent_week_for_topup(emp,
                                frappe.db.get_single_value("Work Management Settings", "salary_component"),
                                wm_pay_on, dfrom, dto)
                            if wm_topup.get("block"):
                                frappe.db.rollback(save_point=wm_savepoint)
                                out["skipped"].append({
                                    "employee": emp, "employee_name": ename,
                                    "week_from": str(dfrom), "week_to": str(dto),
                                    "pay_date": str(wm_pay_on),
                                    "amount": frappe.utils.flt(total_owed),
                                    "reason": wm_topup["block"],
                                })
                                continue
                            if wm_topup.get("released"):
                                agg = frappe.db.sql(wm_agg_sql, tuple(sparams), as_dict=True)
                                total_owed = 0
                                for g in agg:
                                    total_owed = total_owed + frappe.utils.flt(g.owed)
                            d = frappe.new_doc("Work Management Payment")
                            d.run_title = "Worker payment — " + ename + " — " + frappe.utils.today()
                            d.company = DEFAULT_COMPANY
                            # payroll date = the first pay day on or after the week ends, so
                            # setting the pay day to the closing day pays on that day.
                            # A chosen range skips the search - its own end date is the
                            # pay date, not a day found by walking forward from it.
                            pd_val = dto
                            if not wk_days:
                                pd_guard = 0
                                while frappe.utils.getdate(pd_val).weekday() != wk_pay_idx and pd_guard < 7:
                                    pd_val = frappe.utils.add_days(pd_val, 1)
                                    pd_guard = pd_guard + 1
                            d.payroll_date = pd_val
                            d.prepared_by = frappe.session.user
                            try:
                                if dfrom:
                                    d.period_from = dfrom
                                if dto:
                                    d.period_to = dto
                            except Exception:
                                pass
                            # one traceable line per actuals doc this worker earned on, carrying
                            # the full accountability chain from the review sheet: who assigned
                            # the job, who entered actuals, and every approver.
                            asg_cache = {}
                            total_days = 0
                            total_qty = 0
                            rv_by = None
                            rv_at = None
                            for g in agg:
                                if frappe.utils.flt(g.owed) <= 0:
                                    continue
                                ai = None
                                if g.assignment:
                                    ai = asg_cache.get(g.assignment)
                                    if ai is None:
                                        ai = frappe.db.get_value("Work Management Assigner", g.assignment,
                                            ["assigned_by", "approved_by"], as_dict=True)
                                        asg_cache[g.assignment] = ai
                                qty = frappe.utils.flt(g.qty)
                                owed = frappe.utils.flt(g.owed)
                                row = d.append("lines", {})
                                row.actuals = g.actuals
                                row.employee = emp
                                row.employee_name = ename
                                row.farm = g.farm
                                row.task = g.task
                                row.block = g.block
                                row.work_from = g.wfrom
                                row.work_to = g.wto
                                row.days = g.days
                                row.qty = qty
                                row.rate = frappe.utils.flt(g.doc_rate) or ((owed / qty) if qty else 0)
                                row.assignment = g.assignment
                                row.assigned_by = ai.assigned_by if ai else None
                                row.fm_approved_by = ai.approved_by if ai else None
                                row.entered_by = g.entered_by
                                row.hr_approved_by = g.hr_approved_by
                                row.gm_approved_by = g.gm_approved_by
                                row.paid_workers = 1
                                row.amount = owed
                                total_days = total_days + frappe.utils.cint(g.days)
                                total_qty = total_qty + qty
                                if g.reviewed_at and (not rv_at or str(g.reviewed_at) > str(rv_at)):
                                    rv_at = g.reviewed_at
                                    rv_by = g.reviewed_by
                            # worker-centric header: one payment entry per employee
                            d.employee = emp
                            d.employee_name = ename
                            d.farm = agg[0].farm
                            d.total_days = total_days
                            d.total_qty = total_qty
                            d.amount = total_owed
                            d.total_workers = 1
                            d.total_actuals = len(d.lines)
                            d.flags.ignore_permissions = True
                            d.insert(ignore_permissions=True)
                            frappe.db.set_value("Work Management Payment", d.name, "workflow_state", "Unpaid", update_modified=False)
                            # Sending to payroll raises the Additional Salary right away -- see
                            # raise_additional_salary_for_payment(). The payment stays Unpaid
                            # (docstatus stays 0 for this whole chain, by design -- see the
                            # comment on CHAIN_ENDS["Work Management Payment"]) until payroll
                            # submits the Salary Slip that carries it; only then does
                            # workflow_state move to Paid -- see on_salary_slip_submit().
                            wm_component = frappe.db.get_single_value("Work Management Settings", "salary_component")
                            wm_as_name = raise_additional_salary_for_payment(
                                d.name, emp, ename, wm_component, total_owed, pd_val, DEFAULT_COMPANY)
                            frappe.db.set_value("Work Management Payment", d.name, "custom_submitted_at", frappe.utils.now(), update_modified=False)
                            # stamp the reference on the included rows (NOT paid yet -- that
                            # follows once payroll submits the Salary Slip, on_salary_slip_submit())
                            refrows = frappe.db.sql("""
                                SELECT we.name rowname FROM `tabWork Actuals Employee` we
                                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                                WHERE """ + sconds + """
                            """, tuple(sparams), as_dict=True)
                            subnow = frappe.utils.now()
                            if refrows:
                                # stamp only rows still unsent; if any were taken meanwhile, undo this week
                                frappe.db.sql("""UPDATE `tabWork Actuals Employee` SET payment_ref = %s
                                    WHERE name IN %s AND IFNULL(payment_ref, '') = ''""",
                                    (d.name, tuple([x.rowname for x in refrows])))
                                if frappe.db.count("Work Actuals Employee", {"payment_ref": d.name}) != len(refrows):
                                    frappe.throw("Some of these days were sent by somebody else meanwhile.")
                            for rr in refrows:
                                frappe.db.set_value("Work Actuals Employee", rr.rowname, "payment_ref", d.name, update_modified=False)
                                frappe.db.set_value("Work Actuals Employee", rr.rowname, "custom_reviewed", 1, update_modified=False)
                                frappe.db.set_value("Work Actuals Employee", rr.rowname, "custom_reviewed_by", frappe.session.user, update_modified=False)
                                frappe.db.set_value("Work Actuals Employee", rr.rowname, "custom_reviewed_at", subnow, update_modified=False)
                            frappe.db.commit()
                            out["created"].append({
                                "name": d.name, "workflow_state": "Unpaid",
                                "employee": emp, "employee_name": ename,
                                "week_from": dfrom, "week_to": dto,
                                "payroll_date": str(frappe.db.get_value("Work Management Payment", d.name, "payroll_date") or ""),
                                "amount": total_owed,
                                "additional_salary": wm_as_name,
                                "days": sum(frappe.utils.cint(x.days) for x in agg)})
                        except Exception as wm_exc:
                            # isolate this WEEK's failure -- this worker's other, already
                            # committed weeks (see the per-week commit below) must not be
                            # lost just because a later week could not raise its Additional
                            # Salary.
                            frappe.db.rollback(save_point=wm_savepoint)
                            frappe.log_error(
                                title="Work Management: payroll send failed for one week",
                                message=frappe.get_traceback(),
                            )
                            out["skipped"].append({
                                "employee": emp, "employee_name": ename,
                                "week_from": str(dfrom), "week_to": str(dto),
                                "amount": frappe.utils.flt(total_owed),
                                "reason": "could not raise Additional Salary: " + str(wm_exc),
                            })
                            continue
                        # no explicit release_savepoint here: frappe.db.commit()
                        # above already ends the transaction and discards it --
                        # releasing it again afterwards would error ("no such
                        # savepoint").

    elif action == "pay_bulk_review":
        # Stamp SEVERAL workers' unpaid confirmed rows as reviewed in one call.
        # Same stamps as pay_worker_review, looped; employees is a CSV list.
        emps_raw = frappe.form_dict.get("employees")
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        emp_list = []
        if emps_raw:
            for e in emps_raw.split(","):
                ev = e.strip()
                if ev and ev not in emp_list:
                    emp_list.append(ev)
        if not emp_list:
            out["error"] = "employees is required (CSV)"
        else:
            now = frappe.utils.now()
            results = []
            total_rows = 0
            for emp in emp_list:
                rconds = "we.employee=%s AND ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0" + CHECKED_ONLY
                rparams = [emp]
                if dfrom:
                    rconds = rconds + " AND we.work_date >= %s"
                    rparams.append(dfrom)
                if dto:
                    rconds = rconds + " AND we.work_date <= %s"
                    rparams.append(dto)
                rows = frappe.db.sql("""
                    SELECT we.name rowname FROM `tabWork Actuals Employee` we
                    INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                    WHERE """ + rconds + """
                """, tuple(rparams), as_dict=True)
                if not rows:
                    results.append({"employee": emp, "rows": 0, "error": "no unpaid confirmed rows"})
                    continue
                for r in rows:
                    frappe.db.set_value("Work Actuals Employee", r.rowname, "custom_reviewed", 1, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", r.rowname, "custom_reviewed_by", frappe.session.user, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", r.rowname, "custom_reviewed_at", now, update_modified=False)
                total_rows = total_rows + len(rows)
                results.append({"employee": emp, "rows": len(rows)})
            frappe.db.commit()
            out["results"] = results
            out["workers_reviewed"] = len([r for r in results if not r.get("error")])
            out["rows_reviewed"] = total_rows
            out["reviewed_by"] = frappe.session.user

    elif action == "pay_bulk_submit" and not CAN_SEND:
        out["error"] = ("Only the HR head, accounting or the general manager can send work to "
                        "accounts. You can review and audit, but not create the payment.")

    elif action == "pay_bulk_submit":
        # ONE SEND AT A TIME (2026-11-12): two people sending at once, or a retried
        # request, both saw the same unsent rows and both paid them. A site-wide lock
        # held for the whole send makes the second wait, then find nothing left.
        if not frappe.db.sql("SELECT GET_LOCK('wmpay-send', 60)")[0][0]:
            frappe.throw("Another payment send is running. Try again in a minute.")
        # Send SEVERAL reviewed workers to accounts in one call: one Work
        # Management Payment per employee (same shape as pay_worker_submit).
        # A worker with any unreviewed unpaid rows is skipped — review first.
        emps_raw = frappe.form_dict.get("employees")
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        emp_list = []
        if emps_raw:
            for e in emps_raw.split(","):
                ev = e.strip()
                if ev and ev not in emp_list:
                    emp_list.append(ev)
        bw_ask = wmpay_span(dfrom)
        if not emp_list:
            out["error"] = "employees is required (CSV)"
        elif bw_ask["error"]:
            out["error"] = bw_ask["error"]
        else:
            results = []
            sent = 0
            sent_total = 0
            bw_from = dfrom
            bw_to = dto
            bw_names = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
            bw_start_day = frappe.db.get_single_value("Work Management Settings", "pay_week_starts_on") or "Sunday"
            bw_end_day = frappe.db.get_single_value("Work Management Settings", "pay_week_ends_on") or "Saturday"
            bw_pay_day = frappe.db.get_single_value("Work Management Settings", "pay_day") or bw_end_day
            bw_start_wd = bw_names.index(bw_start_day) if bw_start_day in bw_names else 6
            bw_end_idx = bw_names.index(bw_end_day) if bw_end_day in bw_names else 5
            bw_pay_idx = bw_names.index(bw_pay_day) if bw_pay_day in bw_names else bw_end_idx
            bw_len = ((bw_end_idx - bw_start_wd) % 7) + 1
            bw_today = frappe.utils.getdate(frappe.utils.today())
            bw_part_ok = frappe.utils.cint(frappe.db.get_single_value(
                "Work Management Settings", "allow_part_week_send"))
            # 0 = the configured pay week; 1..31 = the range this send asked for
            bw_days = bw_ask["days"]
            # what the pay week leaves over. The single send has always reported
            # these; the bulk send dropped them without a word, which is how 5,027
            # Monday lines went unpayable and unnoticed on a Tuesday-to-Sunday week.
            bw_outside = []
            for emp in emp_list:
                # same weekly rule as the single send: one payment per worker per
                # COMPLETED pay week, with the week in progress held back
                dfrom = bw_from
                dto = bw_to
                bconds = ("we.employee=%s AND ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0"
                           " AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0"
                           " AND IFNULL(we.payment_ref,'')=''") + TW_ONLY + CHECKED_ONLY
                bparams = [emp]
                if dfrom:
                    bconds = bconds + " AND we.work_date >= %s"
                    bparams.append(dfrom)
                if dto:
                    bconds = bconds + " AND we.work_date <= %s"
                    bparams.append(dto)
                bwk_rows = frappe.db.sql("""
                    SELECT we.work_date d FROM `tabWork Actuals Employee` we
                    INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                    WHERE """ + bconds + """
                    GROUP BY we.work_date
                """, tuple(bparams), as_dict=True)
                bwk = {}
                for br in bwk_rows:
                    bdd = frappe.utils.getdate(br.d)
                    bback = (bdd.weekday() - bw_start_wd) % 7
                    bspan = bw_len
                    if bw_days:
                        # a chosen range, tiled forward from the first date
                        # selected so two windows never claim the same day
                        bspan = bw_days
                        bback = 0
                        if bw_days > 1:
                            bback = frappe.utils.date_diff(bdd, frappe.utils.getdate(bw_from)) % bw_days
                    elif bback >= bw_len:
                        bw_outside.append({"employee": emp, "date": str(br.d)})
                        continue
                    bs = frappe.utils.add_days(bdd, -bback)
                    be = frappe.utils.add_days(bs, bspan - 1)
                    if frappe.utils.getdate(be) < bw_today or bw_part_ok:
                        bwk[str(bs)] = {"week_from": str(bs), "week_to": str(be)}
                for wk in sorted(bwk.values(), key=lambda x: x["week_from"]):
                    dfrom = wk["week_from"]
                    dto = wk["week_to"]
                    if bw_from and str(dfrom) < str(bw_from):
                        dfrom = bw_from
                    if bw_to and str(dto) > str(bw_to):
                        dto = bw_to
                    # IFNULL(payment_ref,'')='' matters: without it a second send re-claims rows
                    # that already sit on a payment, silently orphaning the first document
                    sconds = "we.employee=%s AND ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0 AND IFNULL(we.payment_ref,'')=''" + CHECKED_ONLY
                    sparams = [emp]
                    if dfrom:
                        sconds = sconds + " AND we.work_date >= %s"
                        sparams.append(dfrom)
                    if dto:
                        sconds = sconds + " AND we.work_date <= %s"
                        sparams.append(dto)
                    bw_agg_sql = """
                        SELECT ac.name actuals, ac.farm farm, ac.task task, ac.block_section block,
                               ac.rate doc_rate, ac.assignment assignment,
                               ac.entered_by entered_by, ac.hr_approved_by hr_approved_by,
                               ac.gm_approved_by gm_approved_by, we.employee_name nm,
                               MIN(we.work_date) wfrom, MAX(we.work_date) wto,
                               COUNT(DISTINCT we.work_date) days,
                               COALESCE(SUM(we.actual_quantity),0) qty,
                               COALESCE(SUM(we.amount),0) owed,
                               MAX(we.custom_reviewed_at) reviewed_at,
                               MAX(we.custom_reviewed_by) reviewed_by
                        FROM `tabWork Actuals Employee` we
                        INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                        WHERE """ + sconds + """
                        GROUP BY ac.name, ac.farm, ac.task, ac.block_section, ac.rate, ac.assignment,
                                 ac.entered_by, ac.hr_approved_by, ac.gm_approved_by, we.employee_name
                        ORDER BY MIN(we.work_date)
                    """
                    agg = frappe.db.sql(bw_agg_sql, tuple(sparams), as_dict=True)
                    total_owed = 0
                    for g in agg:
                        total_owed = total_owed + frappe.utils.flt(g.owed)
                    if not agg or total_owed <= 0:
                        results.append({"employee": emp, "error": "no unpaid confirmed earnings in window"})
                        continue
                    ename = agg[0].nm or frappe.db.get_value("Employee", emp, "employee_name") or emp
                    # Payroll preconditions, checked BEFORE the payment is written -- the
                    # same block the single send has always run. A worker ERPNext would
                    # refuse must not get a payment document either: otherwise the work is
                    # stamped "sent to accounts" with no payroll record behind it, and the
                    # Issues tab cannot show it, because that tab only lists UNSENT work.
                    bw_pay_on = dto
                    if not bw_days:
                        # only the recurring weekly cycle searches forward for the
                        # configured pay day - a chosen range was given an end date
                        # on purpose, and that IS the pay date
                        bw_guard = 0
                        while frappe.utils.getdate(bw_pay_on).weekday() != bw_pay_idx and bw_guard < 7:
                            bw_pay_on = frappe.utils.add_days(bw_pay_on, 1)
                            bw_guard = bw_guard + 1
                    bw_emp = frappe.db.get_value("Employee", emp,
                        ["status", "date_of_joining", "relieving_date", "employee_name", "company"], as_dict=True)
                    bw_block = None
                    if bw_emp and bw_emp.status == "Suspended":
                        bw_block = "employee is Suspended"
                    elif bw_emp and bw_emp.company and bw_emp.company != DEFAULT_COMPANY:
                        bw_block = "employee belongs to " + str(bw_emp.company) + ", not " + str(DEFAULT_COMPANY)
                    elif bw_emp and bw_emp.status == "Inactive":
                        bw_block = "employee is Inactive"
                    elif bw_emp and bw_emp.relieving_date and str(bw_pay_on) > str(bw_emp.relieving_date):
                        bw_block = ("pay date " + str(bw_pay_on) + " is after the relieving date "
                                    + str(bw_emp.relieving_date))
                    elif bw_emp and bw_emp.date_of_joining and str(bw_pay_on) < str(bw_emp.date_of_joining):
                        bw_block = ("pay date " + str(bw_pay_on) + " is before the joining date "
                                    + str(bw_emp.date_of_joining))
                    else:
                        bw_ssa = frappe.db.sql("""
                            SELECT name FROM `tabSalary Structure Assignment`
                            WHERE employee = %(e)s AND docstatus = 1 AND from_date <= %(d)s LIMIT 1
                        """, {"e": emp, "d": bw_pay_on}, as_dict=True)
                        if not bw_ssa:
                            bw_later = frappe.db.sql("""
                                SELECT MIN(from_date) d FROM `tabSalary Structure Assignment`
                                WHERE employee = %(e)s AND docstatus = 1
                            """, {"e": emp}, as_dict=True)
                            if bw_later and bw_later[0].d:
                                bw_block = ("salary structure starts " + str(bw_later[0].d)
                                            + ", after the pay date " + str(bw_pay_on))
                            else:
                                bw_block = "no submitted Salary Structure Assignment"
                    if bw_block:
                        results.append({"employee": emp, "employee_name": ename,
                                        "week_from": str(dfrom), "week_to": str(dto),
                                        "pay_date": str(bw_pay_on),
                                        "amount": frappe.utils.flt(total_owed),
                                        "skipped": 1, "reason": bw_block})
                        continue
                    bw_savepoint = "wmbulk" + frappe.generate_hash(length=10)
                    frappe.db.savepoint(bw_savepoint)
                    try:
                        # Late work for a week already sent: hrms allows one Additional Salary per
                        # worker, component and pay date, so instead of a second one the week is
                        # re-sent whole -- see release_sent_week_for_topup(). Inside the savepoint,
                        # so a failed re-send restores the earlier run and its Additional Salary.
                        bw_topup = release_sent_week_for_topup(emp,
                            frappe.db.get_single_value("Work Management Settings", "salary_component"),
                            bw_pay_on, dfrom, dto)
                        if bw_topup.get("block"):
                            frappe.db.rollback(save_point=bw_savepoint)
                            results.append({"employee": emp, "employee_name": ename,
                                            "week_from": str(dfrom), "week_to": str(dto),
                                            "pay_date": str(bw_pay_on),
                                            "amount": frappe.utils.flt(total_owed),
                                            "skipped": 1, "reason": bw_topup["block"]})
                            continue
                        if bw_topup.get("released"):
                            agg = frappe.db.sql(bw_agg_sql, tuple(sparams), as_dict=True)
                            total_owed = 0
                            for g in agg:
                                total_owed = total_owed + frappe.utils.flt(g.owed)
                        d = frappe.new_doc("Work Management Payment")
                        d.run_title = "Worker payment — " + ename + " — " + frappe.utils.today()
                        d.company = DEFAULT_COMPANY
                        # payroll date = the day the week closes, which IS the pay day, so a
                        # week's earnings land on one known date for everyone
                        # payroll date = the first pay day on or after the week ends.
                        # A chosen range skips the search - its own end date is the
                        # pay date, not a day found by walking forward from it.
                        pd_val = dto
                        if not bw_days:
                            pd_guard = 0
                            while frappe.utils.getdate(pd_val).weekday() != bw_pay_idx and pd_guard < 7:
                                pd_val = frappe.utils.add_days(pd_val, 1)
                                pd_guard = pd_guard + 1
                        d.payroll_date = pd_val
                        d.prepared_by = frappe.session.user
                        try:
                            if dfrom:
                                d.period_from = dfrom
                            if dto:
                                d.period_to = dto
                        except Exception:
                            pass
                        asg_cache = {}
                        total_days = 0
                        total_qty = 0
                        rv_by = None
                        rv_at = None
                        for g in agg:
                            if frappe.utils.flt(g.owed) <= 0:
                                continue
                            ai = None
                            if g.assignment:
                                ai = asg_cache.get(g.assignment)
                                if ai is None:
                                    ai = frappe.db.get_value("Work Management Assigner", g.assignment,
                                        ["assigned_by", "approved_by"], as_dict=True)
                                    asg_cache[g.assignment] = ai
                            qty = frappe.utils.flt(g.qty)
                            owed = frappe.utils.flt(g.owed)
                            row = d.append("lines", {})
                            row.actuals = g.actuals
                            row.employee = emp
                            row.employee_name = ename
                            row.farm = g.farm
                            row.task = g.task
                            row.block = g.block
                            row.work_from = g.wfrom
                            row.work_to = g.wto
                            row.days = g.days
                            row.qty = qty
                            row.rate = frappe.utils.flt(g.doc_rate) or ((owed / qty) if qty else 0)
                            row.assignment = g.assignment
                            row.assigned_by = ai.assigned_by if ai else None
                            row.fm_approved_by = ai.approved_by if ai else None
                            row.entered_by = g.entered_by
                            row.hr_approved_by = g.hr_approved_by
                            row.gm_approved_by = g.gm_approved_by
                            row.paid_workers = 1
                            row.amount = owed
                            total_days = total_days + frappe.utils.cint(g.days)
                            total_qty = total_qty + qty
                            if g.reviewed_at and (not rv_at or str(g.reviewed_at) > str(rv_at)):
                                rv_at = g.reviewed_at
                                rv_by = g.reviewed_by
                        d.employee = emp
                        d.employee_name = ename
                        d.farm = agg[0].farm
                        d.total_days = total_days
                        d.total_qty = total_qty
                        d.amount = total_owed
                        d.total_workers = 1
                        d.total_actuals = len(d.lines)
                        d.flags.ignore_permissions = True
                        d.insert(ignore_permissions=True)
                        frappe.db.set_value("Work Management Payment", d.name, "workflow_state", "Unpaid", update_modified=False)
                        # Sending to payroll raises the Additional Salary right away -- see
                        # raise_additional_salary_for_payment(). The payment itself stays a
                        # draft, exactly as before (so "Return to unpaid" can still delete
                        # it) until payroll submits the Salary Slip that carries it -- only
                        # then does it become Paid and a real, submitted record; see
                        # on_salary_slip_submit().
                        bw_component = frappe.db.get_single_value("Work Management Settings", "salary_component")
                        bw_as_name = raise_additional_salary_for_payment(
                            d.name, emp, ename, bw_component, total_owed, pd_val, DEFAULT_COMPANY)
                        frappe.db.set_value("Work Management Payment", d.name, "custom_submitted_at", frappe.utils.now(), update_modified=False)
                        # stamp the reference on the included rows (NOT paid yet -- that
                        # follows once payroll submits the Salary Slip, on_salary_slip_submit())
                        refrows = frappe.db.sql("""
                            SELECT we.name rowname FROM `tabWork Actuals Employee` we
                            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                            WHERE """ + sconds + """
                        """, tuple(sparams), as_dict=True)
                        bulknow = frappe.utils.now()
                        if refrows:
                            frappe.db.sql("""UPDATE `tabWork Actuals Employee` SET payment_ref = %s
                                WHERE name IN %s AND IFNULL(payment_ref, '') = ''""",
                                (d.name, tuple([x.rowname for x in refrows])))
                            if frappe.db.count("Work Actuals Employee", {"payment_ref": d.name}) != len(refrows):
                                frappe.throw("Some of these days were sent by somebody else meanwhile.")
                        for rr in refrows:
                            frappe.db.set_value("Work Actuals Employee", rr.rowname, "payment_ref", d.name, update_modified=False)
                            frappe.db.set_value("Work Actuals Employee", rr.rowname, "custom_reviewed", 1, update_modified=False)
                            frappe.db.set_value("Work Actuals Employee", rr.rowname, "custom_reviewed_by", frappe.session.user, update_modified=False)
                            frappe.db.set_value("Work Actuals Employee", rr.rowname, "custom_reviewed_at", bulknow, update_modified=False)
                        sent = sent + 1
                        sent_total = sent_total + total_owed
                        results.append({"employee": emp, "employee_name": ename, "name": d.name,
                                        "week_from": dfrom, "week_to": dto, "amount": total_owed,
                                        "additional_salary": bw_as_name})
                    except Exception as bw_exc:
                        # one worker/week's failure (bad salary structure config, a
                        # duplicate/overlapping Additional Salary, a currency lookup
                        # issue, ...) must not cost every OTHER worker already
                        # processed in this same bulk send. Roll back only this
                        # iteration's half-written Payment + Additional Salary --
                        # everything before it was already committed below -- and
                        # keep going so the rest of the batch still lands.
                        frappe.db.rollback(save_point=bw_savepoint)
                        frappe.log_error(
                            title="Work Management: bulk payroll send failed for one worker",
                            message=frappe.get_traceback(),
                        )
                        results.append({"employee": emp, "employee_name": ename,
                                        "week_from": str(dfrom), "week_to": str(dto),
                                        "amount": frappe.utils.flt(total_owed),
                                        "error": str(bw_exc)})
                        continue
                    else:
                        frappe.db.release_savepoint(bw_savepoint)
                        # commit THIS worker/week now, not at the end of the whole
                        # batch -- so a later worker's failure can only roll back
                        # their own savepoint, never work already banked here.
                        frappe.db.commit()
            frappe.db.commit()
            out["results"] = results
            out["sent"] = sent
            out["sent_total"] = sent_total
            out["errors"] = len([r for r in results if r.get("error")])
            out["skipped"] = len([r for r in results if r.get("skipped")])
            out["skipped_total"] = sum(frappe.utils.flt(r.get("amount")) for r in results if r.get("skipped"))
            # never silent again: a date the pay week leaves out is named, not dropped
            out["outside_pay_week"] = bw_outside
            out["span_days"] = bw_days

    elif action == "pay_absent_conflicts":
        # AUDIT: every confirmed worker-day with money recorded on a day that
        # worker was marked ABSENT (submitted attendance). Scan time attached so
        # reviewers can tell "attendance wrongly marked" (has a scan) from a
        # possible ghost entry (no scan either). Optional farm + date filters.
        cfarm = (frappe.form_dict.get("farm") or "").strip()
        cfrom = frappe.form_dict.get("from_date")
        cto = frappe.form_dict.get("to_date")
        cconds = "ac.workflow_state='CONFIRMED' AND we.amount > 0"
        cparams = []
        if cfarm:
            cconds = cconds + " AND TRIM(ac.farm) = TRIM(%s)"
            cparams.append(cfarm)
        if cfrom:
            cconds = cconds + " AND we.work_date >= %s"
            cparams.append(cfrom)
        if cto:
            cconds = cconds + " AND we.work_date <= %s"
            cparams.append(cto)
        crows = frappe.db.sql("""
            SELECT we.employee, we.employee_name, ac.farm, ac.task, ac.name actuals,
                   we.work_date wdate, we.actual_quantity qty, we.amount,
                   IFNULL(we.paid,0) paid, we.payment_ref run_ref,
                   ac.entered_by entered_by
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            INNER JOIN `tabAttendance` att ON att.employee = we.employee
                  AND att.attendance_date = we.work_date
                  AND att.docstatus = 1 AND att.status = 'Absent'
            WHERE """ + cconds + """
            ORDER BY we.work_date DESC, we.employee
            LIMIT 2000
        """, tuple(cparams), as_dict=True)
        # scan evidence for those exact worker-days
        scan_ev = {}
        if crows:
            cemps = tuple(set([r.employee for r in crows]))
            cdates = tuple(set([str(r.wdate) for r in crows]))
            for r2 in frappe.db.sql("""
                SELECT employee, DATE(`time`) d, MIN(`time`) t FROM `tabEmployee Checkin`
                WHERE employee IN %s AND DATE(`time`) IN %s
                GROUP BY employee, DATE(`time`)
            """, (cemps, cdates), as_dict=True):
                scan_ev[(r2.employee, str(r2.d))] = str(r2.t)[11:16]
        rows_out = []
        tot_amt = 0
        tot_paid = 0
        wset = {}
        for r in crows:
            wd = str(r.wdate)
            amt = frappe.utils.flt(r.amount)
            tot_amt = tot_amt + amt
            if frappe.utils.cint(r.paid):
                tot_paid = tot_paid + amt
            wset[r.employee] = 1
            rows_out.append({
                "employee": r.employee, "employee_name": r.employee_name,
                "farm": r.farm, "task": r.task, "actuals": r.actuals,
                "wdate": wd, "qty": frappe.utils.flt(r.qty), "amount": amt,
                "paid": frappe.utils.cint(r.paid), "run_ref": r.run_ref,
                "entered_by": r.entered_by,
                "scan_in": scan_ev.get((r.employee, wd)),
            })
        out["rows"] = rows_out
        out["summary"] = {
            "rows": len(rows_out), "workers": len(wset),
            "amount": tot_amt, "paid_amount": tot_paid,
            "unpaid_amount": tot_amt - tot_paid,
            "with_scan": len([x for x in rows_out if x["scan_in"]]),
            "no_scan": len([x for x in rows_out if not x["scan_in"]]),
        }

    elif action == "pay_discrepancies":
        # AUDIT / DISCREPANCY ENGINE — every check is a way money can leak or a
        # record can lie. Each returns auditable rows (worker, day, doc) so the
        # reviewer can open the worker's sheet or the actuals doc directly.
        dfarm = (frappe.form_dict.get("farms") or "").strip()
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        if not dfrom:
            dfrom = str(frappe.utils.add_days(frappe.utils.today(), -31))
        if not dto:
            dto = str(frappe.utils.today())
        # per-check enable toggles (Work Management Settings; default ON)
        disc_on = {}
        for dk in ("disc_absent_paid", "disc_ghost_days", "disc_leave_paid", "disc_off_paid",
                   "disc_rate_mismatch", "disc_multi_farm", "disc_self_approved", "disc_left_earning",
                   "disc_no_pay", "disc_dup_day", "disc_inactive_assigned",
                   "disc_long_day", "disc_short_day", "disc_hours_vs_qty"):
            val = 1
            try:
                val = frappe.utils.cint(frappe.db.get_single_value("Work Management Settings", dk))
            except Exception:
                val = 1
            disc_on[dk] = val
        dconds = "ac.workflow_state='CONFIRMED' AND we.amount > 0 AND we.work_date BETWEEN %s AND %s"
        dparams = [dfrom, dto]
        farm_list_d = []
        if dfarm:
            for f in dfarm.split(","):
                fv = f.strip()
                if fv:
                    farm_list_d.append(fv)
        if farm_list_d:
            dconds = dconds + " AND TRIM(ac.farm) IN %s"
            dparams.append(tuple(farm_list_d))
        base_rows = frappe.db.sql("""
            SELECT we.name rowname, we.employee, we.employee_name, ac.farm, ac.task,
                   ac.name actuals, we.work_date wdate, we.actual_quantity qty,
                   we.amount, IFNULL(we.paid,0) paid, we.payment_ref run_ref,
                   ac.rate doc_rate, IFNULL(we.count_in_payroll,0) in_pay,
                   ac.entered_by entered_by, we.hours hours,
                   p3.uom plan_uom, p3.daily_target dtarget
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            -- the unit and the daily target live on the plan, not on the actuals, and
            -- the three hours checks below cannot be asked without them. Both joins
            -- are on primary keys.
            LEFT JOIN `tabWork Management Assigner` a3 ON ac.assignment = a3.name
            LEFT JOIN `tabWork Management Planner` p3 ON a3.planner_request = p3.name
            WHERE """ + dconds + """
            ORDER BY we.work_date DESC
            LIMIT 30000
        """, tuple(dparams), as_dict=True)
        # ---- evidence maps for the window ----
        demps = tuple(set([r.employee for r in base_rows])) or ("__none__",)
        scan_ev = {}
        att_ev = {}
        for r2 in frappe.db.sql("""
            SELECT employee, DATE(`time`) d, MIN(`time`) t FROM `tabEmployee Checkin`
            WHERE employee IN %s AND DATE(`time`) BETWEEN %s AND %s
            GROUP BY employee, DATE(`time`)
        """, (demps, dfrom, dto), as_dict=True):
            scan_ev[(r2.employee, str(r2.d))] = str(r2.t)[11:16]
        for r2 in frappe.db.sql("""
            SELECT employee, attendance_date d, status FROM `tabAttendance`
            WHERE docstatus = 1 AND employee IN %s AND attendance_date BETWEEN %s AND %s
        """, (demps, dfrom, dto), as_dict=True):
            kk2 = (r2.employee, str(r2.d))
            # corrected attendance: a Present-class record beats an Absent one
            if r2.status in ('Present', 'Half Day', 'Work From Home'):
                att_ev[kk2] = r2.status
            elif att_ev.get(kk2) not in ('Present', 'Half Day', 'Work From Home'):
                att_ev[kk2] = r2.status
        leave_ev = {}
        for r2 in frappe.db.sql("""
            SELECT employee, leave_type, from_date, to_date FROM `tabLeave Application`
            WHERE docstatus < 2 AND (status='Approved' OR docstatus=1)
              AND from_date <= %s AND to_date >= %s AND employee IN %s
        """, (dto, dfrom, demps), as_dict=True):
            lst = leave_ev.get(r2.employee)
            if lst is None:
                lst = []
                leave_ev[r2.employee] = lst
            lst.append((str(r2.from_date), str(r2.to_date), r2.leave_type or "leave"))
        hl_ev = {}
        for r2 in frappe.db.sql("""
            SELECT name, holiday_list FROM `tabEmployee`
            WHERE name IN %s AND IFNULL(holiday_list,'') != ''
        """, (demps,), as_dict=True):
            hl_ev[r2.name] = r2.holiday_list
        off_ev = {}
        if hl_ev:
            for r2 in frappe.db.sql("""
                SELECT parent, holiday_date FROM `tabHoliday`
                WHERE parent IN %s AND holiday_date BETWEEN %s AND %s
            """, (tuple(set(hl_ev.values())), dfrom, dto), as_dict=True):
                off_ev[(r2.parent, str(r2.holiday_date))] = 1
        # ---- single pass: bucket rows into the presence-based checks ----
        today_d = str(frappe.utils.today())
        b_absent = []
        b_ghost = []
        b_leave = []
        b_off = []
        b_rate = []
        # ---- THE THREE HOURS CHECKS ----
        # A day used to be atomic here, so none of these could be asked. Now that a
        # worker's day can be split between tasks and the hours are recorded, three
        # things can contradict each other and are worth a person's attention.
        #
        # Hours absent read as a full day, which is what every row written before the
        # field existed means -- so history does not light up the moment this ships.
        b_long = []
        b_short = []
        b_hqty = []
        day_h = {}
        day_money = {}
        day_where = {}
        day_rows = {}
        name_of = {}
        for r in base_rows:
            wd = str(r.wdate)
            rr = {"employee": r.employee, "employee_name": r.employee_name,
                  "farm": r.farm, "task": r.task, "actuals": r.actuals, "wdate": wd,
                  "qty": frappe.utils.flt(r.qty), "amount": frappe.utils.flt(r.amount),
                  "paid": frappe.utils.cint(r.paid), "run_ref": r.run_ref,
                  "entered_by": r.entered_by,
                  "scan_in": scan_ev.get((r.employee, wd)),
                  "att_status": att_ev.get((r.employee, wd))}
            astat = att_ev.get((r.employee, wd))
            if astat == "Absent":
                b_absent.append(rr)
            elif wd <= today_d and not rr["scan_in"] and not astat:
                b_ghost.append(rr)
            onlv = 0
            for lv in leave_ev.get(r.employee, []):
                if lv[0] <= wd <= lv[1]:
                    rr2 = dict(rr)
                    rr2["leave_type"] = lv[2]
                    b_leave.append(rr2)
                    onlv = 1
                    break
            if not onlv and hl_ev.get(r.employee) and off_ev.get((hl_ev[r.employee], wd)):
                b_off.append(rr)
            # amount should equal qty x doc rate for payroll rows
            if frappe.utils.cint(r.in_pay) and frappe.utils.flt(r.doc_rate) > 0:
                expect = frappe.utils.flt(r.qty) * frappe.utils.flt(r.doc_rate)
                if abs(expect - frappe.utils.flt(r.amount)) > 0.5:
                    rr3 = dict(rr)
                    rr3["expected"] = expect
                    rr3["rate"] = frappe.utils.flt(r.doc_rate)
                    b_rate.append(rr3)
            # standard_hours(), inlined -- no def in the sandbox. Saturday is short
            # and Sunday is not, which is the shape these farms work. Keep in step
            # with work_management/split_day.py, which is unit-tested.
            #
            # DELIBERATELY the SITE standard here, not the job's own day, which is
            # what man-days divide by. The two measure different things: a man-day
            # asks "how much of this job's day was given", so a twelve-hour patrol
            # shift is one day of patrolling. These checks ask "could a person's
            # calendar day physically hold this", and there the answer is eight
            # hours whatever the job. A twelve-hour shift plus a four-hour task is
            # sixteen hours of one person's Wednesday, and that is worth a look.
            hd_i = frappe.utils.getdate(wd).weekday()  # Mon=0 .. Sun=6
            if hd_i == 5:
                hd_std = frappe.utils.flt(STANDARD_DAY.get("saturday"))
            elif hd_i == 6:
                hd_std = frappe.utils.flt(STANDARD_DAY.get("sunday"))
            else:
                hd_std = frappe.utils.flt(STANDARD_DAY.get("weekday"))
            hd_hrs = frappe.utils.flt(r.hours) if frappe.utils.flt(r.hours) > 0 else hd_std
            # the day's total, for the long-day check after this loop
            name_of[r.employee] = r.employee_name
            day_h[(r.employee, wd)] = frappe.utils.flt(day_h.get((r.employee, wd))) + hd_hrs
            day_money[(r.employee, wd)] = frappe.utils.flt(day_money.get((r.employee, wd))) + frappe.utils.flt(r.amount)
            dw_list = day_where.get((r.employee, wd)) or []
            if r.task and r.task not in dw_list:
                dw_list.append(r.task)
            day_where[(r.employee, wd)] = dw_list
            # how many rows share this date, which is what makes the long-day check
            # answerable at all -- see the note where it runs
            day_rows[(r.employee, wd)] = frappe.utils.cint(day_rows.get((r.employee, wd))) + 1
            # HOURS AND OUTPUT DISAGREEING. Not "was this a short day" -- four hours
            # producing about half a target is an ordinary half day, and flagging it
            # would make the flag noise. What is worth a look is three hours
            # producing a full day's output: either the hours are wrong or the
            # quantity is, and only a person can say which.
            hd_tgt = frappe.utils.flt(r.dtarget)
            if hd_tgt > 0 and hd_std > 0:
                hd_out_share = frappe.utils.flt(r.qty) / hd_tgt
                hd_time_share = hd_hrs / hd_std
                # A FULL DAY IS NEVER THIS FLAG. Somebody doing 150% of target in a
                # whole day is productive, not contradictory -- and flagging them
                # made this 162 rows on kaitet.local, all of them good performers.
                # The contradiction is a full day's output in a FRACTION of the day,
                # so a day that was essentially whole is out of scope entirely.
                if hd_time_share < 0.95 and (hd_out_share - hd_time_share) > 0.25:
                    rr4 = dict(rr)
                    rr4["hours"] = hd_hrs
                    rr4["standard_hours"] = hd_std
                    rr4["daily_target"] = hd_tgt
                    rr4["output_pct"] = round(hd_out_share * 100, 1)
                    rr4["time_pct"] = round(hd_time_share * 100, 1)
                    b_short.append(rr4)
            # AN HOURLY TASK WHOSE TWO NUMBERS DISAGREE. Hours are typed on every
            # split row whatever the unit, including the 34 tasks already measured in
            # Hour -- 497 of the planners. There the same number is typed twice and
            # can be typed twice differently, and one of the two is then wrong.
            hd_uom = str(r.plan_uom or "").strip().lower()
            if hd_uom in ("hour", "hours", "hr", "hrs") and frappe.utils.flt(r.hours) > 0:
                if abs(frappe.utils.flt(r.qty) - frappe.utils.flt(r.hours)) > 0.005:
                    rr5 = dict(rr)
                    rr5["hours"] = frappe.utils.flt(r.hours)
                    rr5["uom"] = r.plan_uom
                    b_hqty.append(rr5)
        # ---- A DAY LONGER THAN THE DAY IS ----
        # Per date against that date's own standard, so two ordinary full days are
        # never read as one long one. This is where the warning the entry screen
        # shows becomes a pattern rather than a message somebody dismissed.
        for dk2 in day_h:
            # ONLY A SHARED DAY CAN BE TOO LONG.
            #
            # A single row's hours are whatever that task's day is, and some tasks
            # run longer than the site standard by design -- Security Patroll's daily
            # target is 12 hours, Coffee Picking's is 3. Comparing one such row
            # against an 8-hour standard flagged every one of them: on kaitet.local
            # that was 337 rows, and none of them was a contradiction.
            #
            # The contradiction is several rows for one worker on one date ADDING UP
            # to more than the day holds -- which is exactly the split day whose
            # halves were both left at the full standard, the thing this check was
            # asked for.
            if frappe.utils.cint(day_rows.get(dk2)) < 2:
                continue
            dk_emp = dk2[0]
            dk_day = dk2[1]
            dk_i = frappe.utils.getdate(dk_day).weekday()
            if dk_i == 5:
                dk_std = frappe.utils.flt(STANDARD_DAY.get("saturday"))
            elif dk_i == 6:
                dk_std = frappe.utils.flt(STANDARD_DAY.get("sunday"))
            else:
                dk_std = frappe.utils.flt(STANDARD_DAY.get("weekday"))
            dk_tot = frappe.utils.flt(day_h.get(dk2))
            if dk_std > 0 and dk_tot > dk_std + 0.005:
                b_long.append({"employee": dk_emp, "employee_name": name_of.get(dk_emp) or dk_emp,
                               "farm": None, "task": ", ".join(day_where.get(dk2) or []),
                               "actuals": None, "wdate": dk_day,
                               "hours": dk_tot, "standard_hours": dk_std,
                               "over_by": round(dk_tot - dk_std, 2),
                               "amount": frappe.utils.flt(day_money.get(dk2))})
        b_long = sorted(b_long, key=lambda x: -frappe.utils.flt(x.get("over_by")))

        # ---- same worker earning on 2+ farms the same day ----
        b_multi = []
        mf = frappe.db.sql("""
            SELECT we.employee, we.employee_name, we.work_date wdate,
                   COUNT(DISTINCT ac.farm) farms,
                   GROUP_CONCAT(DISTINCT ac.farm) farm_list,
                   GROUP_CONCAT(DISTINCT ac.name) docs,
                   COALESCE(SUM(we.amount),0) amount
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + dconds + """
            GROUP BY we.employee, we.employee_name, we.work_date
            HAVING COUNT(DISTINCT ac.farm) > 1
            ORDER BY we.work_date DESC LIMIT 300
        """, tuple(dparams), as_dict=True)
        for r in mf:
            b_multi.append({"employee": r.employee, "employee_name": r.employee_name,
                            "wdate": str(r.wdate), "farms": r.farm_list, "actuals": r.docs,
                            "amount": frappe.utils.flt(r.amount)})
        # ---- self-approval: the person who entered the actuals also approved them ----
        sconds2 = "ac.workflow_state='CONFIRMED' AND ac.entry_date BETWEEN %s AND %s"
        sparams2 = [dfrom, dto]
        if farm_list_d:
            sconds2 = sconds2 + " AND TRIM(ac.farm) IN %s"
            sparams2.append(tuple(farm_list_d))
        b_self = []
        for r in frappe.db.sql("""
            SELECT ac.name actuals, ac.farm, ac.task, ac.entered_by,
                   ac.hr_approved_by, ac.gm_approved_by, ac.entry_date,
                   ac.total_payment amount
            FROM `tabWork Management Actuals` ac
            WHERE """ + sconds2 + """
              AND (ac.entered_by = ac.hr_approved_by OR ac.entered_by = ac.gm_approved_by)
            ORDER BY ac.entry_date DESC LIMIT 300
        """, tuple(sparams2), as_dict=True):
            b_self.append({"actuals": r.actuals, "farm": r.farm, "task": r.task,
                           "entered_by": r.entered_by,
                           "hr_approved_by": r.hr_approved_by, "gm_approved_by": r.gm_approved_by,
                           "wdate": str(r.entry_date), "amount": frappe.utils.flt(r.amount)})
        # ---- worker marked Left but still earning after their left date ----
        b_left = []
        for r in frappe.db.sql("""
            SELECT we.employee, we.employee_name, ac.farm, ac.task, ac.name actuals,
                   we.work_date wdate, we.amount, wae.left_date
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            INNER JOIN `tabWork Management Assigner` a2 ON ac.assignment = a2.name
            INNER JOIN `tabWork Assignment Employee` wae ON wae.parent = a2.name
                  AND wae.employee = we.employee AND wae.status = 'Left'
                  AND wae.left_date IS NOT NULL AND we.work_date > wae.left_date
            WHERE """ + dconds + """
            ORDER BY we.work_date DESC LIMIT 300
        """, tuple(dparams), as_dict=True):
            b_left.append({"employee": r.employee, "employee_name": r.employee_name,
                           "farm": r.farm, "task": r.task, "actuals": r.actuals,
                           "wdate": str(r.wdate), "left_date": str(r.left_date),
                           "amount": frappe.utils.flt(r.amount)})
        # ---- recorded work valued at ZERO: qty entered but the row paid nothing,
        # although the doc has a rate and the worker is (now) a Task Worker. Happens
        # when the employment-type lookup failed at entry time. ----
        b_nopay = []
        npconds = "ac.workflow_state='CONFIRMED' AND we.actual_quantity > 0 AND IFNULL(we.amount,0) <= 0 AND IFNULL(ac.rate,0) > 0 AND IFNULL(we.paid,0) = 0 AND we.work_date BETWEEN %s AND %s"
        npparams = [dfrom, dto]
        if farm_list_d:
            npconds = npconds + " AND TRIM(ac.farm) IN %s"
            npparams.append(tuple(farm_list_d))
        for r in frappe.db.sql("""
            SELECT we.name rowname, we.employee, we.employee_name, ac.farm, ac.task,
                   ac.name actuals, we.work_date wdate, we.actual_quantity qty,
                   ac.rate doc_rate
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            INNER JOIN `tabEmployee` emp ON emp.name = we.employee
            WHERE """ + npconds + """
              AND emp.employment_type = 'Task Worker'
            ORDER BY we.work_date DESC LIMIT 300
        """, tuple(npparams), as_dict=True):
            wd = str(r.wdate)
            b_nopay.append({"employee": r.employee, "employee_name": r.employee_name,
                            "farm": r.farm, "task": r.task, "actuals": r.actuals,
                            "wdate": wd, "qty": frappe.utils.flt(r.qty), "amount": 0,
                            "rate": frappe.utils.flt(r.doc_rate),
                            "should_be": frappe.utils.flt(r.qty) * frappe.utils.flt(r.doc_rate),
                            "rowname": r.rowname,
                            "scan_in": scan_ev.get((r.employee, wd)),
                            "att_status": att_ev.get((r.employee, wd))})
        # ---- duplicate day entries: same worker + task + date recorded in more
        # than one document — double pay from overlapping assignments. ----
        b_dup = []
        for r in frappe.db.sql("""
            SELECT we.employee, we.employee_name, ac.farm, ac.task, we.work_date wdate,
                   COUNT(*) copies, COALESCE(SUM(we.amount),0) total_amt,
                   COALESCE(MAX(we.amount),0) keep_amt,
                   GROUP_CONCAT(DISTINCT ac.name) docs,
                   GROUP_CONCAT(DISTINCT ac.entered_by) enterers,
                   MIN(IFNULL(we.paid,0)) min_paid
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + dconds + """ AND we.actual_quantity > 0
            GROUP BY we.employee, we.employee_name, ac.farm, ac.task, we.work_date
            HAVING COUNT(*) > 1
            ORDER BY we.work_date DESC LIMIT 300
        """, tuple(dparams), as_dict=True):
            b_dup.append({"employee": r.employee, "employee_name": r.employee_name,
                          "farm": r.farm, "task": r.task, "wdate": str(r.wdate),
                          "copies": frappe.utils.cint(r.copies),
                          "amount": frappe.utils.flt(r.total_amt) - frappe.utils.flt(r.keep_amt),
                          "total_amt": frappe.utils.flt(r.total_amt),
                          "actuals": r.docs, "entered_by": r.enterers,
                          "paid": frappe.utils.cint(r.min_paid)})
        # ---- employees deactivated in HR but still Active on live assignments:
        # current-state check (ignores the date window) — these people can still
        # have quantities entered against them. ----
        b_inactive = []
        iconds = ""
        iparams = []
        if farm_list_d:
            iconds = " AND TRIM(a.farm) IN %s"
            iparams.append(tuple(farm_list_d))
        for r in frappe.db.sql("""
            SELECT we.name rowname, we.employee, we.employee_name, a.name assignment,
                   a.farm, a.task, a.from_date afrom, a.to_date ato, emp.status emp_status
            FROM `tabWork Assignment Employee` we
            INNER JOIN `tabWork Management Assigner` a ON we.parent = a.name
            INNER JOIN `tabEmployee` emp ON emp.name = we.employee
            WHERE a.workflow_state IN ('Pending Farm Manager','Pending HR Head','Pending GM','Assigned')
              AND IFNULL(we.status,'Active') = 'Active'
              AND emp.status != 'Active'
              """ + iconds + """
            ORDER BY a.farm, we.employee_name LIMIT 300
        """, tuple(iparams), as_dict=True):
            b_inactive.append({"employee": r.employee, "employee_name": r.employee_name,
                               "emp_status": r.emp_status, "farm": r.farm, "task": r.task,
                               "assignment": r.assignment, "wdate": str(r.afrom) + " → " + str(r.ato),
                               "amount": 0})
        checks = [
            {"key": "inactive_assigned", "title": "Left the company but still on live assignments",
             "about": "The employee is Inactive/Left in HR, yet still marked Active on a live assignment — quantities can still be recorded against them. Release them via a substitution/swap, or turn on 'Auto-release inactive employees from assignments' in Work Management Settings to handle this automatically.",
             "rows": b_inactive},
            {"key": "dup_day", "title": "Paid twice for the same day",
             "about": "The same worker, task and date recorded in more than one actuals document — usually two overlapping assignments for one task. The KES figure is the EXCESS beyond one copy. Zero the duplicate day with Edit in the worker's review sheet.",
             "rows": b_dup},
            {"key": "absent_paid", "title": "Paid on marked-Absent days",
             "about": "Money recorded on a day the worker's submitted attendance says Absent. A scan time means the attendance is probably wrong; no scan means the entry itself needs scrutiny.",
             "rows": b_absent},
            {"key": "ghost_days", "title": "No presence evidence at all",
             "about": "Work recorded on a day with no biometric scan and no attendance record of any kind — presence unknown. Could be a reader gap or a ghost entry.",
             "rows": b_ghost},
            {"key": "leave_paid", "title": "Earning while on approved leave",
             "about": "Task pay recorded on days covered by an approved Leave Application — possible double payment (leave pay + task pay).",
             "rows": b_leave},
            {"key": "off_paid", "title": "Work recorded on off days / holidays",
             "about": "Pay on the worker's weekly off or a public holiday. May be legitimate overtime — but should be deliberate, not accidental.",
             "rows": b_off},
            {"key": "rate_mismatch", "title": "Amount doesn't match qty × rate",
             "about": "Payroll rows where the stored amount differs from quantity × the document rate — edited or corrupted values.",
             "rows": b_rate},
            {"key": "multi_farm_day", "title": "Two farms, one day",
             "about": "The same worker earning on more than one farm on the same date — physically doubtful; usually a wrong worker picked.",
             "rows": b_multi},
            {"key": "self_approved", "title": "Entered and approved by the same person",
             "about": "Actuals documents where the person who entered the quantities also gave the HR or GM approval — no independent check.",
             "rows": b_self},
            {"key": "left_but_earning", "title": "Earning after leaving the job",
             "about": "Rows dated after the worker was marked Left on that assignment — a substituted/released worker still collecting days.",
             "rows": b_left},
            {"key": "no_pay", "title": "Recorded work with no pay",
             "about": "Quantities recorded but the row valued at ZERO although the document has a rate and the worker is a Task Worker — the worker-type lookup failed at entry, so these people will never be paid for the work. Revalue to qty × rate.",
             "rows": b_nopay},
            {"key": "long_day", "title": "More hours recorded than the day is long",
             "about": "One worker's recorded hours across every task on a single date add up to more than that date's standard day (8 weekdays, 6 Saturdays by default — set in Work Management Settings). Judged per date, so two ordinary full days are never read as one long one. Sometimes real overtime; often a split day where the halves were both left at the full standard. Pay is unaffected either way — hours are measurement, and pay is quantity × rate — so this costs a wrong man-day figure, not a wrong wage.",
             "rows": b_long},
            {"key": "short_day", "title": "Hours and output disagree",
             "about": "The output on this row runs well ahead of the time recorded against it — three hours producing a full day's target, say. NOT a short day: four hours producing about half a target is an ordinary half day and is never flagged. Either the hours are wrong or the quantity is, and only somebody who was there can say which.",
             "rows": b_short},
            {"key": "hours_vs_qty", "title": "Hourly task where the two numbers differ",
             "about": "The task is measured in Hours, so the quantity and the hours are the same fact typed twice — and here they disagree. 34 tasks in the catalogue are hourly, covering 497 plans, and hours are typed on every split row whatever the unit, which is what makes this possible. One of the two figures is wrong; the quantity is the one that pays.",
             "rows": b_hqty},
        ]
        toggle_map = {"inactive_assigned": "disc_inactive_assigned",
                      "dup_day": "disc_dup_day", "no_pay": "disc_no_pay",
                      "absent_paid": "disc_absent_paid", "ghost_days": "disc_ghost_days",
                      "leave_paid": "disc_leave_paid", "off_paid": "disc_off_paid",
                      "rate_mismatch": "disc_rate_mismatch", "multi_farm_day": "disc_multi_farm",
                      "self_approved": "disc_self_approved", "left_but_earning": "disc_left_earning",
                      "long_day": "disc_long_day", "short_day": "disc_short_day",
                      "hours_vs_qty": "disc_hours_vs_qty"}
        for c in checks:
            if not disc_on.get(toggle_map.get(c["key"]), 1):
                c["rows"] = []
                c["disabled"] = 1
            amts = 0
            wku = {}
            for x in c["rows"]:
                amts = amts + frappe.utils.flt(x.get("should_be") if c["key"] == "no_pay" else x.get("amount"))
                if x.get("employee"):
                    wku[x["employee"]] = 1
            c["count"] = len(c["rows"])
            c["workers"] = len(wku)
            c["amount"] = amts
            c["rows"] = c["rows"][:200]
        out["checks"] = checks
        out["window"] = {"from": dfrom, "to": dto}
        out["scanned_rows"] = len(base_rows)

    elif action == "pay_fix_unvalued":
        # Repair rows found by the "Recorded work with no pay" check: a Task
        # Worker's row that valued at zero because the type lookup failed at entry.
        # Revalues to qty x doc rate, restores payroll counting, re-sums the parent
        # and leaves an audit comment. Only unpaid rows on CONFIRMED docs.
        rn_raw = frappe.form_dict.get("rownames")
        rn_list = []
        if rn_raw:
            for rn in rn_raw.split(","):
                rv = rn.strip()
                if rv and rv not in rn_list:
                    rn_list.append(rv)
        if not rn_list:
            out["error"] = "rownames is required (CSV)"
        else:
            fixed = []
            errors = []
            parents = {}
            for rn in rn_list[:300]:
                row = frappe.db.get_value("Work Actuals Employee", rn,
                    ["name", "parent", "employee", "employee_name", "work_date",
                     "actual_quantity", "amount", "paid"], as_dict=True)
                if not row:
                    errors.append({"rowname": rn, "error": "not found"})
                    continue
                if frappe.utils.cint(row.paid):
                    errors.append({"rowname": rn, "error": "already paid"})
                    continue
                if frappe.utils.flt(row.amount) > 0.001:
                    errors.append({"rowname": rn, "error": "already valued"})
                    continue
                pinfo = frappe.db.get_value("Work Management Actuals", row.parent,
                    ["workflow_state", "rate"], as_dict=True)
                if not pinfo or pinfo.workflow_state != "CONFIRMED" or frappe.utils.flt(pinfo.rate) <= 0:
                    errors.append({"rowname": rn, "error": "doc not CONFIRMED or has no rate"})
                    continue
                etype = frappe.db.get_value("Employee", row.employee, "employment_type")
                if etype != "Task Worker":
                    errors.append({"rowname": rn, "error": "worker is not a Task Worker (" + str(etype) + ")"})
                    continue
                new_amt = round(frappe.utils.flt(row.actual_quantity) * frappe.utils.flt(pinfo.rate), 2)
                frappe.db.set_value("Work Actuals Employee", rn, "employment_type", "Task Worker", update_modified=False)
                frappe.db.set_value("Work Actuals Employee", rn, "count_in_payroll", 1, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", rn, "amount", new_amt, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", rn, "custom_reviewed", 0, update_modified=False)
                fixed.append({"rowname": rn, "employee": row.employee,
                              "employee_name": row.employee_name,
                              "wdate": str(row.work_date), "amount": new_amt})
                pl = parents.get(row.parent)
                if pl is None:
                    pl = []
                    parents[row.parent] = pl
                pl.append((row.employee_name or row.employee) + " " + str(row.work_date) + " → " + str(round(new_amt, 2)))
            # re-sum every touched parent
            for pname in parents:
                tots = frappe.db.sql("""
                    SELECT COALESCE(SUM(actual_quantity),0) q, COALESCE(SUM(amount),0) p,
                           COALESCE(SUM(CASE WHEN IFNULL(count_in_payroll,0)=1 THEN actual_quantity ELSE 0 END),0) twq,
                           COALESCE(SUM(CASE WHEN IFNULL(count_in_payroll,0)=0 THEN actual_quantity ELSE 0 END),0) slq,
                           COUNT(DISTINCT CASE WHEN IFNULL(count_in_payroll,0)=1 THEN employee END) pp
                    FROM `tabWork Actuals Employee` WHERE parent=%s
                """, (pname,), as_dict=True)
                if tots:
                    frappe.db.set_value("Work Management Actuals", pname, "total_actual_qty", frappe.utils.flt(tots[0].q), update_modified=False)
                    frappe.db.set_value("Work Management Actuals", pname, "total_payment", frappe.utils.flt(tots[0].p), update_modified=False)
                    frappe.db.set_value("Work Management Actuals", pname, "custom_tw_qty", frappe.utils.flt(tots[0].twq), update_modified=False)
                    frappe.db.set_value("Work Management Actuals", pname, "custom_salaried_qty", frappe.utils.flt(tots[0].slq), update_modified=False)
                    frappe.db.set_value("Work Management Actuals", pname, "payroll_people", frappe.utils.cint(tots[0].pp), update_modified=False)
            frappe.db.commit()
            for pname in parents:
                try:
                    frappe.get_doc("Work Management Actuals", pname).add_comment("Edited",
                        "Zero-pay repair by " + frappe.session.user + ": revalued at doc rate — " + "; ".join(parents[pname]))
                except Exception:
                    pass
            out["fixed"] = fixed
            out["fixed_count"] = len(fixed)
            out["fixed_total"] = sum(x["amount"] for x in fixed)
            out["errors"] = errors

    elif action == "pay_recalc_wages":
        # WAGE-DRIFT REPAIR: many plan rates were rounded to 2dp (e.g. 340/150 =
        # 2.2667 stored as 2.27), so a full day pays 340.50 / 339.96 / 342 instead
        # of the intended 340. For every plan whose implied daily wage
        # (rate x daily_target) is within 1% of 340 but not exactly 340, revalue
        # UNPAID confirmed payroll rows to qty x (340 / daily_target).
        # dry_run=1 reports what would change without touching anything.
        # Chunked (max 800 rows per call) — repeat until remaining = 0.
        recalc_dry = frappe.utils.cint(frappe.form_dict.get("dry_run"))
        WAGE = 340.0
        BAND = 3.4
        bad_plans = {}
        for r in frappe.db.sql("""
            SELECT name, rate, daily_target FROM `tabWork Management Planner`
            WHERE IFNULL(rate,0) > 0 AND IFNULL(daily_target,0) > 0
        """, as_dict=True):
            dw = frappe.utils.flt(r.rate) * frappe.utils.flt(r.daily_target)
            if abs(dw - WAGE) <= BAND and abs(dw - WAGE) > 0.001:
                bad_plans[r.name] = frappe.utils.flt(r.daily_target)
        rows_bad = []
        if bad_plans:
            rows_bad = frappe.db.sql("""
                SELECT we.name rowname, we.parent, we.employee, we.actual_quantity qty,
                       we.amount, a2.planner_request plan
                FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                INNER JOIN `tabWork Management Assigner` a2 ON ac.assignment = a2.name
                WHERE ac.workflow_state = 'CONFIRMED'
                  AND IFNULL(we.paid,0) = 0 AND IFNULL(we.payment_ref,'') = '' AND IFNULL(we.payroll_check,'') = '' AND IFNULL(we.count_in_payroll,0) = 1
                  AND we.actual_quantity > 0
                  AND a2.planner_request IN %s
            """, (tuple(bad_plans.keys()),), as_dict=True)
        todo = []
        old_total = 0
        new_total = 0
        for r in rows_bad:
            tgt = bad_plans.get(r.plan)
            if not tgt:
                continue
            new_amt = round(frappe.utils.flt(r.qty) * (WAGE / tgt), 2)
            if abs(new_amt - frappe.utils.flt(r.amount)) > 0.01:
                todo.append((r.rowname, r.parent, new_amt, frappe.utils.flt(r.amount)))
                old_total = old_total + frappe.utils.flt(r.amount)
                new_total = new_total + new_amt
        out["plans_affected"] = len(bad_plans)
        out["rows_to_fix"] = len(todo)
        out["old_total"] = old_total
        out["new_total"] = new_total
        out["delta"] = new_total - old_total
        if not recalc_dry and todo:
            batch = todo[:800]
            parents_r = {}
            for (rn, par, namt, oamt) in batch:
                frappe.db.set_value("Work Actuals Employee", rn, "amount", namt, update_modified=False)
                parents_r[par] = 1
            for pname in parents_r:
                tots = frappe.db.sql("""
                    SELECT COALESCE(SUM(actual_quantity),0) q, COALESCE(SUM(amount),0) p
                    FROM `tabWork Actuals Employee` WHERE parent=%s
                """, (pname,), as_dict=True)
                if tots:
                    frappe.db.set_value("Work Management Actuals", pname, "total_payment", frappe.utils.flt(tots[0].p), update_modified=False)
            frappe.db.commit()
            out["fixed_now"] = len(batch)
            out["parents_resummed"] = len(parents_r)
            out["remaining"] = len(todo) - len(batch)

    elif action == "pay_round_amounts":
        # HYGIENE: round unpaid confirmed row amounts to the cent (removes float
        # artifacts like 338.99999999999994) and re-sum the parents. Chunked.
        rr_rows = frappe.db.sql("""
            SELECT we.name rowname, we.parent, we.amount
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE ac.workflow_state = 'CONFIRMED' AND IFNULL(we.paid,0) = 0 AND IFNULL(we.payment_ref,'') = '' AND IFNULL(we.payroll_check,'') = ''
              AND we.amount != ROUND(we.amount, 2)
            LIMIT 900
        """, as_dict=True)
        parents_rr = {}
        for r in rr_rows:
            frappe.db.set_value("Work Actuals Employee", r.rowname, "amount", round(frappe.utils.flt(r.amount), 2), update_modified=False)
            parents_rr[r.parent] = 1
        for pname in parents_rr:
            tots = frappe.db.sql("""
                SELECT COALESCE(SUM(amount),0) p FROM `tabWork Actuals Employee` WHERE parent=%s
            """, (pname,), as_dict=True)
            if tots:
                frappe.db.set_value("Work Management Actuals", pname, "total_payment", round(frappe.utils.flt(tots[0].p), 2), update_modified=False)
        frappe.db.commit()
        remaining_rr = frappe.db.sql("""
            SELECT COUNT(*) n FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE ac.workflow_state = 'CONFIRMED' AND IFNULL(we.paid,0) = 0 AND IFNULL(we.payment_ref,'') = '' AND IFNULL(we.payroll_check,'') = ''
              AND we.amount != ROUND(we.amount, 2)
        """, as_dict=True)
        out["rounded"] = len(rr_rows)
        out["parents_resummed"] = len(parents_rr)
        out["remaining"] = frappe.utils.cint(remaining_rr[0].n) if remaining_rr else 0

    elif action == "pay_fix_duplicates" and not frappe.form_dict.get("force_legacy"):
        # Retired 2026-11-12: it kept the earliest-created copy and zeroed rows already
        # in a sent payment, so the worker was paid again. Duplicates are fixed in the
        # payroll check, which keeps the copy recorded first and never touches sent rows.
        out["error"] = "Duplicate days are now fixed in Payment > Payroll checks."

    elif action == "pay_fix_duplicates" and False:
        # DUPLICATE-DAY REPAIR: for every (worker, task, date) recorded in more
        # than one confirmed document, KEEP the copy in the earliest-created
        # document and zero the rest (qty and amount, review stamps reset).
        # Groups containing a paid row are skipped — those need manual handling.
        # Chunked (max 150 groups per call); dry_run=1 only reports.
        fd_dry = frappe.utils.cint(frappe.form_dict.get("dry_run"))
        fd_from = frappe.form_dict.get("from_date") or "2000-01-01"
        fd_to = frappe.form_dict.get("to_date") or str(frappe.utils.today())
        fd_farm = (frappe.form_dict.get("farms") or "").strip()
        fdconds = "ac.workflow_state='CONFIRMED' AND we.actual_quantity > 0 AND we.work_date BETWEEN %s AND %s"
        fdparams = [fd_from, fd_to]
        fd_flist = []
        if fd_farm:
            for f in fd_farm.split(","):
                fv = f.strip()
                if fv:
                    fd_flist.append(fv)
        if fd_flist:
            fdconds = fdconds + " AND TRIM(ac.farm) IN %s"
            fdparams.append(tuple(fd_flist))
        fd_rows = frappe.db.sql("""
            SELECT we.name rowname, we.parent, we.employee, we.employee_name,
                   ac.task, we.work_date wdate, we.actual_quantity qty, we.amount,
                   IFNULL(we.paid,0) paid, ac.creation doc_created
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + fdconds + """
            ORDER BY we.employee, ac.task, we.work_date, ac.creation
        """, tuple(fdparams), as_dict=True)
        groups = {}
        for r in fd_rows:
            k = (r.employee, r.task or "", str(r.wdate))
            g = groups.get(k)
            if g is None:
                g = []
                groups[k] = g
            g.append(r)
        dup_groups = []
        skipped_paid = 0
        for k in groups:
            g = groups[k]
            if len(g) < 2:
                continue
            if any(frappe.utils.cint(x.paid) for x in g):
                skipped_paid = skipped_paid + 1
                continue
            dup_groups.append(g)
        out["dup_groups"] = len(dup_groups)
        out["skipped_paid_groups"] = skipped_paid
        excess = 0
        zero_rows = 0
        for g in dup_groups:
            for x in g[1:]:
                excess = excess + frappe.utils.flt(x.amount)
                zero_rows = zero_rows + 1
        out["rows_to_zero"] = zero_rows
        out["excess_total"] = excess
        if not fd_dry and dup_groups:
            batch = dup_groups[:150]
            parents_fd = {}
            for g in batch:
                keep = g[0]
                for x in g[1:]:
                    frappe.db.set_value("Work Actuals Employee", x.rowname, "actual_quantity", 0, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", x.rowname, "amount", 0, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", x.rowname, "custom_reviewed", 0, update_modified=False)
                    pl = parents_fd.get(x.parent)
                    if pl is None:
                        pl = []
                        parents_fd[x.parent] = pl
                    pl.append((x.employee_name or x.employee) + " " + str(x.wdate) + " (" + str(x.task) + ", kept in " + keep.parent + ")")
            for pname in parents_fd:
                tots = frappe.db.sql("""
                    SELECT COALESCE(SUM(actual_quantity),0) q, COALESCE(SUM(amount),0) p,
                           COALESCE(SUM(CASE WHEN IFNULL(count_in_payroll,0)=1 THEN actual_quantity ELSE 0 END),0) twq,
                           COALESCE(SUM(CASE WHEN IFNULL(count_in_payroll,0)=0 THEN actual_quantity ELSE 0 END),0) slq,
                           COUNT(DISTINCT CASE WHEN IFNULL(count_in_payroll,0)=1 AND actual_quantity > 0 THEN employee END) pp
                    FROM `tabWork Actuals Employee` WHERE parent=%s
                """, (pname,), as_dict=True)
                if tots:
                    frappe.db.set_value("Work Management Actuals", pname, "total_actual_qty", frappe.utils.flt(tots[0].q), update_modified=False)
                    frappe.db.set_value("Work Management Actuals", pname, "total_payment", round(frappe.utils.flt(tots[0].p), 2), update_modified=False)
                    frappe.db.set_value("Work Management Actuals", pname, "custom_tw_qty", frappe.utils.flt(tots[0].twq), update_modified=False)
                    frappe.db.set_value("Work Management Actuals", pname, "custom_salaried_qty", frappe.utils.flt(tots[0].slq), update_modified=False)
                    frappe.db.set_value("Work Management Actuals", pname, "payroll_people", frappe.utils.cint(tots[0].pp), update_modified=False)
            frappe.db.commit()
            for pname in parents_fd:
                try:
                    frappe.get_doc("Work Management Actuals", pname).add_comment("Edited",
                        "Duplicate-day repair by " + frappe.session.user + ": zeroed re-entered day(s) — " + "; ".join(parents_fd[pname][:12]))
                except Exception:
                    pass
            out["fixed_groups"] = len(batch)
            out["remaining_groups"] = len(dup_groups) - len(batch)

    elif action == "pay_bulk_withdraw":
        # Return SEVERAL pending payments to Unpaid in one go — same as
        # pay_run_withdraw per entry: clear refs + review stamps, delete the doc.
        nm_raw = frappe.form_dict.get("names")
        nm_list = []
        if nm_raw:
            for nm in nm_raw.split(","):
                nv = nm.strip()
                if nv and nv not in nm_list:
                    nm_list.append(nv)
        if not nm_list:
            out["error"] = "names is required (CSV)"
        else:
            results = []
            done_n = 0
            rows_n = 0
            for nm in nm_list[:200]:
                cur = frappe.db.get_value("Work Management Payment", nm, "workflow_state")
                if not cur:
                    results.append({"name": nm, "error": "not found"})
                    continue
                if cur != "Unpaid":
                    results.append({"name": nm, "error": "state is " + str(cur)})
                    continue
                if frappe.db.sql("""
                    SELECT sd.parent FROM `tabSalary Detail` sd
                    INNER JOIN `tabAdditional Salary` a ON a.name = sd.additional_salary
                    WHERE a.ref_doctype = 'Work Management Payment' AND a.ref_docname = %(n)s LIMIT 1
                """, {"n": nm}, as_dict=True):
                    results.append({"name": nm, "error": "a Salary Slip has already paid this through payroll"})
                    continue
                for asr in frappe.db.sql("""
                    SELECT name FROM `tabAdditional Salary`
                    WHERE ref_doctype = 'Work Management Payment' AND ref_docname = %(n)s
                      AND docstatus = 1
                """, {"n": nm}, as_dict=True):
                    adoc = frappe.get_doc("Additional Salary", asr.name)
                    adoc.flags.ignore_permissions = True
                    adoc.cancel()
                rws = frappe.db.get_all("Work Actuals Employee",
                    filters={"payment_ref": nm, "paid": 0}, pluck="name")
                for rn in rws:
                    frappe.db.set_value("Work Actuals Employee", rn, "payment_ref", None, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", rn, "custom_reviewed", 0, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", rn, "custom_reviewed_by", None, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", rn, "custom_reviewed_at", None, update_modified=False)
                wt = frappe.db.get_value("Work Management Payment", nm, "run_title")
                try:
                    frappe.delete_doc("Work Management Payment", nm, ignore_permissions=True, force=True)
                    # commit per document: a lock clash on one entry must not roll
                    # back the entries already returned, which is what made the bulk
                    # action look like it had done nothing
                    frappe.db.commit()
                except Exception as e:
                    frappe.db.rollback()
                    results.append({"name": nm, "error": str(e)[:120]})
                    continue
                done_n = done_n + 1
                rows_n = rows_n + len(rws)
                results.append({"name": nm, "run_title": wt, "rows_reset": len(rws)})
            frappe.db.commit()
            out["results"] = results
            out["withdrawn"] = done_n
            out["rows_reset"] = rows_n
            out["errors"] = len([r for r in results if r.get("error")])

    elif action == "pay_purge_queue":
        # Empty the accounts queue wholesale. Same end state as returning every
        # entry to unpaid -- refs and review stamps cleared, documents deleted --
        # but in one server-side pass rather than a round trip per document.
        # Refuses anything payroll has already consumed. Chunked: repeat until
        # "remaining" comes back 0.
        pq_chunk = frappe.utils.cint(frappe.form_dict.get("chunk") or 400)
        if pq_chunk < 1 or pq_chunk > 1000:
            pq_chunk = 400
        pq_total = frappe.db.count("Work Management Payment", {"workflow_state": "Unpaid"})
        pq_rows = frappe.db.sql("""
            SELECT name FROM `tabWork Management Payment`
            WHERE workflow_state = 'Unpaid' ORDER BY creation LIMIT %(n)s
        """, {"n": pq_chunk}, as_dict=True)
        pq_names = [r.name for r in pq_rows]
        out["total"] = pq_total
        out["batch"] = len(pq_names)
        if not pq_names:
            out["remaining"] = 0
            out["deleted"] = 0
        else:
            pq_used = {}
            for u in frappe.db.sql("""
                SELECT a.ref_docname n FROM `tabSalary Detail` sd
                INNER JOIN `tabAdditional Salary` a ON a.name = sd.additional_salary
                WHERE a.ref_doctype = 'Work Management Payment' AND a.ref_docname IN %(p)s
            """, {"p": tuple(pq_names)}, as_dict=True):
                pq_used[u.n] = 1
            pq_go = [n for n in pq_names if not pq_used.get(n)]
            # ONE PAYMENT AT A TIME, MONEY FIRST (2026-11-12). The Additional Salary is
            # cancelled before the rows are freed, all inside one savepoint: if the cancel
            # fails, nothing about that payment has changed. Freeing first used to leave
            # rows sendable while the old Additional Salary still paid them.
            pq_freed = 0
            pq_gone = 0
            pq_failed = []
            for n in pq_go:
                pq_sp = "wmpq_" + str(pq_gone + len(pq_failed))
                frappe.db.savepoint(pq_sp)
                try:
                    for asr in frappe.db.sql("""
                        SELECT name FROM `tabAdditional Salary`
                        WHERE ref_doctype = 'Work Management Payment' AND ref_docname = %(n)s
                          AND docstatus = 1
                    """, {"n": n}, as_dict=True):
                        adoc = frappe.get_doc("Additional Salary", asr.name)
                        adoc.flags.ignore_permissions = True
                        adoc.cancel()
                    for rr in frappe.db.sql("""
                        SELECT name FROM `tabWork Actuals Employee`
                        WHERE payment_ref = %(p)s AND IFNULL(paid,0) = 0
                    """, {"p": n}, as_dict=True):
                        frappe.db.set_value("Work Actuals Employee", rr.name, {"payment_ref": None,
                            "custom_reviewed": 0, "custom_reviewed_by": None, "custom_reviewed_at": None},
                            update_modified=False)
                        pq_freed = pq_freed + 1
                    frappe.delete_doc("Work Management Payment", n, ignore_permissions=True, force=True)
                    pq_gone = pq_gone + 1
                except Exception as pq_exc:
                    frappe.db.rollback(save_point=pq_sp)
                    pq_failed.append({"payment": n, "error": str(pq_exc)[:200]})
            frappe.db.commit()
            out["failed"] = pq_failed
            out["deleted"] = pq_gone
            out["rows_freed"] = pq_freed
            out["skipped_paid_by_payroll"] = len(pq_used)
            out["remaining"] = frappe.db.count("Work Management Payment", {"workflow_state": "Unpaid"})

    elif action == "pay_issues":
        # Everyone in a date range who CANNOT be paid cleanly, and why. The same
        # preconditions the Additional Salary hook checks, run ahead of time so the
        # problems are visible before a run rather than discovered as a comment on a
        # document nobody opens. Nothing is stored: fix the data and the row goes.
        #   employee Inactive          -> ERPNext refuses a payroll record outright
        #   pay date past relieving    -> Additional Salary.validate_dates
        #   pay date before joining    -> Additional Salary.validate_dates
        #   no structure by that date  -> Additional Salary.validate_salary_structure
        #
        # The range is bucketed into PAY WEEKS and each week is judged against its
        # OWN pay day, because that is what sending does. Judging a multi-week range
        # against one pay day -- the last one -- silently clears anyone whose joining
        # date falls inside the range: 21 Jul..23 Aug reported 0 blocked while the
        # same span, week by week, found 3.
        is_from = frappe.form_dict.get("from_date")
        is_to = frappe.form_dict.get("to_date")
        is_farms = (frappe.form_dict.get("farms") or "").strip()
        is_one = frappe.form_dict.get("employee")
        if not is_from or not is_to:
            out["error"] = "from_date and to_date are required"
        else:
            is_names = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
            is_startday = frappe.db.get_single_value("Work Management Settings", "pay_week_starts_on") or "Sunday"
            is_endday = frappe.db.get_single_value("Work Management Settings", "pay_week_ends_on") or "Saturday"
            is_payday = frappe.db.get_single_value("Work Management Settings", "pay_day") or is_endday
            is_start_wd = is_names.index(is_startday) if is_startday in is_names else 6
            is_end_idx = is_names.index(is_endday) if is_endday in is_names else 5
            is_payidx = is_names.index(is_payday) if is_payday in is_names else is_end_idx
            is_len = ((is_end_idx - is_start_wd) % 7) + 1
            is_cond = ("ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0"
                       " AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0"
                       " AND IFNULL(we.payment_ref,'')=''"
                       " AND we.work_date >= %(f)s AND we.work_date <= %(t)s") + TW_ONLY
            is_args = {"f": is_from, "t": is_to}
            if is_farms:
                is_cond = is_cond + " AND ac.farm IN %(fl)s"
                is_args["fl"] = tuple([x.strip() for x in is_farms.split(",") if x.strip()])
            if is_one:
                is_cond = is_cond + " AND we.employee = %(e)s"
                is_args["e"] = is_one
            # one row per employee per DAY, so the day can be placed in its pay week
            is_days = frappe.db.sql("""
                SELECT we.employee emp, MAX(we.employee_name) nm, MAX(ac.farm) farm,
                       we.work_date d, COALESCE(SUM(we.amount),0) owed
                FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                WHERE """ + is_cond + """
                GROUP BY we.employee, we.work_date
            """, is_args, as_dict=True)

            is_groups = {}
            is_outside = []
            for dr in is_days:
                ddate = frappe.utils.getdate(dr.d)
                dback = (ddate.weekday() - is_start_wd) % 7
                if dback >= is_len:
                    # the pay week is shorter than seven days and this weekday sits in
                    # the gap, so no send will ever pick it up -- named, never dropped
                    is_outside.append({"employee": dr.emp, "employee_name": dr.nm,
                                       "farm": dr.farm, "date": str(dr.d),
                                       "amount": frappe.utils.flt(dr.owed)})
                    continue
                wstart = frappe.utils.add_days(ddate, -dback)
                wend = frappe.utils.add_days(wstart, is_len - 1)
                gkey = str(dr.emp) + "|" + str(wstart)
                if gkey not in is_groups:
                    wpay = wend
                    wguard = 0
                    while frappe.utils.getdate(wpay).weekday() != is_payidx and wguard < 7:
                        wpay = frappe.utils.add_days(wpay, 1)
                        wguard = wguard + 1
                    is_groups[gkey] = {"emp": dr.emp, "nm": dr.nm, "farm": dr.farm,
                                       "week_from": str(wstart), "week_to": str(wend),
                                       "pay_date": str(wpay), "owed": 0.0, "days": 0,
                                       "wfrom": str(dr.d), "wto": str(dr.d)}
                g = is_groups[gkey]
                g["owed"] = g["owed"] + frappe.utils.flt(dr.owed)
                g["days"] = g["days"] + 1
                if str(dr.d) < g["wfrom"]:
                    g["wfrom"] = str(dr.d)
                if str(dr.d) > g["wto"]:
                    g["wto"] = str(dr.d)

            is_emp_cache = {}
            is_out = []
            is_blocked_amt = 0
            is_keys = sorted(is_groups.keys())
            for gk in is_keys:
                g = is_groups[gk]
                ie = is_emp_cache.get(g["emp"])
                if ie is None:
                    ie = frappe.db.get_value("Employee", g["emp"],
                        ["employee_name", "status", "date_of_joining", "relieving_date"], as_dict=True) or {}
                    is_emp_cache[g["emp"]] = ie
                is_pd = g["pay_date"]
                why = []
                fix = []
                if ie and ie.get("status") == "Inactive":
                    why.append("Employee is Inactive")
                    fix.append("Set the employee back to Active, or decide they should not be paid")
                if ie and ie.get("relieving_date") and str(is_pd) > str(ie.get("relieving_date")):
                    why.append("Pay date " + str(is_pd) + " falls after the relieving date " + str(ie.get("relieving_date")))
                    fix.append("Correct the relieving date, or pay this work through payroll directly")
                if ie and ie.get("date_of_joining") and str(is_pd) < str(ie.get("date_of_joining")):
                    why.append("Pay date " + str(is_pd) + " falls before the joining date " + str(ie.get("date_of_joining")))
                    fix.append("Correct the date of joining")
                issa = frappe.db.sql("""
                    SELECT name FROM `tabSalary Structure Assignment`
                    WHERE employee = %(e)s AND docstatus = 1 AND from_date <= %(d)s LIMIT 1
                """, {"e": g["emp"], "d": is_pd}, as_dict=True)
                if not issa:
                    why.append("No submitted Salary Structure Assignment effective on or before " + str(is_pd))
                    fix.append("Assign and submit a Salary Structure for this employee")
                if why:
                    is_blocked_amt = is_blocked_amt + frappe.utils.flt(g["owed"])
                    is_out.append({
                        "employee": g["emp"],
                        "employee_name": (ie.get("employee_name") if ie else None) or g["nm"] or g["emp"],
                        "farm": g["farm"],
                        "amount": frappe.utils.flt(g["owed"]),
                        "days": g["days"],
                        "work_from": g["wfrom"],
                        "work_to": g["wto"],
                        "week_from": g["week_from"],
                        "week_to": g["week_to"],
                        "pay_date": is_pd,
                        "status": ie.get("status") if ie else None,
                        "date_of_joining": ie.get("date_of_joining") if ie else None,
                        "relieving_date": ie.get("relieving_date") if ie else None,
                        "reasons": why,
                        "fixes": fix,
                    })
            # the strictest pay date among the blocked weeks, so the row-level
            # "Mark solved" re-check cannot report cleared on a laxer date
            is_pd_top = None
            for r in is_out:
                if is_pd_top is None or str(r["pay_date"]) < str(is_pd_top):
                    is_pd_top = r["pay_date"]
            if is_pd_top is None:
                is_pd_top = is_to
            out["pay_date"] = str(is_pd_top)
            out["week_days"] = is_len
            out["weeks_checked"] = len(set([is_groups[k]["week_from"] for k in is_keys]))
            out["considered"] = len(is_groups)
            out["blocked"] = len(is_out)
            out["blocked_amount"] = is_blocked_amt
            out["clear"] = len(is_groups) - len(is_out)
            out["blocked_employees"] = len(set([r["employee"] for r in is_out]))
            out["considered_employees"] = len(set([is_groups[k]["emp"] for k in is_keys]))
            out["outside_pay_week"] = is_outside
            out["outside_pay_week_amount"] = sum(frappe.utils.flt(x["amount"]) for x in is_outside)
            out["issues"] = is_out
    elif action == "pay_recheck":
        # Re-run one worker's checks on the spot. "Mark solved" calls this, so a row
        # can only leave the list when the data behind it is genuinely fixed --
        # clicking a button can never hide an unpayable worker.
        rc_emp = frappe.form_dict.get("employee")
        rc_pd = frappe.form_dict.get("pay_date") or frappe.utils.today()
        if not rc_emp:
            out["error"] = "employee is required"
        else:
            rc_e = frappe.db.get_value("Employee", rc_emp,
                ["employee_name", "status", "date_of_joining", "relieving_date"], as_dict=True)
            rc_why = []
            if rc_e and rc_e.status == "Inactive":
                rc_why.append("Employee is still Inactive")
            if rc_e and rc_e.relieving_date and str(rc_pd) > str(rc_e.relieving_date):
                rc_why.append("Pay date " + str(rc_pd) + " still falls after the relieving date " + str(rc_e.relieving_date))
            if rc_e and rc_e.date_of_joining and str(rc_pd) < str(rc_e.date_of_joining):
                rc_why.append("Pay date " + str(rc_pd) + " still falls before the joining date " + str(rc_e.date_of_joining))
            rc_ssa = frappe.db.sql("""
                SELECT name FROM `tabSalary Structure Assignment`
                WHERE employee = %(e)s AND docstatus = 1 AND from_date <= %(d)s LIMIT 1
            """, {"e": rc_emp, "d": rc_pd}, as_dict=True)
            if not rc_ssa:
                rc_why.append("Still no Salary Structure Assignment effective on or before " + str(rc_pd))
            out["employee"] = rc_emp
            out["employee_name"] = rc_e.employee_name if rc_e else rc_emp
            out["clear"] = 0 if rc_why else 1
            out["reasons"] = rc_why

    elif action == "pay_fix_orphan_refs":
        # REPAIR: a work row keeps its payment_ref long after the payment it names
        # has gone. pay_purge_queue clears the refs of the documents it deletes,
        # but a payment removed any other way -- straight off the list view, say --
        # leaves its rows stamped. Those rows are then invisible to every send,
        # because pay_worker_submit only picks up rows whose payment_ref is empty,
        # so the worker looks payable on screen and refuses to send.
        # Only rows that are NOT paid and whose ref names a payment that no longer
        # exists are cleared. dry_run=1 reports without writing.
        fo_dry = frappe.utils.cint(frappe.form_dict.get("dry_run") or 0)
        fo_chunk = frappe.utils.cint(frappe.form_dict.get("chunk") or 500)
        if fo_chunk < 1 or fo_chunk > 2000:
            fo_chunk = 500
        fo_rows = frappe.db.sql("""
            SELECT we.name, we.employee, we.payment_ref, we.amount
            FROM `tabWork Actuals Employee` we
            LEFT JOIN `tabWork Management Payment` p ON p.name = we.payment_ref
            WHERE IFNULL(we.payment_ref,'') != ''
              AND IFNULL(we.paid,0) = 0
              AND p.name IS NULL
              AND NOT EXISTS (SELECT 1 FROM `tabAdditional Salary` asl
                              WHERE asl.ref_doctype = 'Work Management Payment'
                                AND asl.ref_docname = we.payment_ref AND asl.docstatus = 1)
            ORDER BY we.name
            LIMIT %(n)s
        """, {"n": fo_chunk}, as_dict=True)
        fo_total = frappe.db.sql("""
            SELECT COUNT(*) n, COALESCE(SUM(we.amount),0) a
            FROM `tabWork Actuals Employee` we
            LEFT JOIN `tabWork Management Payment` p ON p.name = we.payment_ref
            WHERE IFNULL(we.payment_ref,'') != ''
              AND IFNULL(we.paid,0) = 0
              AND p.name IS NULL
              AND NOT EXISTS (SELECT 1 FROM `tabAdditional Salary` asl
                              WHERE asl.ref_doctype = 'Work Management Payment'
                                AND asl.ref_docname = we.payment_ref AND asl.docstatus = 1)
        """, as_dict=True)[0]
        out["dry_run"] = fo_dry
        out["orphan_rows"] = frappe.utils.cint(fo_total.n)
        out["orphan_amount"] = frappe.utils.flt(fo_total.a)
        out["batch"] = len(fo_rows)
        out["sample"] = [{"row": r.name, "employee": r.employee, "ref": r.payment_ref} for r in fo_rows[:8]]
        fo_done = 0
        if not fo_dry:
            for r in fo_rows:
                frappe.db.set_value("Work Actuals Employee", r.name, "payment_ref", None, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", r.name, "custom_reviewed", 0, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", r.name, "custom_reviewed_by", None, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", r.name, "custom_reviewed_at", None, update_modified=False)
                fo_done = fo_done + 1
            frappe.db.commit()
        out["cleared"] = fo_done
        out["remaining"] = frappe.utils.cint(frappe.db.sql("""
            SELECT COUNT(*) n FROM `tabWork Actuals Employee` we
            LEFT JOIN `tabWork Management Payment` p ON p.name = we.payment_ref
            WHERE IFNULL(we.payment_ref,'') != ''
              AND IFNULL(we.paid,0) = 0
              AND p.name IS NULL
              AND NOT EXISTS (SELECT 1 FROM `tabAdditional Salary` asl
                              WHERE asl.ref_doctype = 'Work Management Payment'
                                AND asl.ref_docname = we.payment_ref AND asl.docstatus = 1)
        """, as_dict=True)[0].n)

    elif action == "pay_release_inactive":
        # CLEAN SLATE for the "left the company but still assigned" backlog:
        # mark every Active assignment row of a non-Active employee as Left
        # (dated today), recount the assignments and leave comments. The
        # auto-release checkbox only covers FUTURE deactivations — this handles
        # the existing rows. Chunked (150 rows/call); dry_run=1 reports only.
        ri_dry = frappe.utils.cint(frappe.form_dict.get("dry_run"))
        ri_farm = (frappe.form_dict.get("farms") or "").strip()
        riconds = ""
        riparams = []
        ri_flist = []
        if ri_farm:
            for f in ri_farm.split(","):
                fv = f.strip()
                if fv:
                    ri_flist.append(fv)
        if ri_flist:
            riconds = " AND TRIM(a.farm) IN %s"
            riparams.append(tuple(ri_flist))
        ri_rows = frappe.db.sql("""
            SELECT we.name rowname, we.employee, we.employee_name, a.name asg, a.farm
            FROM `tabWork Assignment Employee` we
            INNER JOIN `tabWork Management Assigner` a ON we.parent = a.name
            INNER JOIN `tabEmployee` emp ON emp.name = we.employee
            WHERE a.workflow_state IN ('Pending Farm Manager','Pending HR Head','Pending GM','Assigned')
              AND IFNULL(we.status,'Active') = 'Active'
              AND emp.status != 'Active'
              """ + riconds + """
            ORDER BY a.name LIMIT 2000
        """, tuple(riparams), as_dict=True)
        wset_ri = {}
        for r in ri_rows:
            wset_ri[r.employee] = 1
        out["rows_found"] = len(ri_rows)
        out["workers_found"] = len(wset_ri)
        if not ri_dry and ri_rows:
            batch = ri_rows[:150]
            touched = {}
            for r in batch:
                frappe.db.set_value("Work Assignment Employee", r.rowname, "status", "Left", update_modified=False)
                frappe.db.set_value("Work Assignment Employee", r.rowname, "left_date", frappe.utils.today(), update_modified=False)
                pl = touched.get(r.asg)
                if pl is None:
                    pl = []
                    touched[r.asg] = pl
                pl.append(r.employee_name or r.employee)
            for asg in touched:
                cnt = frappe.db.sql("""
                    SELECT COUNT(*) n FROM `tabWork Assignment Employee`
                    WHERE parent = %s AND IFNULL(status,'Active') = 'Active'
                """, (asg,), as_dict=True)
                if cnt:
                    frappe.db.set_value("Work Management Assigner", asg, "assigned_count", frappe.utils.cint(cnt[0].n), update_modified=False)
            frappe.db.commit()
            for asg in touched:
                try:
                    frappe.get_doc("Work Management Assigner", asg).add_comment("Comment",
                        "Released (clean slate) by " + frappe.session.user + " — deactivated in HR: " + ", ".join(touched[asg][:15]))
                except Exception:
                    pass
            out["released_now"] = len(batch)
            out["assignments_touched"] = len(touched)
            out["remaining"] = len(ri_rows) - len(batch)

    elif action == "pay_worker_edit_days":
        # BULK audit correction: change several worker-day quantities in one save.
        # Same rules per row as pay_worker_edit_day; parents re-sum once, one
        # audit comment per document lists every change.
        emp = frappe.form_dict.get("employee")
        rows_raw = frappe.form_dict.get("rows")
        if not emp or not rows_raw:
            out["error"] = "employee and rows are required"
        else:
            changes = []
            for c in rows_raw.split("|"):
                bits = c.split("~")
                if len(bits) >= 2 and bits[0]:
                    changes.append((bits[0], frappe.utils.flt(bits[1])))
            updated = []
            errors = []
            parents_e = {}
            for (rowname, new_qty) in changes[:300]:
                if new_qty < 0:
                    errors.append({"rowname": rowname, "error": "negative qty"})
                    continue
                row = frappe.db.get_value("Work Actuals Employee", rowname,
                    ["name", "parent", "employee", "employee_name", "work_date",
                     "actual_quantity", "amount", "paid", "count_in_payroll", "payment_ref"], as_dict=True)
                if not row or row.employee != emp:
                    errors.append({"rowname": rowname, "error": "not this worker's row"})
                    continue
                if frappe.utils.cint(row.paid):
                    errors.append({"rowname": rowname, "error": "already paid"})
                    continue
                if PC_DT and frappe.db.get_value("Work Actuals Employee", rowname, "payroll_check"):
                    errors.append({"rowname": rowname, "error": "in an approved payroll check — send it back first"})
                    continue
                if not frappe.utils.cint(row.count_in_payroll):
                    errors.append({"rowname": rowname, "error": "not payroll-counted"})
                    continue
                if row.payment_ref and frappe.db.get_value("Work Management Payment", row.payment_ref, "workflow_state") == "Unpaid":
                    errors.append({"rowname": rowname, "error": "inside " + row.payment_ref + " — return it to unpaid first"})
                    continue
                pstate = frappe.db.get_value("Work Management Actuals", row.parent, "workflow_state")
                if pstate != "CONFIRMED":
                    errors.append({"rowname": rowname, "error": "doc not CONFIRMED"})
                    continue
                old_qty = frappe.utils.flt(row.actual_quantity)
                old_amt = frappe.utils.flt(row.amount)
                if abs(old_qty - new_qty) < 0.0001:
                    continue
                rate = (old_amt / old_qty) if old_qty else frappe.utils.flt(
                    frappe.db.get_value("Work Management Actuals", row.parent, "rate"))
                new_amt = round(new_qty * rate, 2)
                frappe.db.set_value("Work Actuals Employee", rowname, "actual_quantity", new_qty, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", rowname, "amount", new_amt, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", rowname, "custom_reviewed", 0, update_modified=False)
                pl = parents_e.get(row.parent)
                if pl is None:
                    pl = []
                    parents_e[row.parent] = pl
                pl.append((row.employee_name or emp) + " " + str(row.work_date) + ": qty " + str(old_qty) + " → " + str(new_qty) + ", pay " + str(round(old_amt, 2)) + " → " + str(new_amt))
                updated.append({"rowname": rowname, "qty": new_qty, "amount": new_amt})
            for pname in parents_e:
                tots = frappe.db.sql("""
                    SELECT COALESCE(SUM(actual_quantity),0) q, COALESCE(SUM(amount),0) p
                    FROM `tabWork Actuals Employee` WHERE parent=%s
                """, (pname,), as_dict=True)
                if tots:
                    frappe.db.set_value("Work Management Actuals", pname, "total_actual_qty", frappe.utils.flt(tots[0].q), update_modified=False)
                    frappe.db.set_value("Work Management Actuals", pname, "total_payment", round(frappe.utils.flt(tots[0].p), 2), update_modified=False)
            frappe.db.commit()
            for pname in parents_e:
                try:
                    frappe.get_doc("Work Management Actuals", pname).add_comment("Edited",
                        "Bulk audit correction by " + frappe.session.user + ": " + "; ".join(parents_e[pname][:12]))
                except Exception:
                    pass
            out["updated"] = len(updated)
            out["errors"] = errors
            out["parents"] = len(parents_e)

    # ===== PAYROLL CHECK (chk_) =====
    # HR picks the dates to pay and creates a check. Each farm manager fixes and
    # approves their farm's part, HR clears what crosses farms, the GM approves,
    # and only then do those worker-days go to payroll. Any reviewer may send the
    # check back with a reason. One worker, one day, one task: duplicates found
    # here are zeroed with a logged fix; days already paid twice are recorded only.
    elif action.startswith("chk_") and not PC_DT:
        out["error"] = "Payroll checks are not available on this site yet (run migrate)."

    elif action.startswith("chk_"):
        pc_roles = send_role_list
        pc_fm = []
        for _farm_, _role_ in FARM_APPROVER_ROLE.items():
            if _role_ in pc_roles: pc_fm.append(_farm_)
        pc_gm = 1 if (("General Manager" in pc_roles) or ("System Manager" in pc_roles)
                      or wmg_si("check_gm", None)) else 0
        pc_hr = 1 if (any(_r_ in pc_roles for _r_ in HR_HEAD_ROLES) or pc_gm
                      or wmg_si("check_hr", None)) else 0
        pc_role_of = dict(FARM_APPROVER_ROLE)
        pc_me = frappe.db.get_value("User", frappe.session.user, "full_name") or frappe.session.user
        pc_sender = frappe.db.get_single_value("Work Management Settings", "payroll_pack_sender") \
            if frappe.db.sql("""SELECT 1 FROM `tabSingles` WHERE doctype = 'Work Management Settings'
                                AND field = 'payroll_pack_sender' LIMIT 1""") else None
        pc_url = frappe.utils.get_url("/work-payment")

        def wmpc_people(kind, farms):
            """Email addresses to tell: kind is fm (of `farms`), hr or gm."""
            got = []
            if kind == "fm":
                for f in farms or []:
                    rl = pc_role_of.get(f)
                    if rl:
                        for u in frappe.db.sql("""SELECT DISTINCT hr.parent FROM `tabHas Role` hr
                                INNER JOIN `tabUser` u ON u.name = hr.parent
                                WHERE hr.role = %s AND hr.parenttype = 'User' AND u.enabled = 1
                                  AND u.name NOT IN ('Administrator', 'Guest')""", (rl,)):
                            got.append(u[0])
            elif kind == "hr":
                raw = ""
                if frappe.db.sql("""SELECT 1 FROM `tabSingles` WHERE doctype = 'Work Management Settings'
                                    AND field = 'payroll_check_notify' LIMIT 1"""):
                    raw = frappe.db.get_single_value("Work Management Settings", "payroll_check_notify") or ""
                for e in str(raw).replace(";", ",").split(","):
                    if e.strip():
                        got.append(e.strip())
                if not got and frappe.db.exists("DocType", "Work Management Stage Approver"):
                    for u in frappe.db.sql("""SELECT DISTINCT user FROM `tabWork Management Stage Approver`
                            WHERE parent = 'Work Management Settings' AND stage_label = 'Actuals: HR Head'
                              AND IFNULL(user, '') != ''"""):
                        got.append(u[0])
            else:
                if frappe.db.exists("DocType", "Work Management Stage Approver"):
                    for u in frappe.db.sql("""SELECT DISTINCT user FROM `tabWork Management Stage Approver`
                            WHERE parent = 'Work Management Settings' AND stage_label = 'Actuals: GM'
                              AND IFNULL(user, '') != ''"""):
                        got.append(u[0])
                if not got:
                    for u in frappe.db.sql("""SELECT DISTINCT hr.parent FROM `tabHas Role` hr
                            INNER JOIN `tabUser` u ON u.name = hr.parent
                            WHERE hr.role = 'General Manager' AND hr.parenttype = 'User' AND u.enabled = 1
                              AND u.name NOT IN ('Administrator', 'Guest')"""):
                        got.append(u[0])
            clean = []
            for g in got:
                if g and g not in clean and g != frappe.session.user:
                    clean.append(g)
            return clean

        def wmpc_mail(to, subject, body):
            if not to:
                return
            try:
                frappe.sendmail(recipients=to, sender=pc_sender or None, subject=subject,
                    message=body + '<p><a href="' + pc_url + '">Open Payment &rarr; Payroll checks</a></p>')
            except Exception:
                pass

        def wmpc_label(c):
            return (str(c.name) + " (" + frappe.utils.formatdate(c.period_from, "d MMM") + " – " +
                    frappe.utils.formatdate(c.period_to, "d MMM yyyy") + (", top-up" if c.is_top_up else "") + ")")

        def wmpc_keeper(copies):
            """The copy a duplicate keeps: one already paid if there is one, else the
            copy on the assignment the worker was on first (earliest start, then the
            assignment created first, then the record created first)."""
            paid = [c for c in copies if frappe.utils.cint(c.get("paid"))]
            if paid:
                return paid[0]
            sent = [c for c in copies if c.get("payment_ref")]
            if sent:
                return sent[0]
            ranked = sorted(copies, key=lambda c: (str(c.get("asg_start") or "9999"),
                str(c.get("asg_created") or "9999"), str(c.get("ac_created") or "9999"), str(c.get("row"))))
            return ranked[0]

        def wmpc_duplicates(f, t, farm):
            """Every worker-day in f..t held by two or more payable rows, with its
            copies, the keeper, and who must fix it (the farm, or HR across farms)."""
            keys = frappe.db.sql("""
                SELECT we.employee emp, we.work_date d
                FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                WHERE we.parenttype = 'Work Management Actuals'
                  AND IFNULL(ac.workflow_state, '') != 'Rejected' AND ac.docstatus < 2
                  AND (IFNULL(we.actual_quantity, 0) > 0 OR IFNULL(we.amount, 0) > 0)
                  AND we.work_date BETWEEN %s AND %s
                GROUP BY we.employee, we.work_date HAVING COUNT(*) > 1
            """, (f, t), as_dict=True)
            if not keys:
                return []
            emps = {}
            for k in keys:
                emps[k.emp] = 1
            want = {}
            for k in keys:
                want[(k.emp, str(k.d))] = 1
            rows = frappe.db.sql("""
                SELECT we.name row, we.parent doc, we.employee emp, we.employee_name ename, we.work_date d,
                       we.actual_quantity qty, we.amount amount, IFNULL(we.paid, 0) paid,
                       IFNULL(we.payment_ref, '') payment_ref, IFNULL(we.payroll_check, '') payroll_check,
                       ac.farm farm, ac.task task, ac.assignment asg, ac.workflow_state state,
                       ac.creation ac_created, ac.entered_by entered_by,
                       a.creation asg_created,
                       (SELECT MIN(COALESCE(wae.start_date, a.from_date)) FROM `tabWork Assignment Employee` wae
                         WHERE wae.parent = a.name AND wae.employee = we.employee) asg_start
                FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                LEFT JOIN `tabWork Management Assigner` a ON a.name = ac.assignment
                WHERE we.parenttype = 'Work Management Actuals'
                  AND IFNULL(ac.workflow_state, '') != 'Rejected' AND ac.docstatus < 2
                  AND (IFNULL(we.actual_quantity, 0) > 0 OR IFNULL(we.amount, 0) > 0)
                  AND we.work_date BETWEEN %s AND %s AND we.employee IN %s
                ORDER BY we.employee, we.work_date, ac.creation
            """, (f, t, tuple(emps.keys())), as_dict=True)
            groups = {}
            for r in rows:
                k = (r.emp, str(r.d))
                if k in want:
                    r["d"] = str(r.d)
                    r["ac_created"] = str(r.ac_created)
                    r["asg_created"] = str(r.asg_created) if r.asg_created else None
                    r["asg_start"] = str(r.asg_start) if r.asg_start else None
                    groups.setdefault(k, []).append(r)
            dups = []
            for k in sorted(groups.keys()):
                g = groups[k]
                if len(g) < 2:
                    continue
                farms_in = {}
                for c in g:
                    farms_in[c.farm] = 1
                owner = g[0].farm if len(farms_in) == 1 else "HR"
                if farm and owner != farm:
                    continue
                keep = wmpc_keeper(g)
                # paid twice = settled by payroll on two or more copies. A copy only
                # sitting in a run awaiting accounts is still an open problem: HR
                # withdraws that run, then the copy can be zeroed.
                npaid = len([c for c in g if frappe.utils.cint(c.paid) or c.payment_ref])
                npaid_settled = len([c for c in g if frappe.utils.cint(c.paid)])
                excess = 0
                for c in g:
                    if c.row != keep.row:
                        excess = excess + frappe.utils.flt(c.amount)
                dups.append({"employee": k[0], "employee_name": g[0].ename, "work_date": k[1],
                    "owner": owner, "keep": keep.row, "copies": g, "paid_copies": npaid,
                    "paid_twice": 1 if npaid_settled > 1 else 0, "in_runs": npaid, "excess": excess})
            return dups

        def wmpc_unfinished(f, t, farm):
            """Records that still have to be finished, approved, or cleared away."""
            # only records holding work in these dates: an empty draft pays nobody,
            # and there is no way to clear one from the screens
            conds = """ac.docstatus < 2 AND ac.workflow_state IN
                       ('Draft', 'Rejected', 'Pending Farm Manager', 'Pending HR Head', 'Pending GM')
                    AND EXISTS (SELECT 1 FROM `tabWork Actuals Employee` w0 WHERE w0.parent = ac.name
                                  AND w0.parenttype = 'Work Management Actuals'
                                  AND w0.work_date BETWEEN %(f)s AND %(t)s
                                  AND (IFNULL(w0.actual_quantity, 0) > 0 OR IFNULL(w0.amount, 0) > 0))"""
            if farm:
                conds = conds + " AND ac.farm = %(farm)s"
            return frappe.db.sql("""
                SELECT ac.name, ac.farm, ac.task, t.subject task_name, ac.block_section, ac.workflow_state,
                       ac.entered_by, ac.from_date, ac.to_date, ac.total_payment amount
                FROM `tabWork Management Actuals` ac
                LEFT JOIN `tabTask` t ON t.name = ac.task
                WHERE """ + conds + """
                ORDER BY ac.farm, ac.workflow_state, ac.from_date
            """, {"f": f, "t": t, "farm": farm}, as_dict=True)

        def wmpc_payable_conds(c, farm):
            """The worker-days a farm's approval puts into check `c`."""
            conds = ("we.parenttype = 'Work Management Actuals' AND ac.workflow_state = 'CONFIRMED'"
                     " AND IFNULL(we.count_in_payroll, 0) = 1 AND we.amount > 0 AND IFNULL(we.paid, 0) = 0"
                     " AND IFNULL(we.payment_ref, '') = '' AND IFNULL(we.payroll_check, '') = ''"
                     " AND we.work_date BETWEEN %(f)s AND %(t)s" + TW_ONLY)
            if farm:
                conds = conds + " AND ac.farm = %(farm)s"
            return conds

        def wmpc_retotal(pname):
            tots = frappe.db.sql("""
                SELECT COALESCE(SUM(actual_quantity),0) q, COALESCE(SUM(amount),0) p,
                       COALESCE(SUM(CASE WHEN IFNULL(count_in_payroll,0)=1 THEN actual_quantity ELSE 0 END),0) twq,
                       COALESCE(SUM(CASE WHEN IFNULL(count_in_payroll,0)=0 THEN actual_quantity ELSE 0 END),0) slq,
                       COUNT(DISTINCT CASE WHEN IFNULL(count_in_payroll,0)=1 AND actual_quantity > 0 THEN employee END) pp
                FROM `tabWork Actuals Employee` WHERE parent=%s
            """, (pname,), as_dict=True)
            if tots:
                frappe.db.set_value("Work Management Actuals", pname, {
                    "total_actual_qty": frappe.utils.flt(tots[0].q),
                    "total_payment": round(frappe.utils.flt(tots[0].p), 2),
                    "custom_tw_qty": frappe.utils.flt(tots[0].twq),
                    "custom_salaried_qty": frappe.utils.flt(tots[0].slq),
                    "payroll_people": frappe.utils.cint(tots[0].pp)}, update_modified=False)

        def wmpc_zero(c, dup, copy, reason):
            """Zero one duplicate copy and log it against check `c`."""
            frappe.db.set_value("Work Actuals Employee", copy.row, {"actual_quantity": 0, "amount": 0,
                "custom_reviewed": 0, "payroll_check": ""}, update_modified=False)
            wmpc_retotal(copy.doc)
            kept = None
            for x in dup["copies"]:
                if x.row == dup["keep"]:
                    kept = x
            fx = frappe.new_doc("Work Management Payroll Check Fix")
            fx.payroll_check = c.name
            fx.kind = "duplicate"
            fx.employee = dup["employee"]
            fx.employee_name = dup["employee_name"]
            fx.work_date = dup["work_date"]
            fx.farm = copy.farm
            fx.kept_row = kept.row if kept else None
            fx.kept_actuals = kept.doc if kept else None
            fx.zeroed_row = copy.row
            fx.zeroed_actuals = copy.doc
            fx.qty_before = frappe.utils.flt(copy.qty)
            fx.amount_before = frappe.utils.flt(copy.amount)
            fx.fixed_by = frappe.session.user
            fx.fixed_at = frappe.utils.now()
            fx.reason = reason
            fx.insert(ignore_permissions=True)
            try:
                frappe.get_doc("Work Management Actuals", copy.doc).add_comment("Edited",
                    "Payroll check " + c.name + ": " + str(dup["employee_name"] or dup["employee"]) + " on " +
                    dup["work_date"] + " zeroed by " + frappe.session.user + " (kept in " +
                    str(kept.doc if kept else "?") + "). " + reason)
            except Exception:
                pass
            frappe.db.set_value("Work Management Payroll Check", c.name, {
                "dups_fixed": frappe.utils.cint(c.dups_fixed) + 1,
                "amount_zeroed": frappe.utils.flt(c.amount_zeroed) + frappe.utils.flt(copy.amount)},
                update_modified=False)
            c.dups_fixed = frappe.utils.cint(c.dups_fixed) + 1
            c.amount_zeroed = frappe.utils.flt(c.amount_zeroed) + frappe.utils.flt(copy.amount)

        def wmpc_log_paid_twice(c, dups):
            """Record days already paid twice. Nothing is changed or recovered."""
            n = 0
            for dp in dups:
                if not dp["paid_twice"]:
                    continue
                if frappe.db.exists("Work Management Payroll Check Fix", {"kind": "paid twice",
                        "employee": dp["employee"], "work_date": dp["work_date"]}):
                    continue
                paid = [x for x in dp["copies"] if frappe.utils.cint(x.paid)]
                fx = frappe.new_doc("Work Management Payroll Check Fix")
                fx.payroll_check = c.name if c else None
                fx.kind = "paid twice"
                fx.employee = dp["employee"]
                fx.employee_name = dp["employee_name"]
                fx.work_date = dp["work_date"]
                fx.farm = paid[0].farm
                fx.kept_row = paid[0].row
                fx.kept_actuals = paid[0].doc
                fx.zeroed_row = paid[1].row
                fx.zeroed_actuals = paid[1].doc
                fx.qty_before = frappe.utils.flt(paid[1].qty)
                fx.amount_before = sum(frappe.utils.flt(x.amount) for x in paid[1:])
                fx.payments = ", ".join([str(x.payment_ref or "paid") for x in paid])
                fx.fixed_by = frappe.session.user
                fx.fixed_at = frappe.utils.now()
                fx.reason = "Found paid on " + str(len(paid)) + " records. Recorded only; management decides."
                fx.insert(ignore_permissions=True)
                n = n + 1
            return n

        def wmpc_unstamp(c):
            frappe.db.sql("""UPDATE `tabWork Actuals Employee` SET payroll_check = ''
                             WHERE payroll_check = %s AND IFNULL(payment_ref, '') = ''""", (c.name,))

        def wmpc_get(name):
            c = frappe.db.get_value("Work Management Payroll Check", name,
                ["name", "period_from", "period_to", "is_top_up", "status", "created_by", "hr_approved_by",
                 "hr_approved_at", "gm_approved_by", "gm_approved_at", "sent_at", "sent_back_reason",
                 "sent_back_by", "sent_back_at", "worker_days", "amount", "dups_fixed", "amount_zeroed"],
                as_dict=True) if name else None
            if c:
                c["period_from"] = str(c.period_from)
                c["period_to"] = str(c.period_to)
                c["farms"] = frappe.db.get_all("Work Management Payroll Check Farm",
                    filters={"parent": c.name, "parenttype": "Work Management Payroll Check"},
                    fields=["name", "farm", "status", "approved_by", "approved_at"], order_by="idx")
            return c

        def wmpc_totals(c):
            tt = frappe.db.sql("""SELECT COUNT(*) n, COALESCE(SUM(amount), 0) a FROM `tabWork Actuals Employee`
                                  WHERE payroll_check = %s""", (c.name,), as_dict=True)
            frappe.db.set_value("Work Management Payroll Check", c.name, {
                "worker_days": frappe.utils.cint(tt[0].n), "amount": frappe.utils.flt(tt[0].a)}, update_modified=False)

        pc_name = frappe.form_dict.get("check")
        pc = wmpc_get(pc_name) if pc_name else None
        pc_reason = (frappe.form_dict.get("reason") or "").strip()

        if action == "chk_list":
            out["checks"] = frappe.db.get_all("Work Management Payroll Check",
                fields=["name", "period_from", "period_to", "is_top_up", "status", "created_by", "worker_days",
                        "amount", "dups_fixed", "amount_zeroed", "creation", "sent_back_reason"],
                order_by="period_from desc, creation desc", limit=60)
            for c in out["checks"]:
                c["farms"] = frappe.db.get_all("Work Management Payroll Check Farm",
                    filters={"parent": c.name, "parenttype": "Work Management Payroll Check"},
                    fields=["farm", "status"], order_by="idx")
            # late work: confirmed after its dates went to payroll, waiting for a top-up check
            out["late"] = frappe.db.sql("""
                SELECT ac.farm, COUNT(*) worker_days, COALESCE(SUM(we.amount), 0) amount,
                       MIN(we.work_date) date_from, MAX(we.work_date) date_to
                FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                WHERE we.parenttype = 'Work Management Actuals' AND ac.workflow_state = 'CONFIRMED'
                  AND IFNULL(we.count_in_payroll, 0) = 1 AND we.amount > 0 AND IFNULL(we.paid, 0) = 0
                  AND IFNULL(we.payment_ref, '') = '' AND IFNULL(we.payroll_check, '') = ''
                  AND EXISTS (SELECT 1 FROM `tabWork Management Payroll Check` s WHERE s.status = 'Sent'
                              AND s.is_top_up = 0 AND we.work_date BETWEEN s.period_from AND s.period_to)
                  AND NOT EXISTS (SELECT 1 FROM `tabWork Management Payroll Check` o
                                  WHERE o.status NOT IN ('Sent', 'Cancelled') AND o.is_top_up = 1
                                    AND we.work_date BETWEEN o.period_from AND o.period_to)
                GROUP BY ac.farm ORDER BY ac.farm
            """, as_dict=True)
            out["me"] = {"fm_farms": pc_fm, "hr": pc_hr, "gm": pc_gm, "can_send": CAN_SEND,
                         "gate": PC_GATE, "user": frappe.session.user}

        elif action == "chk_create":
            cf = frappe.form_dict.get("from_date")
            ct = frappe.form_dict.get("to_date")
            ctop = frappe.utils.cint(frappe.form_dict.get("top_up"))
            cerr = None
            if not pc_hr:
                cerr = "Only HR or the GM can start a payroll check."
            elif not (cf and ct) or str(cf) > str(ct):
                cerr = "Pick the dates to pay: a start and an end, in order."
            elif str(ct) >= str(frappe.utils.today()):
                cerr = "A check covers days already worked: end it yesterday or earlier."
            elif frappe.utils.date_diff(ct, cf) > 62:
                cerr = "A payroll check covers at most two months."
            if not cerr and not ctop:
                ov = frappe.db.sql("""SELECT name, status FROM `tabWork Management Payroll Check`
                    WHERE status != 'Cancelled' AND is_top_up = 0 AND period_from <= %s AND period_to >= %s LIMIT 1""",
                    (ct, cf), as_dict=True)
                if ov:
                    cerr = ("Those dates overlap payroll check " + ov[0].name + " (" + ov[0].status + "). A day can "
                            "only be in one check; for work confirmed after a check was sent, start a top-up check.")
            if not cerr and ctop:
                # inside dates already sent, with late work to pay, and no other open top-up there
                sent = frappe.db.sql("""SELECT period_from, period_to FROM `tabWork Management Payroll Check`
                    WHERE status = 'Sent' AND is_top_up = 0 AND period_from <= %s AND period_to >= %s""",
                    (ct, cf), as_dict=True)
                inside = 0
                for sx in sent:
                    if str(sx.period_from) <= str(cf) and str(ct) <= str(sx.period_to):
                        inside = 1
                if not inside:
                    cerr = "A top-up check must sit inside the dates of one check already sent to payroll."
                elif frappe.db.sql("""SELECT 1 FROM `tabWork Management Payroll Check` WHERE is_top_up = 1
                        AND status NOT IN ('Sent', 'Cancelled') AND period_from <= %s AND period_to >= %s LIMIT 1""",
                        (ct, cf)):
                    cerr = "There is already an open top-up check over those dates."
            cfarms = []
            if not cerr:
                for fr in frappe.db.sql("""
                    SELECT DISTINCT ac.farm FROM `tabWork Management Actuals` ac
                    WHERE ac.docstatus < 2 AND IFNULL(ac.farm, '') != '' AND (
                      EXISTS (SELECT 1 FROM `tabWork Actuals Employee` w1 WHERE w1.parent = ac.name
                              AND w1.parenttype = 'Work Management Actuals' AND w1.work_date BETWEEN %(f)s AND %(t)s
                              """ + (" AND IFNULL(w1.payroll_check, '') = '' AND IFNULL(w1.paid, 0) = 0 AND w1.amount > 0"
                                     if ctop else "") + """)
                      """ + ("" if ctop else """OR (ac.workflow_state != 'CONFIRMED' AND ac.from_date <= %(t)s AND ac.to_date >= %(f)s)""") + """)
                    ORDER BY ac.farm""", {"f": cf, "t": ct}):
                    if fr[0] in FARMS:
                        cfarms.append(fr[0])
                if not cfarms:
                    cerr = "Nothing was recorded on any farm over those dates." if not ctop else \
                           "There is no late work to pay inside those dates."
            if cerr:
                out["error"] = cerr
            else:
                cd = frappe.new_doc("Work Management Payroll Check")
                cd.period_from = cf
                cd.period_to = ct
                cd.is_top_up = ctop
                cd.status = "Farm Review"
                cd.created_by = frappe.session.user
                for fv in cfarms:
                    cd.append("farms", {"farm": fv, "status": "Pending"})
                cd.insert(ignore_permissions=True)
                dl = wmpc_duplicates(cf, ct, None)
                out["paid_twice_logged"] = wmpc_log_paid_twice(cd, dl)
                frappe.db.commit()
                wmpc_mail(wmpc_people("fm", cfarms), "Payroll check " + wmpc_label(cd) + ": please review your farm",
                    "<p>" + frappe.utils.escape_html(pc_me) + " has started payroll check <b>" +
                    frappe.utils.escape_html(wmpc_label(cd)) + "</b>.</p><p>Fix any duplicate days and unfinished "
                    "records on your farm, then approve it. Workers are not paid for these dates until every "
                    "farm, HR and the GM have approved.</p>")
                out["name"] = cd.name

        elif not pc:
            out["error"] = "No such payroll check: " + str(pc_name)

        elif action == "chk_detail":
            fscope = (frappe.form_dict.get("farm") or "").strip() or None
            if not pc_hr:
                # a farm manager sees their own farm's part of the check, nobody else's
                if fscope not in pc_fm:
                    fscope = pc_fm[0] if pc_fm else "__none__"
            dl = wmpc_duplicates(pc.period_from, pc.period_to, fscope)
            uf = wmpc_unfinished(pc.period_from, pc.period_to, fscope) if not pc.is_top_up else []
            open_dups = [x for x in dl if not x["paid_twice"]]
            by = {}
            for x in pc.farms:
                by[x.farm] = {"farm": x.farm, "status": x.status, "approved_by": x.approved_by,
                              "approved_at": str(x.approved_at) if x.approved_at else None,
                              "dups": 0, "unfinished": 0, "worker_days": 0, "amount": 0, "absent_paid": 0}
            hr_dups = 0
            for x in open_dups:
                if x["owner"] in by:
                    by[x["owner"]]["dups"] = by[x["owner"]]["dups"] + 1
                else:
                    hr_dups = hr_dups + 1
            for x in uf:
                if x.farm in by:
                    by[x.farm]["unfinished"] = by[x.farm]["unfinished"] + 1
            for x in frappe.db.sql("""
                SELECT ac.farm, COUNT(*) n, COALESCE(SUM(we.amount), 0) a,
                       SUM(CASE WHEN EXISTS (SELECT 1 FROM `tabAttendance` att WHERE att.employee = we.employee
                             AND att.attendance_date = we.work_date AND att.docstatus = 1 AND att.status = 'Absent')
                           THEN 1 ELSE 0 END) absent_paid
                FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                WHERE we.parenttype = 'Work Management Actuals' AND ac.workflow_state = 'CONFIRMED'
                  AND IFNULL(we.count_in_payroll, 0) = 1 AND we.amount > 0
                  AND we.work_date BETWEEN %s AND %s
                  AND (IFNULL(we.payroll_check, '') = %s OR (IFNULL(we.payroll_check, '') = ''
                       AND IFNULL(we.paid, 0) = 0 AND IFNULL(we.payment_ref, '') = ''))
                GROUP BY ac.farm
            """, (pc.period_from, pc.period_to, pc.name), as_dict=True):
                if x.farm in by:
                    by[x.farm]["worker_days"] = frappe.utils.cint(x.n)
                    by[x.farm]["amount"] = frappe.utils.flt(x.a)
                    by[x.farm]["absent_paid"] = frappe.utils.cint(x.absent_paid)
            out["check"] = pc
            out["farms"] = [by[k] for k in sorted(by.keys())]
            out["hr_dups"] = hr_dups
            out["duplicates"] = dl[:400]
            out["duplicates_total"] = len(dl)
            out["unfinished"] = uf
            out["fixes"] = frappe.db.get_all("Work Management Payroll Check Fix", filters={"payroll_check": pc.name},
                fields=["name", "kind", "employee", "employee_name", "work_date", "farm", "kept_actuals",
                        "zeroed_actuals", "amount_before", "payments", "fixed_by", "fixed_at", "reason"],
                order_by="fixed_at desc", limit=500)
            out["me"] = {"fm_farms": pc_fm, "hr": pc_hr, "gm": pc_gm, "can_send": CAN_SEND, "gate": PC_GATE}
            if not pc_hr:
                out["farms"] = [x for x in out["farms"] if x["farm"] in pc_fm]
                out["fixes"] = [x for x in out["fixes"] if x.farm in pc_fm]
                out["hr_dups"] = 0

        elif action == "chk_fix_dup":
            zrow = frappe.form_dict.get("zero_row")
            fx_farm = (frappe.form_dict.get("farm") or "").strip() or None
            fx_all = frappe.utils.cint(frappe.form_dict.get("all"))
            ferr = None
            if pc.status in ("Sent", "Cancelled"):
                ferr = "This check is " + pc.status + "."
            elif not pc_reason:
                ferr = "Say why (it is logged with the fix)."
            dl = [] if ferr else [x for x in wmpc_duplicates(pc.period_from, pc.period_to, None) if not x["paid_twice"]]
            todo = []
            if not ferr:
                for dp in dl:
                    if fx_all:
                        if (fx_farm and dp["owner"] != fx_farm) or (not fx_farm and not pc_hr):
                            continue
                        for cx in dp["copies"]:
                            if cx.row != dp["keep"] and not cx.payment_ref and not frappe.utils.cint(cx.paid):
                                todo.append((dp, cx))
                    else:
                        for cx in dp["copies"]:
                            if cx.row == zrow:
                                todo.append((dp, cx))
                if not todo:
                    ferr = "Nothing to fix: that duplicate is gone or was already fixed."
            if not ferr:
                for dp, cx in todo:
                    if dp["owner"] == "HR" and not pc_hr:
                        ferr = "A duplicate across two farms is for HR to fix."
                    elif dp["owner"] != "HR" and not (pc_hr or dp["owner"] in pc_fm):
                        ferr = "Only " + dp["owner"] + "'s farm manager, HR or the GM can fix that."
                    elif frappe.utils.cint(cx.paid):
                        ferr = "That copy is already paid; zero the other one."
                    elif cx.payment_ref:
                        ferr = ("That copy is in payment run " + str(cx.payment_ref) + ", not yet paid: "
                                "withdraw that run on Awaiting accounts first, then zero it here.")
                    elif dp["owner"] != "HR" and [f for f in pc.farms if f.farm == dp["owner"] and f.status == "Approved"]:
                        ferr = dp["owner"] + " is already approved in this check; send it back first."
                    if ferr:
                        break
            if ferr:
                out["error"] = ferr
            else:
                for dp, cx in todo:
                    wmpc_zero(pc, dp, cx, pc_reason)
                frappe.db.commit()
                out["zeroed"] = len(todo)

        elif action == "chk_farm_approve":
            af = (frappe.form_dict.get("farm") or "").strip()
            arow = [f for f in pc.farms if f.farm == af]
            aerr = None
            if pc.status != "Farm Review":
                aerr = "This check is at " + pc.status + ", not with the farm managers."
            elif not arow:
                aerr = af + " is not in this check."
            elif arow[0].status == "Approved":
                aerr = af + " is already approved."
            elif not (pc_gm or af in pc_fm):
                aerr = "Only " + af + "'s farm manager or the GM can approve it."
            if not aerr:
                dl = [x for x in wmpc_duplicates(pc.period_from, pc.period_to, af) if not x["paid_twice"]]
                uf = wmpc_unfinished(pc.period_from, pc.period_to, af) if not pc.is_top_up else []
                if dl or uf:
                    aerr = (af + " still has " + str(len(dl)) + " duplicate day(s) and " + str(len(uf)) +
                            " unfinished record(s) in these dates. Fix them first.")
            if aerr:
                out["error"] = aerr
            else:
                frappe.db.sql("""UPDATE `tabWork Actuals Employee` we
                    INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                    SET we.payroll_check = %(c)s
                    WHERE """ + wmpc_payable_conds(pc, af),
                    {"c": pc.name, "f": pc.period_from, "t": pc.period_to, "farm": af})
                frappe.db.set_value("Work Management Payroll Check Farm", arow[0].name, {"status": "Approved",
                    "approved_by": frappe.session.user, "approved_at": frappe.utils.now()}, update_modified=False)
                wmpc_totals(pc)
                left = [f for f in pc.farms if f.farm != af and f.status != "Approved"]
                if not left:
                    frappe.db.set_value("Work Management Payroll Check", pc.name, "status", "HR Review")
                    out["status"] = "HR Review"
                frappe.get_doc("Work Management Payroll Check", pc.name).add_comment("Comment",
                    af + " approved by " + pc_me)
                frappe.db.commit()
                if not left:
                    wmpc_mail(wmpc_people("hr", []), "Payroll check " + wmpc_label(pc) + " is ready for HR",
                        "<p>Every farm has approved payroll check <b>" + frappe.utils.escape_html(wmpc_label(pc)) +
                        "</b>. Clear anything across farms and approve it for the GM.</p>")
                out["approved"] = af

        elif action == "chk_hr_approve" or action == "chk_gm_approve":
            is_hr_step = action == "chk_hr_approve"
            herr = None
            if is_hr_step and not pc_hr:
                herr = "Only HR (or the GM) can take this step."
            elif (not is_hr_step) and not pc_gm:
                herr = "Only the GM can approve a payroll check."
            elif pc.status != ("HR Review" if is_hr_step else "GM Review"):
                herr = "This check is at " + pc.status + "."
            elif (not is_hr_step) and pc.hr_approved_by == frappe.session.user:
                herr = ("You approved this check for HR, so somebody else must give the GM approval: "
                        "two people see every payroll.")
            if not herr:
                dl = [x for x in wmpc_duplicates(pc.period_from, pc.period_to, None) if not x["paid_twice"]]
                uf = wmpc_unfinished(pc.period_from, pc.period_to, None) if not pc.is_top_up else []
                if dl or uf:
                    herr = (str(len(dl)) + " duplicate day(s) and " + str(len(uf)) + " unfinished record(s) are "
                            "still in these dates. Fix them, or send the check back.")
            if herr:
                out["error"] = herr
            elif is_hr_step:
                frappe.db.set_value("Work Management Payroll Check", pc.name, {"status": "GM Review",
                    "hr_approved_by": frappe.session.user, "hr_approved_at": frappe.utils.now()})
                frappe.db.commit()
                wmpc_mail(wmpc_people("gm", []), "Payroll check " + wmpc_label(pc) + " needs your approval",
                    "<p>HR (" + frappe.utils.escape_html(pc_me) + ") has approved payroll check <b>" +
                    frappe.utils.escape_html(wmpc_label(pc)) + "</b>: " + str(pc.worker_days) +
                    " worker-days, KES " + frappe.utils.fmt_money(pc.amount) + ", " + str(pc.dups_fixed) +
                    " duplicate day(s) fixed (KES " + frappe.utils.fmt_money(pc.amount_zeroed) + " zeroed).</p>")
                out["status"] = "GM Review"
            else:
                frappe.db.set_value("Work Management Payroll Check", pc.name, {"status": "Approved",
                    "gm_approved_by": frappe.session.user, "gm_approved_at": frappe.utils.now()})
                frappe.db.commit()
                wmpc_mail(wmpc_people("hr", []), "Payroll check " + wmpc_label(pc) + " approved: send to payroll",
                    "<p>The GM has approved payroll check <b>" + frappe.utils.escape_html(wmpc_label(pc)) +
                    "</b>. It can now be sent to payroll from the Payment screen.</p>")
                out["status"] = "Approved"

        elif action == "chk_send_back":
            serr = None
            mine = pc_hr or [f for f in pc.farms if f.farm in pc_fm]
            if pc.status in ("Sent", "Cancelled"):
                serr = "This check is " + pc.status + "."
            elif not mine:
                serr = "Only a reviewer of this check can send it back."
            elif not pc_reason:
                serr = "Say why it is being sent back."
            elif pc.status == "Approved" and frappe.db.sql("""SELECT 1 FROM `tabWork Actuals Employee`
                    WHERE payroll_check = %s AND IFNULL(payment_ref, '') != '' LIMIT 1""", (pc.name,)):
                serr = "Part of this check has already gone to payroll, so it cannot be sent back."
            if serr:
                out["error"] = serr
            else:
                wmpc_unstamp(pc)
                for f in pc.farms:
                    frappe.db.set_value("Work Management Payroll Check Farm", f.name, {"status": "Pending",
                        "approved_by": None, "approved_at": None}, update_modified=False)
                frappe.db.set_value("Work Management Payroll Check", pc.name, {"status": "Farm Review",
                    "sent_back_reason": pc_reason, "sent_back_by": frappe.session.user,
                    "sent_back_at": frappe.utils.now(), "hr_approved_by": None, "hr_approved_at": None,
                    "gm_approved_by": None, "gm_approved_at": None})
                wmpc_totals(pc)
                frappe.get_doc("Work Management Payroll Check", pc.name).add_comment("Comment",
                    "Sent back by " + pc_me + ": " + pc_reason)
                frappe.db.commit()
                wmpc_mail(wmpc_people("fm", [f.farm for f in pc.farms]) + wmpc_people("hr", []),
                    "Payroll check " + wmpc_label(pc) + " was sent back",
                    "<p>" + frappe.utils.escape_html(pc_me) + " sent payroll check <b>" +
                    frappe.utils.escape_html(wmpc_label(pc)) + "</b> back to the farm managers:</p><blockquote>" +
                    frappe.utils.escape_html(pc_reason) + "</blockquote><p>Every farm needs approving again.</p>")
                out["status"] = "Farm Review"

        elif action == "chk_close_sent":
            # Part of an Approved check went to payroll and the rest never can (a worker
            # no longer a task worker, no salary structure, a day outside every pay
            # week). Close it as Sent: the unsent days leave the check, are logged on
            # it, and turn up as late work for a top-up check.
            if not pc_hr:
                out["error"] = "Only HR or the GM can close a payroll check."
            elif pc.status != "Approved":
                out["error"] = "Only an Approved check can be closed as sent."
            elif not pc_reason:
                out["error"] = "Say why the rest of it is not being sent."
            else:
                cs_left = frappe.db.sql("""SELECT COUNT(*) n, COALESCE(SUM(amount), 0) a FROM `tabWork Actuals Employee`
                    WHERE payroll_check = %s AND IFNULL(payment_ref, '') = ''""", (pc.name,), as_dict=True)[0]
                wmpc_unstamp(pc)
                wmpc_totals(pc)
                frappe.db.set_value("Work Management Payroll Check", pc.name, {"status": "Sent", "sent_at": frappe.utils.now()})
                frappe.get_doc("Work Management Payroll Check", pc.name).add_comment("Comment",
                    "Closed as sent by " + pc_me + ": " + str(frappe.utils.cint(cs_left.n)) + " unsent worker-day(s), KES " +
                    frappe.utils.fmt_money(cs_left.a) + ", taken out for a top-up check. " + pc_reason)
                frappe.db.commit()
                out["status"] = "Sent"
                out["released"] = frappe.utils.cint(cs_left.n)

        elif action == "chk_cancel":
            if not pc_hr:
                out["error"] = "Only HR or the GM can cancel a payroll check."
            elif pc.status in ("Sent", "Cancelled"):
                out["error"] = "This check is " + pc.status + "."
            elif frappe.db.sql("""SELECT 1 FROM `tabWork Actuals Employee` WHERE payroll_check = %s
                                  AND IFNULL(payment_ref, '') != '' LIMIT 1""", (pc.name,)):
                out["error"] = "Part of this check has already gone to payroll, so it cannot be cancelled."
            elif not pc_reason:
                out["error"] = "Say why it is being cancelled."
            else:
                wmpc_unstamp(pc)
                frappe.db.set_value("Work Management Payroll Check", pc.name, "status", "Cancelled")
                frappe.get_doc("Work Management Payroll Check", pc.name).add_comment("Comment",
                    "Cancelled by " + pc_me + ": " + pc_reason)
                frappe.db.commit()
                out["status"] = "Cancelled"

        else:
            out["error"] = "unknown action: " + str(action)

    # ===== DASHBOARD (fast: grouped queries) =====
    else:
        out["error"] = "unknown action: " + str(action)

    # A check whose every worker-day has gone to payroll is Sent. Checked after any
    # send, so the Payment screen never has to remember to say so.
    if PC_DT and not out.get("error") and action in ("pay_submit", "pay_worker_submit", "pay_bulk_submit"):
        for pcs in frappe.db.sql("""SELECT c.name FROM `tabWork Management Payroll Check` c
                WHERE c.status = 'Approved'
                  AND EXISTS (SELECT 1 FROM `tabWork Actuals Employee` w1 WHERE w1.payroll_check = c.name)
                  AND NOT EXISTS (SELECT 1 FROM `tabWork Actuals Employee` w2 WHERE w2.payroll_check = c.name
                                  AND IFNULL(w2.payment_ref, '') = '')""", as_dict=True):
            frappe.db.set_value("Work Management Payroll Check", pcs.name, {"status": "Sent", "sent_at": frappe.utils.now()})
        frappe.db.commit()

    if action in ("pay_worker_submit", "pay_bulk_submit"):
        frappe.db.sql("SELECT RELEASE_LOCK('wmpay-send')")

    return out


# ==================================================================
# Payroll linkage: raising the Additional Salary a payment run sends to payroll,
# and reacting once payroll actually pays it (Salary Slip submitted) or the run
# is withdrawn (payment cancelled). Kept as real functions, not sandboxed
# actions, since doc_events call them directly rather than through wm_payment().
# ==================================================================

def raise_additional_salary_for_payment(payment_name, employee, employee_name, salary_component, amount, payroll_date, company):
    """Create + submit the Additional Salary a payment run is sent to payroll for.
    Raises on failure (mirrors Additional Salary.validate(), which the preconditions
    checked in pay_worker_submit/pay_bulk_submit are meant to already satisfy) so the
    caller's transaction rolls back rather than leaving a payment with no payroll
    record behind it."""
    from hrms.payroll.doctype.salary_structure_assignment.salary_structure_assignment import (
        get_employee_currency,
    )

    asal = frappe.new_doc("Additional Salary")
    asal.employee = employee
    asal.employee_name = employee_name
    asal.salary_component = salary_component
    asal.amount = amount
    asal.payroll_date = payroll_date
    asal.company = company
    asal.currency = get_employee_currency(employee)
    asal.ref_doctype = "Work Management Payment"
    asal.ref_docname = payment_name
    asal.flags.ignore_permissions = True
    asal.insert(ignore_permissions=True)
    asal.submit()
    return asal.name


def release_sent_week_for_topup(employee, salary_component, payroll_date, week_from, week_to):
    """Late work for a week that was already sent to payroll.

    hrms allows one Additional Salary per employee, component and payroll date
    when the component overwrites the structure amount, so actuals confirmed
    after their week went to payroll could never be sent for that week's own
    pay date. Instead of a second line, the week is re-sent whole: the earlier
    run's Additional Salary is cancelled, which (on_additional_salary_cancel)
    drops the still-Unpaid run and frees its rows, and the caller then sends
    the freed rows together with the late ones as one payment for the same
    date.

    Only done while payroll has not consumed it. Returns {"released": [runs]}
    when the caller should re-read the week, {"block": reason} when the week
    cannot be reopened, or {} when nothing conflicts. Does not commit: the
    caller holds a savepoint taken before this call and rolls back to it if
    the re-send fails, which restores the cancelled Additional Salary and run.
    """
    existing = frappe.db.get_all("Additional Salary",
        filters={"employee": employee, "salary_component": salary_component,
                 "payroll_date": payroll_date, "docstatus": 1,
                 "overwrite_salary_structure_amount": 1},
        fields=["name", "ref_doctype", "ref_docname"])
    if not existing:
        return {}
    released = []
    for a in existing:
        if a.ref_doctype != "Work Management Payment" or not a.ref_docname:
            return {"block": ("Additional Salary " + a.name + " for " + salary_component + " on "
                              + str(payroll_date) + " was not raised by Work Management; "
                              "send this work with a later end date")}
        slip = frappe.db.sql("""
            SELECT ss.name FROM `tabSalary Detail` sd
            INNER JOIN `tabSalary Slip` ss ON ss.name = sd.parent
            WHERE sd.additional_salary = %s AND ss.docstatus = 1 LIMIT 1
        """, (a.name,), as_dict=True)
        if slip:
            return {"block": ("this week was already paid through payroll (Salary Slip "
                              + slip[0].name + "); send the late work with a later end date")}
        run = frappe.db.get_value("Work Management Payment", a.ref_docname,
            ["workflow_state", "period_from", "period_to"], as_dict=True)
        if not run or run.workflow_state != "Unpaid":
            return {"block": ("payment " + a.ref_docname + " for this week is "
                              + ((run.workflow_state if run else None) or "missing")
                              + "; send the late work with a later end date")}
        # re-sending frees every row the earlier run held, so they must all fall
        # inside the window being sent now, or some would be left unsent
        if ((run.period_from and str(run.period_from) < str(week_from))
                or (run.period_to and str(run.period_to) > str(week_to))):
            return {"block": ("payment " + a.ref_docname + " covers " + str(run.period_from)
                              + " to " + str(run.period_to) + ", wider than "
                              + str(week_from) + " to " + str(week_to)
                              + "; send the whole of that range")}
        released.append(a)
    for a in released:
        asal = frappe.get_doc("Additional Salary", a.name)
        asal.flags.ignore_permissions = True
        asal.cancel()
    return {"released": [a.ref_docname for a in released]}


def _stamp_actuals_paid_for_payment(payment_name):
    """Stamp every actuals row a payment run covers as paid, and flip the parent
    Actuals to paid once all of its payable rows are. Was pay_mark_paid's job;
    now runs once payroll has actually submitted the Salary Slip carrying the
    run's Additional Salary -- see on_salary_slip_submit()."""
    cur = frappe.db.get_value("Work Management Payment", payment_name,
        ["period_from", "period_to"], as_dict=True)
    if not cur:
        return
    pfrom = cur.period_from
    pto = cur.period_to
    # resolve the child doctype of the 'lines' table field (name varies)
    line_dt = None
    pmeta = frappe.get_meta("Work Management Payment")
    for f in pmeta.fields:
        if f.fieldtype == "Table" and f.fieldname == "lines":
            line_dt = f.options
    # ONLY THE ROWS THIS RUN CARRIED (fixed 2026-11-12). It used to stamp every
    # confirmed unpaid row the line's employee had in the period, so work
    # approved after the run was built was marked Paid without being paid. A
    # send writes payment_ref onto exactly the rows it carries; those are the
    # rows this run pays. A run sent before that existed falls back to its lines'
    # own actuals record, worker and dates -- never the worker's whole period.
    touched_parents = {}
    payrows = frappe.db.sql("""
        SELECT we.name rowname, we.parent parent FROM `tabWork Actuals Employee` we
        WHERE we.payment_ref = %s AND IFNULL(we.paid,0) = 0
    """, (payment_name,), as_dict=True)
    if not payrows and line_dt:
        for ln in frappe.db.get_all(line_dt, filters={"parent": payment_name},
                fields=["employee", "actuals", "work_from", "work_to"]):
            if not (ln.employee and ln.actuals):
                continue
            payrows = payrows + frappe.db.sql("""
                SELECT we.name rowname, we.parent parent
                FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                WHERE we.parent = %s AND we.employee = %s AND ac.workflow_state = 'CONFIRMED'
                  AND IFNULL(we.paid,0) = 0 AND IFNULL(we.payment_ref,'') = ''
                  AND IFNULL(we.count_in_payroll,0) = 1
                  AND we.work_date BETWEEN %s AND %s
            """, (ln.actuals, ln.employee, ln.work_from or pfrom or "2000-01-01",
                  ln.work_to or pto or "2999-12-31"), as_dict=True)
    for pr in payrows:
        frappe.db.set_value("Work Actuals Employee", pr.rowname, "paid", 1, update_modified=False)
        frappe.db.set_value("Work Actuals Employee", pr.rowname, "payment_ref", payment_name, update_modified=False)
        touched_parents[pr.parent] = 1
    # flip parent Actuals paid=1 only when ALL its payable rows are now paid
    for parent in touched_parents:
        unpaid = frappe.db.sql("""
            SELECT COUNT(*) c FROM `tabWork Actuals Employee`
            WHERE parent=%s AND IFNULL(count_in_payroll,0)=1 AND amount>0 AND IFNULL(paid,0)=0
        """, (parent,), as_dict=True)
        if unpaid and unpaid[0].c == 0:
            frappe.db.set_value("Work Management Actuals", parent, "paid", 1, update_modified=False)
            frappe.db.set_value("Work Management Actuals", parent, "payment_ref", payment_name, update_modified=False)


def _unstamp_actuals_paid_for_payment(payment_name):
    """The reverse of _stamp_actuals_paid_for_payment(): a run only reaches
    Paid (and only becomes cancellable) after its rows were stamped, so
    cancelling one must free those same rows again -- clearing payment_ref too,
    not just paid, since a row still carrying a payment_ref can never be sent
    again (every send excludes rows where payment_ref is already set).

    Also clears the review stamps (custom_reviewed*): a cancelled run's work is
    exactly as unclaimed as if it had never been sent -- pay_run_withdraw() and
    on_additional_salary_cancel()'s own draft cleanup both reset review the
    same way, and a row cannot be left looking "already reviewed" for a claim
    that no longer exists, hiding it from the unreviewed_amt KPI and skipping a
    real re-review the next time it is sent."""
    rows = frappe.db.get_all("Work Actuals Employee",
        filters={"payment_ref": payment_name}, fields=["name", "parent"])
    touched_parents = {}
    for r in rows:
        frappe.db.set_value("Work Actuals Employee", r.name, "paid", 0, update_modified=False)
        frappe.db.set_value("Work Actuals Employee", r.name, "payment_ref", None, update_modified=False)
        frappe.db.set_value("Work Actuals Employee", r.name, "custom_reviewed", 0, update_modified=False)
        frappe.db.set_value("Work Actuals Employee", r.name, "custom_reviewed_by", None, update_modified=False)
        frappe.db.set_value("Work Actuals Employee", r.name, "custom_reviewed_at", None, update_modified=False)
        touched_parents[r.parent] = 1
    for parent in touched_parents:
        if frappe.db.get_value("Work Management Actuals", parent, "payment_ref") == payment_name:
            frappe.db.set_value("Work Management Actuals", parent, "paid", 0, update_modified=False)
            frappe.db.set_value("Work Management Actuals", parent, "payment_ref", None, update_modified=False)


def on_salary_slip_submit(doc, method=None):
    """doc_events: Salary Slip.on_submit. A run is only actually Paid once payroll
    submits the Salary Slip carrying its Additional Salary -- not when it was sent.
    Runs for every Salary Slip submission; does nothing when none of its earning
    rows trace back to one of ours.

    Only workflow_state moves -- docstatus stays 0, by design, for this whole
    chain (see CHAIN_ENDS's comment for "Work Management Payment"): a
    generated workflow's states never leave doc_status 0, so keeping this in
    step with the workflow means "Paid" is never a real Frappe submission
    either. Cancelling a Paid run is a plain-save workflow action (its own
    "Cancel", reachable from the Actions dropdown like every other stage in
    this app), reacted to in on_payment_update() below, not a real
    doc.cancel()."""
    as_names = list({row.additional_salary for row in (doc.get("earnings") or []) + (doc.get("deductions") or [])
                      if row.get("additional_salary")})
    if not as_names:
        return
    rows = frappe.db.get_all("Additional Salary",
        filters={"name": ["in", as_names], "ref_doctype": "Work Management Payment"},
        fields=["name", "ref_docname"])
    slip_amt = {}
    for row in doc.get("earnings") or []:
        if row.get("additional_salary"):
            slip_amt[row.additional_salary] = slip_amt.get(row.additional_salary, 0) + frappe.utils.flt(row.amount)
    for r in rows:
        pay_name = r.ref_docname
        if not pay_name:
            continue
        state = frappe.db.get_value("Work Management Payment", pay_name, "workflow_state")
        # only an Unpaid run becomes Paid: a Cancelled run stays cancelled (2026-11-12)
        if state != "Unpaid":
            continue
        # THE MONEY MUST AGREE (2026-11-12): the slip's line, the Additional Salary and
        # the rows the run carried. If payroll prorated or edited the line, the rows are
        # not stamped paid on a short payment -- the mismatch is logged for HR instead.
        as_amt = frappe.utils.flt(frappe.db.get_value("Additional Salary", r.name, "amount"))
        rows_amt = frappe.utils.flt(frappe.db.sql("""SELECT COALESCE(SUM(amount), 0) FROM `tabWork Actuals Employee`
                                        WHERE payment_ref = %s""", (pay_name,))[0][0])
        paid_amt = frappe.utils.flt(slip_amt.get(r.name, as_amt))
        if abs(paid_amt - as_amt) > 1 or (rows_amt and abs(rows_amt - as_amt) > 1):
            if frappe.db.exists("DocType", "Work Management Payroll Check Fix"):
                fx = frappe.new_doc("Work Management Payroll Check Fix")
                fx.kind = "slip mismatch"
                fx.employee = frappe.db.get_value("Work Management Payment", pay_name, "employee")
                fx.payments = pay_name + ", " + r.name + ", " + doc.name
                fx.amount_before = as_amt
                fx.fixed_by = frappe.session.user
                fx.fixed_at = frappe.utils.now()
                fx.reason = ("Salary Slip " + doc.name + " paid " + str(paid_amt) + " on Additional Salary " +
                             r.name + " (" + str(as_amt) + "); the run's rows total " + str(rows_amt) +
                             ". Rows not stamped paid; HR to reconcile.")
                fx.insert(ignore_permissions=True)
            continue
        frappe.db.set_value("Work Management Payment", pay_name, "workflow_state", "Paid", update_modified=False)
        frappe.db.set_value("Work Management Payment", pay_name, "accounts_approved_by", frappe.session.user, update_modified=False)
        frappe.db.set_value("Work Management Payment", pay_name, "accounts_approval_date", frappe.utils.today(), update_modified=False)
        frappe.db.set_value("Work Management Payment", pay_name, "custom_accounts_approved_at", frappe.utils.now(), update_modified=False)
        _stamp_actuals_paid_for_payment(pay_name)
    # no explicit commit here: this hook runs inside the Salary Slip's own
    # submit transaction, which commits once that finishes


def _revert_actuals_paid_to_sent(payment_name):
    """Half of _unstamp_actuals_paid_for_payment(): drops paid back to 0 but
    leaves payment_ref alone. Used when the RUN document itself still stands
    and still legitimately claims this work -- only the slip that paid it was
    withdrawn (on_salary_slip_cancel()), or its Additional Salary was cancelled
    directly while it was Paid (on_additional_salary_cancel()) -- so the rows
    go back to "sent, not yet paid", not fully freed. Clearing payment_ref
    here would let the same work be sent again on a second run while this one
    still exists, double-claiming it."""
    rows = frappe.db.get_all("Work Actuals Employee",
        filters={"payment_ref": payment_name, "paid": 1}, fields=["name", "parent"])
    touched_parents = {}
    for r in rows:
        frappe.db.set_value("Work Actuals Employee", r.name, "paid", 0, update_modified=False)
        touched_parents[r.parent] = 1
    for parent in touched_parents:
        if frappe.db.get_value("Work Management Actuals", parent, "payment_ref") == payment_name:
            frappe.db.set_value("Work Management Actuals", parent, "paid", 0, update_modified=False)


def _revert_payment_to_unpaid(pay_name):
    """A Paid run going back to Unpaid: undoes on_salary_slip_submit()'s own
    writes and frees its rows back to "sent, not yet paid" -- not Cancelled,
    which is a person's deliberate call (on_payment_update()), not an
    automatic reaction to the run's payroll backing coming loose. Shared by
    on_salary_slip_cancel() and on_additional_salary_cancel()."""
    frappe.db.set_value("Work Management Payment", pay_name, "workflow_state", "Unpaid", update_modified=False)
    frappe.db.set_value("Work Management Payment", pay_name, "accounts_approved_by", None, update_modified=False)
    frappe.db.set_value("Work Management Payment", pay_name, "accounts_approval_date", None, update_modified=False)
    frappe.db.set_value("Work Management Payment", pay_name, "custom_accounts_approved_at", None, update_modified=False)
    _revert_actuals_paid_to_sent(pay_name)


def on_salary_slip_cancel(doc, method=None):
    """doc_events: Salary Slip.on_cancel. The reverse of on_salary_slip_submit():
    if the slip that made a run Paid is withdrawn, the run cannot go on claiming
    Paid -- payroll no longer stands behind it. The Additional Salary itself is
    left alone (hrms does not cancel it just because the slip carrying it was
    cancelled, and neither do we -- it is still legitimately owed, and stays
    available for a corrected slip to pick up), so the run goes back to Unpaid,
    a draft again, exactly where it sat before any slip touched it -- not
    Cancelled, which is a person's own deliberate action (on_payment_update())."""
    as_names = list({row.additional_salary for row in (doc.get("earnings") or []) + (doc.get("deductions") or [])
                      if row.get("additional_salary")})
    if not as_names:
        return
    rows = frappe.db.get_all("Additional Salary",
        filters={"name": ["in", as_names], "ref_doctype": "Work Management Payment"},
        fields=["name", "ref_docname"])
    for r in rows:
        pay_name = r.ref_docname
        if not pay_name:
            continue
        state = frappe.db.get_value("Work Management Payment", pay_name, "workflow_state")
        if state != "Paid":
            continue
        _revert_payment_to_unpaid(pay_name)


def on_payment_update(doc, method=None):
    """doc_events: Work Management Payment.on_update. Reacts to workflow_state
    actually reaching Cancelled -- which happens via a plain save, since this
    doctype's docstatus never leaves 0 by design (see the comment on
    CHAIN_ENDS["Work Management Payment"]): the generated workflow's own
    Cancel action, from either Unpaid or the terminal Paid, is reachable from
    the same Actions dropdown every other stage in this app uses, and
    apply_workflow() resolves a same-doc_status move as doc.save(), never
    doc.cancel() -- so on_cancel is not where this belongs.

    Cancelling a run must take its Additional Salary with it, so payroll
    never keeps paying out a run this app no longer considers valid, and must
    free whatever actuals rows it had claimed -- Cancelled is a person's
    deliberate, final call on this run, not a temporary state, so the rows
    are freed outright (_unstamp_actuals_paid_for_payment), not just reverted
    to "sent, not yet paid" the way a Paid run losing its slip is
    (_revert_actuals_paid_to_sent, on_salary_slip_cancel())."""
    if not doc.has_value_changed("workflow_state") or doc.workflow_state != "Cancelled":
        return
    # a draft or submitted Salary Slip still carrying this run's Additional Salary
    # would keep paying it after the rows are freed and re-sent (2026-11-12)
    held = frappe.db.sql("""
        SELECT ss.name FROM `tabSalary Detail` sd
        INNER JOIN `tabSalary Slip` ss ON ss.name = sd.parent
        INNER JOIN `tabAdditional Salary` a ON a.name = sd.additional_salary
        WHERE a.ref_doctype = %s AND a.ref_docname = %s AND ss.docstatus < 2 LIMIT 1
    """, (doc.doctype, doc.name))
    if held:
        frappe.throw(frappe._("Salary Slip {0} still carries this run. Remove it from that slip (or cancel the "
            "slip) before cancelling the run.").format(held[0][0]))
    for asr in frappe.db.get_all("Additional Salary",
            filters={"ref_doctype": doc.doctype, "ref_docname": doc.name, "docstatus": 1}):
        as_doc = frappe.get_doc("Additional Salary", asr.name)
        as_doc.flags.ignore_permissions = True
        as_doc.cancel()
    _unstamp_actuals_paid_for_payment(doc.name)


def on_additional_salary_cancel(doc, method=None):
    """doc_events: Additional Salary.on_cancel. The reverse direction of
    on_payment_update() -- an Additional Salary can be cancelled directly
    (its own standard Desk "Cancel"), and the run that raised it must not be
    left claiming Paid, or sitting Unpaid, against payroll that no longer
    exists. Checked by workflow_state, not docstatus: this doctype's
    docstatus never leaves 0 (see on_payment_update())."""
    if doc.ref_doctype != "Work Management Payment" or not doc.ref_docname:
        return
    state = frappe.db.get_value("Work Management Payment", doc.ref_docname, "workflow_state")
    if state is None or state == "Cancelled":
        # already gone, or already handled by on_payment_update() cancelling
        # this same Additional Salary from the other direction
        return
    if state == "Paid":
        _revert_payment_to_unpaid(doc.ref_docname)
    else:
        # still a draft "sent, not yet paid" run -- same cleanup as
        # pay_run_withdraw(): clear the stamps and drop the draft
        rows = frappe.db.get_all("Work Actuals Employee",
            filters={"payment_ref": doc.ref_docname, "paid": 0}, pluck="name")
        for rn in rows:
            frappe.db.set_value("Work Actuals Employee", rn, "payment_ref", None, update_modified=False)
            frappe.db.set_value("Work Actuals Employee", rn, "custom_reviewed", 0, update_modified=False)
            frappe.db.set_value("Work Actuals Employee", rn, "custom_reviewed_by", None, update_modified=False)
            frappe.db.set_value("Work Actuals Employee", rn, "custom_reviewed_at", None, update_modified=False)
        frappe.delete_doc("Work Management Payment", doc.ref_docname, ignore_permissions=True, force=True)
